	public double ReimburseParker(Map<String, String> objDictionary) 
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		// Login As Admin
		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver(); // driver.quit();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		// Navigate to user page
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users", "Local");
		clsCommonWeb.SENTRYLINK_SearchUserByOnApprovedUserPage(objDictionary, driver, "parker");
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strFirstName = (strUniqueId + strMunicipality.replace(" ", "").replace(",", "")+ "parker, parker").toLowerCase();
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Approved Users", "{LinkExists} " + strFirstName, 30);
		objDictionary.put("strWaitForPageLoad", "False");
		clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", strFirstName, 1);
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "User", "{TextFieldExists} User~Reimburse Amount", 180);
		objDictionary.put("strWaitForPageLoad", "True");
		String strCurrentAccountBalance = clsCommonWeb.StoreText(objDictionary, driver, "User", "Account Balance", 1,"strCurrentAccountBalance");
		// Populate Reimburse Amount > $20.00
		clsCommonWeb.PopulateAction(objDictionary, driver, "User", "Populate Reimburse Amount", "{T} Reimburse Amount","101.00");
		clsCommonWeb.ClickButton(objDictionary, driver, "User", "Reimburse Funds", 1, "Local");
		// Validate the Current Account Balance didn't change
		clsCommonWeb.VerificationPointText(objDictionary, driver, "User", "Account Balance", 1, "Value",strCurrentAccountBalance);
		// Populate Reimburse Amount < $20.00
		clsCommonWeb.PopulateAction(objDictionary, driver, "User", "Populate Reimburse Amount", "{T} Reimburse Amount","20.00");
		objDictionary.put("strWaitForPageLoad", "False");
		clsCommonWeb.ClickButton(objDictionary, driver, "User", "Reimburse Funds", 1, "Local");
		// Validate Account Balance
		String strReimburseAmount = objDictionary.get("strReimburseAmount").replace("$", "");
		Double dblNewAccountBalance = Double.parseDouble(strCurrentAccountBalance.replace("$", ""))+ Double.parseDouble(strReimburseAmount);
		DecimalFormat dFormat = new DecimalFormat("$#.00");// "$#.##" //$#.00
		clsCommonWeb.ClickButton(objDictionary, driver, "User", "Reimburse Funds", 1, "Local");
		objDictionary.put("strWaitForPageLoad", "True");
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "User", "{TextExists} User~Account Balance", 60);
		clsCommonWeb.VerificationPointText(objDictionary, driver, "User", "Account Balance", 1, "Value",dFormat.format(dblNewAccountBalance));
		driver.quit();
		objDictionary.remove("strCurrentParkingAccountBalance");
		objDictionary.put("strCurrentParkingAccountBalance", Double.toString(dblNewAccountBalance));
		return dblNewAccountBalance;
	}
	public String SENTRYLINK_GetUserName(Map<String, String> objDictionary,String strRole)
	{
    	String strEnvironment = objDictionary.get("strEnvironment");
    	if(strEnvironment.equals("PROD"))
		{
			if(strRole.equals("admin"))
			{
				return "darinadmin@mpspark.com";
			}
//			else
//			{
//				return "Darin@mpspark.com";
//			}
		}
    	String strUniqueId = objDictionary.get("strUniqueId");if(strUniqueId == null) {strUniqueId = "";}
        String strMunicipality = objDictionary.get("strMunicipality");if(strMunicipality == null) {strMunicipality = "";}
        if(strRole.equals("parking_enforcement_officer")){strRole = "peo";}
  		return strUniqueId+strMunicipality.replace(" ","").replace(",", "")+strRole.replace(" ","")+"@gmail.com";
	}
	public String SENTRYLINK_CheckIfUserExists(Map<String, String> objDictionary, String strRole) 
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		HttpConnections clsHttpConnections = new HttpConnections();
		// Check if User Exists
		String strUserName = clsCommonWeb.SENTRYLINK_GetUserName(objDictionary, strRole).toLowerCase();
		String strPassword = clsCommonWeb.SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		String strJsonUserId = "";
		if(strRole.equals("admin")){strJsonUserId = objDictionary.get("strJsonAdminId");}
		else{strJsonUserId = objDictionary.get("strJsonUserId");}
		if(strJsonUserId == null)
		{
			strJsonUserId = clsHttpConnections.StoreJsonUserId(objDictionary, strUserName, strPassword);
		}
		if (strJsonUserId.equals("")) {return "False";}return "True";
	}
	public void SENTRYLINK_CreateUser(Map<String, String> objDictionary, String strRole) 
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		String strUserExists = clsCommonWeb.SENTRYLINK_CheckIfUserExists(objDictionary, strRole);
		if (strUserExists.equals("False")) 
		{
			String strBrowser = objDictionary.get("strBrowser");
			String strRemotePath = objDictionary.get("strRemotePath");
			String strMunicipality = objDictionary.get("strMunicipality");
			String strUniqueId = objDictionary.get("strUniqueId");
			String strUserName = clsCommonWeb.SENTRYLINK_GetUserName(objDictionary, strRole);
			String strPassword = clsCommonWeb.SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
			String strFirstName = strUniqueId + strMunicipality.replace(" ", "").replace(",", "");
			String strLastName = strRole.replace(" ", "");
			threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
			WebDriver driver = getDriver(); // driver.quit();
			clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "New User", 1, "Local");
			String strObjectNames = "{T} Email|{T} First name|{T} Last name|{T} Password|{T} Password confirmation|{L} Municipality";
			String strObjectValues = strUserName + "|" + strFirstName + "|" + strLastName + "|" + strPassword + "|"+ strPassword + "|" + strMunicipality;
			clsCommonWeb.PopulateAction(objDictionary, driver, "Create A New User", "Populate Create A New User",strObjectNames, strObjectValues);
			clsCommonWeb.ClickButton(objDictionary, driver, "Create A New User", "Save User", 1, "Local");
			clsCommonWeb.VerificationPointText(objDictionary, driver, "Approved Users", "SuccessAlertMessage", 1,"Contains", "User was successfully created.");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName);
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Edit", 1);
			if (strRole.equals("concierge")) {strRole = "Parker";}
			clsCommonWeb.PopulateAction(objDictionary, driver, "EditUser", "Populate User Role", "{L} User Roles",strRole);
			clsCommonWeb.ClickButton(objDictionary, driver, "EditUser", "Add", 1, "Local");
			clsCommonWeb.ClickButton(objDictionary, driver, "EditUser", "Save User", 1, "Local");
			clsCommonWeb.VerificationPointText(objDictionary, driver, "Edit Users", "UpdatedTheUser", 1, "Contains","Updated the User.");
			driver.quit();
		}
	}
