	public void SENTRYLINK_OpenLoginPage(Map<String, String> objDictionary, WebDriver driver) 
	{
		String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
		System.out.println(strMethodName);
		Reporter.log("<font color='orange'>     " + strMethodName + "</font>");
		String strURL = GetPageURL(objDictionary, driver, "Login");
		// Work Around
		String strEnvironment = objDictionary.get("strEnvironment");
		switch (strEnvironment) 
		{
			case "QA":
				strURL = "https://launchpad.quality.sentry-link.com/users/login";
				break;
			case "SG":
				strURL = "https://launchpad.staging.sentry-link.com/users/login";
				break;
			case "PROD":
				strURL = "https://sentrylink.mpspark.com/users/login";
				break;
			default:
				UpdateErrorMessageWithPivotalData(objDictionary, driver,"The URL has not been added for the (Login) with Environment (" + strEnvironment + ")-"+ strMethodName,"Local");
		}
		try 
		{driver.get(strURL);} // {driver.get(strURL);driver.manage().window().maximize();}
		catch (Exception e) {UpdateErrorMessageWithPivotalData(objDictionary, driver,"Unable to open login page-(" + e + ")-" + strMethodName, "Local");}
	}
