	public void SENTRYLINK_GlobalAdminLoginIn(Map<String, String> objDictionary, WebDriver driver)
	{
		String strMethondName = new Object() {}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     " + strMethondName + "</font>");
		CommonWeb clsCommonWeb = new CommonWeb();
		String strEnvironment = objDictionary.get("strEnvironment");
		// Login as Global Admin
		String strPassword = "";
		if(strEnvironment.equals("PROD"))
		{
			strPassword = SENTRYLINK_GetPassword(objDictionary, "darinadmin@mpspark.com", "admin");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password","darinadmin@mpspark.com|" + strPassword);
		}
		else
		{
			strPassword = SENTRYLINK_GetPassword(objDictionary, "darin@mpspark.com", "admin");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password","darin@mpspark.com|" + strPassword);
		}
		clsCommonWeb.ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
		switch (strActualWaitValue)
		{
			case "InvalidEmailOrPassword":
				UpdateErrorMessageWithPivotalData(objDictionary, driver, "Invalid Email Or Password-" + strMethondName,"Local");
				break;
			case "YouHaveOneMoreAttemptBeforeYourAccountIsLocked":
				UpdateErrorMessageWithPivotalData(objDictionary, driver,"You Have One More Attempt Before Your Account Is Locked-" + strMethondName, "Local");
				break;
			case "WorkerSubsystem":
				UpdateErrorMessageWithPivotalData(objDictionary, driver,"Worker Subsystem error, check Sidekiq id down (" + strEnvironment + ")-" + strMethondName,"Local");
				break;
			case "YourAccountIsLocked":
				UpdateErrorMessageWithPivotalData(objDictionary, driver, "Your Accoutn Is Locked-" + strMethondName,"Local");
				break;
			case "YourAccountHasExpiredDueToInactivity":
				UpdateErrorMessageWithPivotalData(objDictionary, driver,"Your Accoutn Has Expired Due To Inactivity-" + strMethondName, "Local");
				break;
		}
	}

	public void SENTRYLINK_AdminLoginIn(Map<String, String> objDictionary, WebDriver driver) 
	{
		String strMethondName = new Object() {
		}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     " + strMethondName + "</font>");
		CommonWeb clsCommonWeb = new CommonWeb();
		String strEnvironment = objDictionary.get("strEnvironment");
		VerificationPointPage(objDictionary, driver, "Login", "Exists");
		String strUserName = "darin@mpspark.com";
		String strRole = "admin";
		SENTRYLINK_UserLoginIn(objDictionary, driver, strRole);
		if (strActualWaitValue.equals("InvalidEmailOrPassword")|| strActualWaitValue.equals("YouHaveOneMoreAttemptBeforeYourAccountIsLocked")) 
		{
			String strPassword = SENTRYLINK_GetPassword(objDictionary, strUserName, strRole);
			PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password",strUserName + "|" + strPassword);
			ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
			String strPageName = GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToApprovedUsers(objDictionary, driver, strPageName);
			clsCommonWeb.SENTRYLINK_UpdateUserPasswordOrCreateNewUser(objDictionary, driver, strRole);
		}
		else if (strActualWaitValue.equals("WorkerSubsystem")) 
		{UpdateErrorMessageWithPivotalData(objDictionary, driver,"Worker Subsystem error, check Sidekiq id down (" + strEnvironment + ")-" + strMethondName,"Local");}
		else if (strActualWaitValue.equals("YourAccountIsLocked")) 
		{
			// Unlock Account
			String strPassword = SENTRYLINK_GetPassword(objDictionary, "darin@mpspark.com", strRole);
			PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password","darin@mpspark.com|" + strPassword);
			ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			strUserName = clsCommonWeb.SENTRYLINK_GetUserName(objDictionary, "admin");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName.toLowerCase());
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Unlock", 1);
			String strVariableName = clsCommonWeb.StoreText(objDictionary, driver, "Approved Users", "UserName", 1,"strVarUserName");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", strVariableName, 1);
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Log Out", 1);
		} 
		else if (strActualWaitValue.equals("YourAccountHasExpiredDueToInactivity")) 
		{
			String strPassword = SENTRYLINK_GetPassword(objDictionary, strUserName, strRole);
			PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password",strUserName + "|" + strPassword);
			ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
			// Navigate to User
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			strUserName = clsCommonWeb.SENTRYLINK_GetUserName(objDictionary, "admin");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName.toLowerCase());
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Unlock", 1);
			String strVariableName = clsCommonWeb.StoreText(objDictionary, driver, "Approved Users", "UserName", 1,"strVarUserName");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", strVariableName, 1);
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Log Out", 1);
			strPassword = SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
			switch (strEnvironment)
			{
				case "QA":
					objDictionary.put("https://sentrylink.quality.sentry-link.com/users/login","Login");
				case "SG":
					objDictionary.put("https://sentrylink.staging.sentry-link.com/users/login","Login");
				case "PROD":
					objDictionary.put("https://sentrylink.mpspark.com/users/login","Login");
			} 
			PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password",strUserName.toLowerCase() + "|" + strPassword);
			ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
		}
	}
	public void SENTRYLINK_UpdateUserPasswordOrCreateNewUser(Map<String, String> objDictionary, WebDriver driver,String strRole) 
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		Database clsDatabase = new Database();
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strEnvironment = objDictionary.get("strEnvironment");
		String strObjectNames = "";
		String strObjectValues = "";
		String strUserName = strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + strRole.replace(" ", "")+ "@gmail.com";
		String strPassword = SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		if (!strCurrentPageName.equals("Approved Users"))
		{
			clsCommonWeb.ClickLink(objDictionary, driver, "Municipalities", "Approved User", 1);
		}
		clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName.toLowerCase());
		clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
		String strCondition = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Approved Users", "Edit", 1,"Exists", "");
		if (strCondition.equals("True")) 
		{
			// Update Password
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Edit", 1);
			clsCommonWeb.ClickButton(objDictionary, driver, "Edit User", "Show/Hide Password Fields", 1, "Local");
			// Loop
			do 
			{
				int intCurrentVersion = Integer.parseInt(strPassword.substring(strPassword.indexOf(strRole) + strRole.length(), strPassword.length() - 1));
				int intNewVersion = intCurrentVersion + 1;
				String strNewPassword = strPassword.replace(Integer.toString(intCurrentVersion),Integer.toString(intNewVersion));
				clsCommonWeb.PopulateAction(objDictionary, driver, "Edit User", "Populate Passwords","{T} Password|{T} Password Confirmation", strNewPassword + "|" + strNewPassword);
				clsCommonWeb.ClickButton(objDictionary, driver, "Edit User", "Save User", 1, "Local");
				strCondition = clsCommonWeb.ConditionalStepText(objDictionary, driver, "Edit User","Failed to update the User.", 1, "Exists", "");
				strPassword = strNewPassword;
			} while (strCondition.equals("True"));
			String strSQL = "Update \"UNIQUE\" SET \"Password\" = '" + strPassword + "' where \"Environment\" = '"+ strEnvironment + "' and \"UserId\" = '" + strUserName.toLowerCase() + "'";
			clsDatabase.DATABASE_Update(objDictionary, strSQL);
		} 
		else 
		{
			// Add New User
			ClickButton(objDictionary, driver, "Approved Users", "New User", 1, "Local");
			strObjectNames = "{T} Email|{T} First name|{T} Last name|{T} Password|{T} Password confirmation|{L} Municipality";
			strUserName = strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + strRole.replace(" ", "")+ "@gmail.com";
			strPassword = strUniqueId + strMunicipality.replace(", ", "").replace(" ", "") + strRole.replace(" ", "")+ "1";
			strObjectValues = strUserName + "|" + strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + "|"+ strRole.replace(" ", "") + "|" + strPassword + "|" + strPassword + "|" + strMunicipality;
			PopulateAction(objDictionary, driver, "Create A New User", "Populate Create A New User", strObjectNames,strObjectValues);
			ClickButton(objDictionary, driver, "Create A New User", "Save User", 1, "Local");
			VerificationPointText(objDictionary, driver, "Approved Users", "SuccessAlertMessage", 1, "Contains","User was successfully created.");
			System.out.println(driver.getCurrentUrl());
			SENTRYLINK_SearchUserByOnApprovedUserPage(objDictionary, driver, strRole);
			ClickLink(objDictionary, driver, "Approved Users", "Edit", 1);
			VerificationPointListbox(objDictionary, driver, "EditUser", "User Roles", 1, "Item Order","|admin|api_application|automated_process|coin_collector|court_clerk|csr|lot_security|municipality_admin|parker|parking_enforcement_officer|read_only|session_voider|violation_monitor");
			PopulateAction(objDictionary, driver, "EditUser", "Populate User Role", "{L} User Roles", strRole);
			ClickButton(objDictionary, driver, "EditUser", "Add", 1, "Local");
			ClickButton(objDictionary, driver, "EditUser", "Save User", 1, "Local");
			ClickLink(objDictionary, driver, "EditUser", "Municipalities", 1);
		}
		ClickLink(objDictionary, driver, "Municipalities", "~strVarUserName~", 1);
		ClickLink(objDictionary, driver, "Municipalities", "Log Out", 1);
		if (strEnvironment.equals("PROD")) 
		{
			ClearBrowserCache(driver);
			driver.navigate().refresh();
			PopulateAction(objDictionary, driver, "Login-AfterLogout", "Populate Login", "{T} Email|{T} Password",strUserName + "|" + strPassword);
			ClickButton(objDictionary, driver, "Login-AfterLogout", "Sign in", 1, "Local");
		}
		else 
		{
			PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password",strUserName + "|" + strPassword);
			ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
		}
	}
