	public void SENTRYLINK_ExitSpotOpenMeterInBrowser(Map<String, String> objDictionary, String strMaximumDuration,String strCoinTimePuchaseLimit, String strFreeTimeFirstPayment, String strCreditCardIncrementTime,String strInitialGracePeriod, String strViolationGracePeriod, String strHandicapInitialGracePeriod,String strHandicapViolationGrace, String strNoParkingGrace, String strSetImageSendBeforeViolation,String strParkingShortSessionSec, String strUnlockValue, String strUnlockTime, String strUnlockMax,String strHostType)
	{
		String strMethodName = new Object() {
		}.getClass().getEnclosingMethod().getName();
		CommonWeb clsCommonWeb = new CommonWeb();
		System.out.println(strMethodName.toUpperCase());
		Meter clsMeter = new Meter();
		HttpConnections clsHttpConnections = new HttpConnections();
		String strVirtualMeter = objDictionary.get("strVirtualMeter");
		if (strVirtualMeter == null) {strVirtualMeter = "False";}
		// Check If Current Rate Block Is Set Correctly
		String strDeviceId = objDictionary.get("strDeviceId");
		String strCurrentRateBlockGroup = clsHttpConnections.GET_RateBlockNameUsingRateBlockId(objDictionary,strDeviceId);
		String strRateBlockGroup = objDictionary.get("strRateBlockGroup");
		// Check If Rate Block Is Blank
		String strRateBlockIsBlank = clsHttpConnections.CheckIfRatBlockRateSetIsBlank(objDictionary, strDeviceId);
		objDictionary.put("strRateBlockIsBlank", strRateBlockIsBlank);
		if (!strCurrentRateBlockGroup.equals(strRateBlockGroup)) {clsCommonWeb.AddOrUpdateMeterRateBlockGroup(objDictionary, strRateBlockGroup, strHostType);}
		// Add TestCase Variables to Dictionary As Needed
		objDictionary.remove("strMaximumDuration");
		objDictionary.put("strMaximumDuration", strMaximumDuration);
		if (strVirtualMeter.equals("True")) 
		{
			String strUserExists = "";
			try {strUserExists = clsHttpConnections.JsonCheckIfUserExists(objDictionary);} catch (Exception e) {};
			if (strUserExists.contains("True"))// False
			{
				try 
				{
					clsHttpConnections.CURL_EndParkingSession(objDictionary);
					// clsHttpConnections.JsonEndParkingSession(objDictionary);
				} catch (Exception e) {}
				String LegacyStatus = clsHttpConnections.HTTPCONNECTIONS_FetchLegacyMeterStatus(objDictionary, "");
				if (LegacyStatus.equals("Empty")) {Reporter.log("The Virtual meter spot changed to empty");}
				else {clsMeter.UpdateErrorMessageWithPivotalData(objDictionary, null,"The Virtual meter spot did not change to empty-" + strMethodName);}
			}
		} 
		else 
		{
			clsMeter.METER_ExitBothSpots(objDictionary, null, "Local");
			String strExecuteFrom = objDictionary.get("ExecuteFrom");if (strExecuteFrom == null) {strExecuteFrom = "";}
			if (strExecuteFrom.equals("Development")) {clsCommonWeb.OpenMeterInBrowser(objDictionary);}
		}
	}
	public void SENTRYLINK_ExitSpotSetMeterRateBlocksOpenMeterInBrowse(Map<String, String> objDictionary,String strMaximumDuration, String strCoinTimePuchaseLimit, String strFreeTimeFirstPayment,String strCreditCardIncrementTime, String strInitialGracePeriod, String strViolationGracePeriod,String strHandicapInitialGracePeriod, String strHandicapViolationGrace, String strNoParkingGrace,String strSetImageSendBeforeViolation, String strParkingShortSessionSec, String strUnlockValue,String strUnlockTime, String strUnlockMax, String strHostType)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		CommonWeb clsCommonWeb = new CommonWeb();
		System.out.println(strMethodName.toUpperCase());
		Meter clsMeter = new Meter();
		HttpConnections clsHttpConnections = new HttpConnections();
		String strVirtualMeter = objDictionary.get("strVirtualMeter");if (strVirtualMeter == null) {strVirtualMeter = "False";}
		// Check If Current Rate Block Is Set Correctly
		String strDeviceId = objDictionary.get("strDeviceId");
		String strCurrentRateBlockGroup = clsHttpConnections.GET_RateBlockNameUsingRateBlockId(objDictionary,strDeviceId);
		String strRateBlockGroup = objDictionary.get("strRateBlockGroup");
		// Check If Rate Block Is Blank
		String strRateBlockIsBlank = clsHttpConnections.CheckIfRatBlockRateSetIsBlank(objDictionary, strDeviceId);
		objDictionary.put("strRateBlockIsBlank", strRateBlockIsBlank);
		if (!strCurrentRateBlockGroup.equals(strRateBlockGroup)) 
		{
			clsCommonWeb.AddOrUpdateMeterRateBlockGroup(objDictionary, strRateBlockGroup, strHostType);
		}
		// Add TestCase Variables to Dictionary As Needed
		objDictionary.remove("strMaximumDuration");
		objDictionary.put("strMaximumDuration", strMaximumDuration);
		if (strVirtualMeter.equals("True"))
		{
			String strUserExists = "";
			try {strUserExists = clsHttpConnections.JsonCheckIfUserExists(objDictionary);} catch (Exception e) {};
			if (strUserExists.contains("True"))// False
			{
				String LegacyStatus = clsHttpConnections.HTTPCONNECTIONS_FetchLegacyMeterStatus(objDictionary, "");
				if(!LegacyStatus.equals("Empty"))
				{
					try {clsHttpConnections.JsonEndParkingSession(objDictionary);} catch (Exception e) {}
					LegacyStatus = clsHttpConnections.HTTPCONNECTIONS_FetchLegacyMeterStatus(objDictionary, "");
					if (LegacyStatus.equals("Empty")) {Reporter.log("The Virtual meter spot changed to empty");}
					else {clsMeter.UpdateErrorMessageWithPivotalData(objDictionary, null,"The Virtual meter spot did not change to empty-" + strMethodName);}
				}
			}
		}
		else
		{
			clsMeter.METER_ExitBothSpots(objDictionary, null, "Local");
			String strExecuteFrom = objDictionary.get("ExecuteFrom");
			if (strExecuteFrom == null) {strExecuteFrom = "";}
			if (strExecuteFrom.equals("Development")) {clsCommonWeb.OpenMeterInBrowser(objDictionary);}
		}
		clsCommonWeb.SENTRYLINK_SetMeterRateBlocksOpenMeterInBrowse(objDictionary, null, strMaximumDuration,strCoinTimePuchaseLimit, strFreeTimeFirstPayment, strCreditCardIncrementTime, strInitialGracePeriod,strViolationGracePeriod, strHandicapInitialGracePeriod, strHandicapViolationGrace, strNoParkingGrace,strSetImageSendBeforeViolation, strParkingShortSessionSec, strUnlockValue, strUnlockTime, strUnlockMax,"Local");
		String strMeterGroupInitialGraceTimeSeconds = clsHttpConnections.GET_MeterGroupInitialGraceTimeSecond(objDictionary, "Local", "1");
		int intInitialGracePeriod = Integer.parseInt(strInitialGracePeriod) * 60;
		int intMeterGroupInitialGraceTimeSeconds = Integer.parseInt(strMeterGroupInitialGraceTimeSeconds);
		if(intInitialGracePeriod != intMeterGroupInitialGraceTimeSeconds)
		{
			//Update Meter Group Initial Grace
			String strBrowser = objDictionary.get("strBrowser");
			String strRemotePath = objDictionary.get("strRemotePath");
			String strMeterGroup = objDictionary.get("strMeterGroup");
			threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
			WebDriver driver = getDriver();
			clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			// Navigate to Configure Meter
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Meter Groups",strHostType);
			clsCommonWeb.ClickLink(objDictionary, driver, "Meter Groups", strMeterGroup, 1);
			clsCommonWeb.ClickButton(objDictionary, driver, "Meter Groups","Edit This Meter Group", 1,"Local");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Meter Group Edit", "Populate User Search", "{T} Parking init grace period",Integer.toString(intInitialGracePeriod));
			try {Thread.sleep(2000);} catch (Exception z) {}
			clsCommonWeb.ClickButton(objDictionary, driver, "Meter Group Edit","Update", 1,"Local");
			try {Thread.sleep(2000);} catch (Exception z) {}
			driver.quit();
		}
	}
	
	
	
