	public void SENTRYLINK_SetMeterRateBlocksOpenMeterInBrowse(Map<String, String> objDictionary, WebDriver driver,String strMaximumDuration, String strCoinTimePuchaseLimit, String strFreeTimeFirstPayment,String strCreditCardIncrementTime, String strInitialGracePeriod, String strViolationGracePeriod,String strHandicapInitialGracePeriod, String strHandicapViolationGrace, String strNoParkingGrace,String strSetImageSendBeforeViolation, String strParkingShortSessionSec, String strUnlockValue,String strUnlockTime, String strUnlockMax, String strHostType) 
	{
		String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
		System.out.println("Start: " + strMethodName);
		Stopwatch timer = Stopwatch.createStarted();
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		HttpConnections clsHttpConnections = new HttpConnections();
		String strVirtualMeter = objDictionary.get("strVirtualMeter");
		if (strVirtualMeter == null) {strVirtualMeter = "False";}
		// Check If Local spot Rate Block Is Set Correctly
		String strDeviceId = objDictionary.get("strDeviceId");
		String strCurrentRateBlockGroup = clsHttpConnections.GET_RateBlockNameUsingRateBlockId(objDictionary,strDeviceId);
		String strRateBlockGroup = objDictionary.get("strRateBlockGroup");
		if (!strCurrentRateBlockGroup.equals(strRateBlockGroup)) {clsCommonWeb.AddOrUpdateMeterRateBlockGroup(objDictionary, strRateBlockGroup, "Local");}
		// Check If Remote spot Rate Block Is Set Correctly
		String strRemoteDeviceId = objDictionary.get("strRemoteDeviceId");
		if (strRemoteDeviceId != null) 
		{
			strCurrentRateBlockGroup = clsHttpConnections.GET_RateBlockNameUsingRateBlockId(objDictionary,strRemoteDeviceId);
			if (!strCurrentRateBlockGroup.equals(strRateBlockGroup)) {clsCommonWeb.AddOrUpdateMeterRateBlockGroup(objDictionary, strRateBlockGroup, "Remote");}
		}
		// RRB: Remove Rate Blocks
		String strRateBlockIsBlank = objDictionary.get("strRateBlockIsBlank");
		// Check If Rate Block Is Blank
		if (strRateBlockIsBlank == null) {strRateBlockIsBlank = clsHttpConnections.CheckIfRatBlockRateSetIsBlank(objDictionary, strDeviceId);objDictionary.put("strRateBlockIsBlank", strRateBlockIsBlank);}
		if (strRateBlockIsBlank.equals("False")) {clsCommonWeb.SENTRYLINK_DeleteFreeAndNoParkingRateSetFromRateBlock(objDictionary);}
		// Remove Rate From Both Global Machines
		String strRemoteHost = objDictionary.get("strRemoteHost");
		if (strRemoteHost == null) {strRemoteHost = "";}
		if (!strRemoteHost.equals("")) {clsMeter.RemoveRateBlocksFromMeter(objDictionary, null, "Remote");}
		// Reset After Rate Block Switches From Free Time 10 to 0
		String strPreviousFreeTimeFirstPayment = clsMeter.METER_GetSYS_PARKING_FREE_TIME_ON_FIRST_PAYMENT(objDictionary,driver);
		if (strFreeTimeFirstPayment.equals("0") && strPreviousFreeTimeFirstPayment.equals("10")) 
		{
			// PS1: Park Spot 1
			clsMeter.METER_ParkSpot(objDictionary, "1", strHostType);
			String strNumberOfSpots = clsMeter.METER_GetSYS_NUMBER_OF_SPOTS(objDictionary, driver, strHostType);
			if (!strNumberOfSpots.equals("1")) {clsMeter.METER_ExitBothSpots(objDictionary, null, "Local");}
			else {clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null, "1", strHostType);}
		}
		clsMeter.RemoveRateBlocksFromMeter(objDictionary, null, "Local");
		String strForcedMulti = clsMeter.METER_GetSYS_FORCE_MULTI(objDictionary,driver, "Local");
		if(strForcedMulti.equals("true"))
  		{
  			clsMeter.RemoveGlobalRateBlocksFromMeter(objDictionary, driver, "Local");
  		}
		// UpdateMeterSettings
		clsMeter.SENTRYMETER_UpdateMetertSetting(objDictionary, strMaximumDuration, strCoinTimePuchaseLimit,strFreeTimeFirstPayment, strCreditCardIncrementTime, strInitialGracePeriod, strViolationGracePeriod,strHandicapInitialGracePeriod, strHandicapViolationGrace, strNoParkingGrace,strSetImageSendBeforeViolation, strParkingShortSessionSec, strUnlockValue, strUnlockTime, strUnlockMax);
		// USLRSV: Update Rate Set Values
		try {Thread.sleep(5500);} catch (Exception z) {}
		clsCommonWeb.SENTRYLINK_UpdateRateSetValues(objDictionary, strMaximumDuration, strCoinTimePuchaseLimit,strFreeTimeFirstPayment, strCreditCardIncrementTime, strInitialGracePeriod, strViolationGracePeriod,strHandicapInitialGracePeriod, strHandicapViolationGrace, strNoParkingGrace);
		// Disable Maintenance Mode
		if (strVirtualMeter.equals("False")) {clsCommonWeb.SENTRYLINK_UpdateMaintenanceMode(objDictionary, "Disable", "1", "", strHostType);}
		System.out.println("Method (" + strMethodName + ") took: " + timer.stop());
	}

	public void SENTRYLINK_UserLoginIn(Map<String, String> objDictionary, WebDriver driver, String strRole) 
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonWeb clsCommonWeb = new CommonWeb(); 
  		Database clsDatabase = new Database();
  		String strBrowser = objDictionary.get("strBrowser");
  		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strEnvironment = objDictionary.get("strEnvironment");
		//We Need to Limit Number of Prod Users
		String strUserName = "";
		if(strEnvironment.equals("PROD"))
		{
			strUserName = "darin@mpspark.com";
			if(strRole.equals("admin"))
			{
				strUserName = "darinadmin@mpspark.com";
			}
		}
		else
		{
			if(strRole.equals("parking_enforcement_officer")){strRole = "peo";}
			strUserName = strUniqueId+strMunicipality.replace(" ","").replace(",", "")+strRole.replace(" ","")+"@gmail.com";
		}
		String strPassword = SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		// Get Current Page
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		if (strCurrentPageName.contains("Please choose a Municipality") && strBrowser.equals("Safari")) 
		{
			// Click Logout
			clsCommonWeb.ClickLink(objDictionary, driver, "Please choose a Municipality", "Log Out", 1);
		}
		clsCommonWeb.StoreText(objDictionary, driver, "Login", "Version", 1, "strSentryLinkVersion");
		strPassword = SENTRYLINK_GetPassword(objDictionary, strUserName.toLowerCase(), strRole);
		clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password",strUserName.toLowerCase() + "|" + strPassword);
		ClickButton(objDictionary, driver, "Login", "Sign in", 1, "Local");
		if (strActualWaitValue.equals("Renew your password")) 
		{
			String strPasswordReplace = strPassword.replace("!", "");
			int intCurrentVersion = Integer.parseInt(strPassword.substring(strPasswordReplace.indexOf(strRole) + strRole.length(), strPasswordReplace.length()));
			int intNewVersion = intCurrentVersion + 1;
			String strNewPassword = strPasswordReplace.replace(Integer.toString(intCurrentVersion),Integer.toString(intNewVersion)) + "!";
			clsCommonWeb.PopulateAction(objDictionary, driver, "Renew your password", "Populate Renew your password","{T} Current password|{T} New password|{T} Confirm new password",strPassword + "|" + strNewPassword + "|" + strNewPassword);
			clsCommonWeb.ClickButton(objDictionary, driver, "Renew your password", "Change my password", 1, "Local");
			String strSQL = "Update \"UNIQUE\" SET \"Password\" = '" + strNewPassword + "' where \"Environment\" = '"+ strEnvironment + "' and \"UserId\" = '" + strUserName.toLowerCase() + "'";
			Reporter.log("Update Password SQL: " + strSQL);
			clsDatabase.DATABASE_Update(objDictionary, strSQL);
		} 
		else if (strActualWaitValue.equals("UserIsDeleted"))
		{
			// Unlock User
			if (strRole.equals("admin")) {UpdateErrorMessageWithPivotalData(objDictionary, driver,"The User (" + strUserName + ") Account is Is Deleted-" + strMethondName, "Local");}
			else 
			{clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);}
		}
		else if (strActualWaitValue.equals("InvalidEmailOrPassword") && !strRole.equals("admin")|| strActualWaitValue.equals("YouHaveOneMoreAttemptBeforeYourAccountIsLocked")&& !strRole.equals("admin")) 
		{
			// Update User Password
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName.toLowerCase());
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
			try {Thread.sleep(2000);} catch (Exception z) {}
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Edit", 1);
			clsCommonWeb.ClickButton(objDictionary, driver, "Edit User", "Show/Hide Password Fields", 1, "Local");
			strPassword = strUniqueId + strMunicipality.replace(", ", "").replace(" ", "") + strRole.replace(" ", "")+ "1";
			int intCurrentVersion = 0;
			String strNewPassword = "";
			String strCondition3 = "True";
			do 
			{
				int intNewVersion = intCurrentVersion + 1;
				strPassword = strPassword.replace("!", "");
				strNewPassword = strPassword.replace(Integer.toString(intCurrentVersion),Integer.toString(intNewVersion)) + "!";
				clsCommonWeb.PopulateAction(objDictionary, driver, "Edit User", "Populate Passwords","{T} Password|{T} Password Confirmation", strNewPassword + "|" + strNewPassword);
				clsCommonWeb.ClickButton(objDictionary, driver, "Edit User", "Save User", 1, "Local");
				try {Thread.sleep(2000);} catch (Exception z) {}
				strCondition3 = clsCommonWeb.ConditionalStepText(objDictionary, driver, "Edit User","Failed to update the User.", 1, "Exists", "");
				intCurrentVersion++;
				strPassword = strNewPassword;
			} while (strCondition3.equals("True"));
			// Insert User In to database
			strUserName = SENTRYLINK_GetUserName(objDictionary, strRole);
			String strSQL = "Update \"UNIQUE\" SET \"Password\" = '" + strNewPassword + "' where \"Environment\" = '"+ strEnvironment + "' and \"UserId\" = '" + strUserName.toLowerCase() + "'";
			clsDatabase.DATABASE_Update(objDictionary, strSQL);
			clsCommonWeb.SENTRYLINK_LogOut(objDictionary, driver, "Approved Users");
			SENTRYLINK_UserLoginIn(objDictionary, driver, strRole);
		} 
		else if (strActualWaitValue.equals("YourAccountIsLocked") && !strRole.equals("admin")) 
		{
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName.toLowerCase());
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Unlock", 1);
			clsCommonWeb.SENTRYLINK_LogOut(objDictionary, driver, "Approved Users");
			SENTRYLINK_UserLoginIn(objDictionary, driver, strRole);
		} 
		else if (strActualWaitValue.equals("YourAccountHasExpiredDueToInactivity") && !strRole.equals("admin")) 
		{
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Approved Users","Local");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email",strUserName.toLowerCase());
			clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1, "Local");
			try {Thread.sleep(1000);}catch (Exception e) {}
			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Unlock", 1);
			clsCommonWeb.SENTRYLINK_LogOut(objDictionary, driver, "Approved Users");
			switch (strEnvironment)
			{
				case "QA":
					objDictionary.put("https://sentrylink.quality.sentry-link.com/users/login","Login");
				case "SG":
					objDictionary.put("https://sentrylink.staging.sentry-link.com/users/login","Login");
				case "PROD":
					objDictionary.put("https://sentrylink.mpspark.com/users/login","Login");
			} 
			clsCommonWeb.PopulateAction(objDictionary, driver, "Login", "Populate Login", "{T} Email|{T} Password",strUserName.toLowerCase() + "|" + strPassword);
			// UpdateErrorMessageWithPivotalData(objDictionary,driver,"Your account has
			// expired due to inactivity.-"+strUserName+"-"+strMethondName);
		}
	}
