  	public void SENTRYLINK_TurnOnMeterLogging(Map<String, String> objDictionary)
    {
  		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strHost = objDictionary.get("strHost");
		String strPassword = System.getenv("UNIQUE");
	    JSch jsch = new JSch();
	    String user = "root";String host = strHost;int port=22;
	    try
    	{
		    Session session = jsch.getSession(user, host, port);
		    session.setPassword(strPassword);
	        session.setConfig("StrictHostKeyChecking", "no");
	        System.out.println("Establishing Session Connection");
	        session.connect();
	        System.out.println("Connection established.");
	        Channel channel=session.openChannel("exec");
	        ((ChannelExec)channel).setCommand("tail -f /var/log/Xsession.log | sed -e \"s/#~> //g\"");
	        channel.setInputStream(null);
	        ((ChannelExec)channel).setErrStream(System.err);
	        InputStream in=channel.getInputStream();
	        System.out.println("Establishing Channel Connection");
	        channel.connect();
	        System.out.println("Connection established.");
	        byte[] tmp=new byte[1024];
	        while(true)
	        {
	        	while(in.available()>0)
	        	{
	        		int i=in.read(tmp, 0, 1024);if(i<0)break;
	        		System.out.print("Terminal Response:" + new String(tmp, 0, i));
	        	}
	        	if(channel.isClosed())
	        	{
	        		if(in.available()>0) continue; System.out.println("exit-status: "+channel.getExitStatus());
	        		if(channel.getExitStatus() == 0)
	        		{Reporter.log("The Meter logging was activated");}
	        		else
	        		{UpdateErrorMessageWithPivotalData(objDictionary,null,"The Meter logging was not activated"+strMethondName,"Local");}
	            	break;
	        	}
	        }
	        channel.disconnect();
	        session.disconnect();
	    	}catch(Exception e){System.err.print(e);}
    }
