	public String ConditionalStepListbox(Map<String, String> objDictionary, WebDriver driver, String strPageName,String strListboxName, int intListboxIndex, String strValidationType, String strListboxValue) 
	{
		// Doesn't Work
		String strMethondName = new Object() {}.getClass().getEnclosingMethod().getName();
		CommonWeb clsCommonWeb = new CommonWeb();
		WebElement objListbox = clsCommonWeb.GetListboxObj(objDictionary, driver, strPageName, strListboxName);
		if (objListbox != null) 
		{
			switch (strValidationType) {
				case "Exists":
					return "True";
				case "Item Exists":
					List<WebElement> options = objListbox.findElements(By.tagName("option"));
					for (WebElement option : options)
					{
						System.out.println(option.getText());
						if (!option.getText().toString().equals("")) 
						{
							System.out.println(strListboxValue);
							System.out.println(option.getText());
							if (strListboxValue == option.getText()){return "True";}
						}
					}
				case "Value":
					if (new Select(objListbox).getFirstSelectedOption().getText().equals(strListboxValue)) 
					{return "True";}
					else
					{return "False";}
				default:
					clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary, driver,"The Validation Type (" + strValidationType + ") for Listbox hasn't been added", "Local");
			}
		} 
		else 
		{
			if (strValidationType.equals("Exists")) 
			{
				return "False";
			} 
			else
			{
				clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary, driver,"The Listbox (" + strListboxName + ") at index (" + intListboxIndex+ ") did not exist, so it could not perform the (" + strValidationType + ") validation-"+ strMethondName,"Local");
			}
		}
		return "";
	}

	// Dispute Violation
	public void SENTRYLINK_DisputeViolation(Map<String, String> objDictionary, String strViolationNumber,String strLicensePlate, String strValidateEmailReceipt) throws Exception
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		// Create Admin User
		clsCommonWeb.SENTRYLINK_CreateUser(objDictionary, "admin");
		// Login As Admin
		HttpConnections clsHttpConnections = new HttpConnections();
		String strViolationDateIssued = clsHttpConnections.HTTPCONNECTIONS_StoreViolationDateIssued(objDictionary,"Local", "1");
		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver(); // driver.quit();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		//clsCommonWeb.SENTRYLINK_UserLoginIn(objDictionary, driver,"parker");
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		// Navigate to user page
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Payment Site", "Local");
		// Populate Violation Number
		try {Thread.sleep(2000);} catch (Exception e) {}
		clsCommonWeb.PopulateAction(objDictionary, driver, "Pay Violation", "Populate Violation LookUp","{T} Violation Number|{T} License Plate", strViolationNumber + "|" + strLicensePlate);
		clsCommonWeb.ClickButton(objDictionary, driver, "Pay Violation", "Click To Find Your Violation", 1, "Local");
		// Valdiate Violation Summary
		clsCommonWeb.VerificationPointText(objDictionary, driver, "Pay Or Appeal Violation", "Violation #", 1,"Contains", strViolationNumber);
		String strEnvironment = objDictionary.get("strEnvironment");
		String strFormattedViolationDateIssued = "";
		strFormattedViolationDateIssued = clsCommonWeb.ConvertUTCTimeToLocalTimeWithTimeZoneAbbr(strViolationDateIssued,"yyyy-MM-dd'T'HH:mm:ss'Z'","MM/dd/yyyy h:mm:ss a","America/Chicago");
		clsCommonWeb.VerificationPointText(objDictionary, driver, "Pay Or Appeal Violation", "Date Issued", 1,"Contains", strFormattedViolationDateIssued);
		clsCommonWeb.VerificationPointText(objDictionary, driver, "Pay Or Appeal Violation", "License Plate Number", 1,"Contains", strLicensePlate);
		String strViolationReason = objDictionary.get("strViolationReason");
		clsCommonWeb.VerificationPointText(objDictionary, driver, "Pay Or Appeal Violation", "Violation Reason", 1,"Contains", strViolationReason);
		Gmail clsGmail = new Gmail();
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		//Parker Email
		String strGmailParkerPassword = clsGmail.Gmail_GetParkerGmailPassword(objDictionary);
		String strGmailParkerUserName = strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + "parker@gmail.com";
		clsGmail.Gmail_DeleteAllEmails(strGmailParkerUserName, strGmailParkerPassword);
		//PEO Email
		String strGmailPEOPassword = clsGmail.Gmail_GetPEOGmailPassword(objDictionary);
		String strGmailPEOUserName = strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + "peo@gmail.com";
		clsGmail.Gmail_DeleteAllEmails(strGmailPEOUserName, strGmailPEOPassword);
		clsCommonWeb.ClickButton(objDictionary, driver, "Pay Or Appeal Violation", "Dispute This Violation", 1,"Local");
		try {Thread.sleep(2500);} catch (Exception e) {}
		clsCommonWeb.PopulateAction(objDictionary, driver, "Dispute Violations", "Populate Dispute Violation","{T} Email|{T} Dispute Reason", strGmailParkerUserName.toLowerCase() + "|The devil made me do it");
		clsCommonWeb.ClickButton(objDictionary, driver, "Dispute Violations", "Submit My Dispute", 1, "Local");
		try {Thread.sleep(15000);} catch (Exception e) {}
		if(!strEnvironment.equals("PROD"))
		{
			//Validate Parker Disputed Violation Email
			clsGmail.Gmail_ValidateDisputedViolationEmailParker(objDictionary, strGmailParkerUserName, strGmailParkerPassword,strViolationNumber);
		}
		//Validate PEO Disputed Violation Email
//		clsGmail.Gmail_ValidateDisputedViolationEmailPEO(objDictionary, strGmailPEOUserName, strGmailPEOPassword,strViolationNumber);
		//Need to add code to validate disputed email for the parker
		driver.quit();
	}
	public void SENTRYLINK_RefundPaymentsFromParkingSessionPage(Map<String, String> objDictionary, WebDriver driver) {
	    String strParkingSessionURL = driver.getCurrentUrl();
	    WebDriverWait wait = new WebDriverWait(driver,Duration.ofSeconds(30));
	    // Refund Payments
	    ClickLink(objDictionary, driver, "Parking Session", "Adjustments", 0);
	    try {Thread.sleep(3000);} catch (Exception e) {}
	    WebElement objTable = GetTableObj(objDictionary, driver, "Parking Session", "Adjustments", 1);

	    if (objTable == null) {
	        UpdateErrorMessageWithPivotalData(objDictionary, driver, "The table (Adjustments) did not exist", "Local");
	        return; // Exit the method if the table is not found
	    }
	    List<WebElement> allRows = objTable.findElements(By.xpath(".//tbody/tr"));
	    System.out.println("Total rows found: " + allRows.size());
	    int totalRowsToProcess = allRows.size() - 1;  // Number of rows to refund (exclude last)
        int i = 0;  // Start counter

        do {
            // Re-fetch the table and rows at the beginning of each iteration
            objTable = GetTableObj(objDictionary, driver, "Parking Session", "Adjustments", 1);
            if (objTable == null) {
                UpdateErrorMessageWithPivotalData(objDictionary, driver, "Adjustments table not found during processing", "Local");
                break;
            }

            allRows = objTable.findElements(By.xpath(".//tbody/tr"));

            // Safety check: prevent going beyond available rows
            if (i >= allRows.size() - 1 || allRows.size() <= 1) {
                System.out.println("No more valid rows to process (i=" + i + "). Stopping.");
                break;
            }

            WebElement objRow = allRows.get(i);
            System.out.println("Processing row: " + i);
            System.out.println("Current max refundable index: " + (allRows.size() - 1));

            try {
                List<WebElement> columns = objRow.findElements(By.tagName("td"));
                if (columns.size() >= 8) {
                    String valueIn5thColumn = columns.get(4).getText();
                    System.out.println("Value in 5th column: " + valueIn5thColumn);

                    // Safely check for Refund link (recommended to avoid errors if already refunded)
                    List<WebElement> refundLinks = columns.get(7).findElements(By.linkText("Refund"));
                    if (refundLinks.isEmpty()) {
                        System.out.println("No Refund link in row " + i + " - skipping (possibly already refunded)");
                    } else {
                        WebElement refundLink = refundLinks.get(0);
                        String strHref = refundLink.getAttribute("href");
                        objDictionary.remove("strHref");
                        objDictionary.put("strHref", strHref);

                        refundLink.click();
                        try { Thread.sleep(1000); } catch (Exception e) {}
                        // Refund Payment
                        PopulateAction(objDictionary, driver, "Normal Payment", "Populate Refund Amount", 
                            "{T} Refund / Adjustment Amount|{RB} Add or Subtract from Payment", valueIn5thColumn + "|Subtract");
                        ClickButton(objDictionary, driver, "Normal Payment", "Refund / Adjust", 1, "Local");
                        try { Thread.sleep(2000); } catch (Exception e) {}

                        VerificationPointText(objDictionary, driver, "Normal Payment", "Success Message", 1, 
                            "Contains", "Successfully created adjustment");

                        // Navigate back to Parking Session
                        driver.navigate().to(strParkingSessionURL);
                        try { Thread.sleep(2000); } catch (Exception e) {}

                        // Re-open Adjustments tab
                        wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//a[text()='Adjustments']")));
                        ClickLink(objDictionary, driver, "Parking Session", "Adjustments", 0);

                        // Wait for table to reload
                        try { Thread.sleep(1500); } catch (Exception e) {}
                    }
                }
            } catch (Exception e) {
                System.out.println("Exception during row " + i + " processing: " + e.getMessage());
                e.printStackTrace();
                // Optionally break; or continue to next row
            }
            System.out.println("counter "+i);
            i++;  // Increment counter at the very end

        } while (i < totalRowsToProcess);  // Continue only if we haven't processed all original refundable rows
        return;
	}
	public void SENTRYLINK_NavigateToParkingSession(Map<String, String> objDictionary, WebDriver driver,String strAuthorization, String strSpotNumber) 
	{
		String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
		// Add Sleep to allow Meter Values to get up to SentryLink
		try {Thread.sleep(7000);} catch (Exception e) {}
		CommonWeb clsCommonWeb = new CommonWeb();
		String strVirtualMeter = objDictionary.get("strVirtualMeter");
		if (strVirtualMeter == null) {strVirtualMeter = "False";}
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strParkingId = objDictionary.get("strParkingId");
		String strMunicipalitySubdomain = objDictionary.get("strMunicipalitySubdomain");
		if (strParkingId == null) 
		{
			UpdateErrorMessageWithPivotalData(objDictionary, null,"The Parking Id didn't exist in the objDictionary" + strMethodName, "Local");
		}
		String strEnvironment = objDictionary.get("strEnvironment");
		if (strEnvironment == null) {strEnvironment = "";}
		// DEVICE SETTINGS
		switch (strEnvironment) 
		{
			case "QA":
				driver.navigate().to("https://" + strMunicipalitySubdomain + ".quality.sentry-link.com/parking_sessions/"+ strParkingId);
				Reporter.log("https://" + strMunicipalitySubdomain + ".quality.sentry-link.com/parking_sessions/"+ strParkingId);
				break;
			case "SG":
				driver.navigate().to("https://" + strMunicipalitySubdomain + ".staging.sentry-link.com/parking_sessions/"+ strParkingId);
				Reporter.log("https://" + strMunicipalitySubdomain + ".staging.sentry-link.com/parking_sessions/" + strParkingId);
				break;
			case "PROD":
				driver.navigate().to("https://" + strMunicipalitySubdomain + ".mpspark.com/parking_sessions/" + strParkingId);
				Reporter.log("https://" + strMunicipalitySubdomain + ".mpspark.com/parking_sessions/" + strParkingId);
				break;
		}
	}
