	public void SENTRYLINK_DestroyUser(Map<String, String> objDictionary, WebDriver driver, String strRole) 
	{
		String strUniqueId = objDictionary.get("strUniqueId");
		String strMunicipality = objDictionary.get("strMunicipality");
		String strUserName = strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + strRole.replace(" ", "")+ "@gmail.com";
		SENTRYLINK_OpenLoginPage(objDictionary, driver);
		SENTRYLINK_UserLoginIn(objDictionary, driver, strRole);
		String strCondition = ConditionalStepText(objDictionary, driver, "Login", "AlertMessage", 1, "Exists", "");
		if (strCondition.equals("True")) {driver.quit();Reporter.log("The user (" + strUserName + ") had already been destroyed" + "");return;}
		// Workaround
		if (!"admin|court_clerk|csr".contains(strRole)) 
		{
			ClickLink(objDictionary, driver, "Home", strMunicipality.replace(" ", "").replace(",", "") + " " + strRole,1);
		}
		ClickLink(objDictionary, driver, "Home", "Log Out", 1);
		SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strPageName = GetCurrentPageName(objDictionary, driver);
		SENTRYLINK_NavigateToApprovedUsers(objDictionary, driver, strPageName);
		SENTRYLINK_SearchUserByOnApprovedUserPage(objDictionary, driver, strRole);
		ClickTableLinkByColumnValue(objDictionary, driver, "Approved Users", "Users", 1, 2, strUserName, "Destroy");
		try {Thread.sleep(2000);} catch (Exception e) {} // Wait for destroy to complete
		driver.quit();
	}
	public void SENTRYLINK_DestroyUser2(Map<String, String> objDictionary, String strUserName, String strPassword) 
	{
		String strMethondName = new Object() {}.getClass().getEnclosingMethod().getName();
		HttpConnections clsHttpConnections = new HttpConnections();
		try 
		{
			String strJsonUserId = clsHttpConnections.StoreJsonUserId(objDictionary, strUserName, strPassword);
			if (strJsonUserId.equals("CheckIfUserIsDeleted")) 
			{
				SENTRYLINK_UndeleteUser(objDictionary, strUserName);
				strJsonUserId = clsHttpConnections.StoreJsonUserId(objDictionary, strUserName, strPassword);
				if (!strJsonUserId.equals("CheckIfUserIsDeleted")) 
				{
					clsHttpConnections.JsonDeleteUser(objDictionary, strJsonUserId, strUserName);
				}
			} 
			else if (strJsonUserId.equals("")) 
			{Reporter.log("The user (" + strUserName + ") had already been destroyed" + "");}
			else 
			{
				clsHttpConnections.JsonDeleteUser(objDictionary, strJsonUserId, strUserName);
				try {Thread.sleep(10000);} catch (Exception e) {}
			}
		} catch (Exception e) 
		{UpdateErrorMessageWithPivotalData(objDictionary, null,"SENTRYLINK_DestroyUser2-(" + e + ")" + strMethondName, "Local");}
	}
