	public void SENTRYLINK_ProcessViolationAwaitingCollectionsInSL(Map<String, String> objDictionary,String strViolationId) {
		CommonWeb clsCommonWeb = new CommonWeb();
		String strBrowser = objDictionary.get("strBrowser");
    	String strRemotePath = objDictionary.get("strRemotePath");
    	//Disagree With Dispute
		threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToViolationsPage(objDictionary, driver, strPageName);
		clsCommonWeb.ClickLink(objDictionary, driver, "Violations", strViolationId, 1);
		clsCommonWeb.ClickLink(objDictionary, driver, "Violations", "Awaiting Collections", 1);
		try {Thread.sleep(3000);}catch (Exception e) {}
		WebElement objTable = clsCommonWeb.GetTableObj(objDictionary, driver, "Violations Awaiting Collection Reports", "Violations Awaiting Collection", 1);
        List<WebElement> rows = objTable.findElements(By.xpath(".//tbody/tr"));
        boolean violationFound = false;
        String violationId = "";
        // Loop through each row
        for (WebElement row : rows) {
        	try {violationId = row.findElement(By.xpath("./td[1]")).getText();}
        	catch (Exception f) {}
            // Check if the violation ID matches the target
            if (violationId.equals(strViolationId)) {
                // Find the checkbox in the last column (8th column)
                WebElement checkbox = row.findElement(By.xpath("./td[8]/input[@type='checkbox']")); // Adjust if the checkbox is in a different format
                // Check the checkbox if it's not already checked
                if (!checkbox.isSelected()) {
                    checkbox.click();
                }
                violationFound = true; // Mark as found
                break; // Exit the loop once found
            }
        }
        if (!violationFound) {
            System.out.println("Error: Violation ID " + strViolationId + " not found in the table.");
            clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Violation Id ("+strViolationId+") did not exist in the Violations Awaiting Collection Table","Local");
        }
		clsCommonWeb.ClickButton(objDictionary, driver,  "Violations Awaiting Collection Reports", "Generate Collections Export", 1,"Local");
		clsCommonWeb.ClickLink(objDictionary, driver, "Violations Awaiting Collection Reports", "Violations", 1);
		clsCommonWeb.ClickLink(objDictionary, driver, "Violations", strViolationId, 1);
		try {Thread.sleep(3000);}catch (Exception e) {}
 		clsCommonWeb.VerificationPointTable(objDictionary, driver, "Violations", "Violation Details", 1, "1","2", "CellValue", "Collections");
 		driver.quit();
	}
