	public void AddOrUpdateMeterRateBlockGroup(Map<String, String> objDictionary, String strRateBlockGroup,String strHostType)
	{
		String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
		HttpConnections clsHttpConnections = new HttpConnections();
		CommonWeb clsCommonWeb = new CommonWeb();
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		String strRateSetName = "";
		if (strRateBlockGroup.contains("Reservation")) {strRateSetName = strRateBlockGroup.replace("ReservationRateBlockGroup", "ReservationRateSet");}
		else {strRateSetName = strRateBlockGroup.replace("AutomationRateBlockGroup", "AutomationRateSet");}
		// Check If Rate Set Exists
		String strRateSetExists = clsHttpConnections.CheckIfRateSetExistsInSentryLink(objDictionary, strRateSetName);
		objDictionary.put("strRateSetExists", strRateSetExists);
		String strRateBlockExists = clsHttpConnections.CheckIfRateBlockExistsInSentryLink(objDictionary,strRateBlockGroup);
		if (strRateBlockExists.equals("False"))
		{
			// RATE BLOCK DOES NOT EXIST - CREATE RATE BLOCK AND UPDATE OR ADD RATE BLOCK
			threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
			WebDriver driver = getDriver();
			clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			// Navigate to Configure Meter
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			if (strRateBlockGroup.contains("Reservation"))
			{
				clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Meter Groups",strHostType);
				String strReservationRateType = objDictionary.get("strReservationRateType");
				SENTRYLINK_AddReservationRateBlockGroup(objDictionary, driver, strReservationRateType);
			}
			else
			{
				clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Meter",strHostType);
				SENTRYLINK_AddRateBlockGroup(objDictionary, driver);
			}
		}
		else
		{
			threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
			WebDriver driver = getDriver();
			// Get Device Id
			String strDeviceId = "";
			if (strHostType.equals("Local")) {strDeviceId = objDictionary.get("strDeviceId");}
			else if (strHostType.contains("Remote")) {strDeviceId = objDictionary.get("strRemoteDeviceId" + strHostType.substring(strHostType.length() - 1));}
			if(strDeviceId == null)
			{
				UpdateErrorMessageWithPivotalData(objDictionary, driver,"The Device does not have any assocated Remote Meters-GlobalClass-GetMeterProperties", strHostType);
			}
			String strCurrentRateBlockGroup = clsHttpConnections.GET_RateBlockNameUsingRateBlockId(objDictionary,strDeviceId);
			clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
			clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
			String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
			String strReservationRateType = objDictionary.get("strReservationRateType");
			if (strRateBlockGroup.contains("Reservation"))
			{
				// Update Rate Set
				clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Meter Groups",strHostType);
				if (strRateSetExists.equals("False"))
				{
					// ADD RATE SET
					clsCommonWeb.ClickLink(objDictionary, driver, "Rate Block Groups", "Rate Sets", 1);
					// Check if Create Link Exists
					String strConditional = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Rate Sets","Rate Set Created", 1, "Exists", "strConditional");
					if (strConditional.equals("True"))
					{clsCommonWeb.ClickLink(objDictionary, driver, "Rate Sets", "Rate Set Created", 1);}
					else
					{clsCommonWeb.ClickButton(objDictionary, driver, "Rate Sets", "Add New Rate Set", 1, "Local");}
					clsCommonWeb.SENTRYLINK_PopulateRateSet(objDictionary, driver, strReservationRateType);
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save Rate Set", 1, "Local");
					clsCommonWeb.ClickLink(objDictionary, driver, "Rate Set", "Rate Block Groups", 1);
				}
				else
				{
					// UPDATE RATE SET
					clsCommonWeb.ClickLink(objDictionary, driver, "Meter Groups", "Rate Sets", 1);
					try {Thread.sleep(2500);} catch (Exception e) {}
					clsCommonWeb.ClickLink(objDictionary, driver, "Meter Groups",strRateSetName + strReservationRateType, 1);
					clsCommonWeb.SENTRYLINK_PopulateRateSet(objDictionary, driver, strReservationRateType);
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save Rate Set", 1, "Local");
					clsCommonWeb.ClickLink(objDictionary, driver, "Rate Set", "Rate Block Groups", 1);
				}
				// Set Meter Rate Blocks
				try {Thread.sleep(1000);} catch (Exception e) {}
				clsCommonWeb.ClickLink(objDictionary, driver, "Rate Block Groups", strRateBlockGroup, 1);
				clsCommonWeb.SENTRYLINK_ClearRateFromRateBlockTable(objDictionary, driver);
				try {Thread.sleep(2000);} catch (Exception e) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group","{L} Add Set to This Group", strRateSetName + strReservationRateType);
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
				try {Thread.sleep(1000);} catch (Exception e) {}
				String strHref = driver.getCurrentUrl();
				objDictionary.put("strHref", strHref);
				// clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Setting",
				// "{TextFieldExists} Rate Block Setting~Rate Block Name", 30);
				String strReservationBlockGroup = objDictionary.get("strReservationBlockGroup");
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Rate Block Name","{T} Rate Block Name", strReservationBlockGroup);
				String strMinutesBeforeReservation = objDictionary.get("strMinutesBeforeReservation");
				String strReservationTimeMinutes = objDictionary.get("strReservationTimeMinutes");
				clsCommonWeb.SENTRYLINK_PopulateReservationStartAndEndTime(objDictionary, driver,strMinutesBeforeReservation, strReservationTimeMinutes, strReservationRateType);
			}
			else
			{
				// Meter Rate Block Group
				clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Meter",strHostType);
				if (!strCurrentRateBlockGroup.equals(strRateBlockGroup))
				{
					System.out.println("Start: " + strMethodName);
					Stopwatch timer = Stopwatch.createStarted();
					objDictionary.put("strRateSetExists", strRateSetExists);
					// Check If Expected Rate Block Exists
					if (strRateSetExists.equals("False"))
					{
						// Add Rate Block
						clsCommonWeb.SENTRYLINK_AddRateBlockGroup(objDictionary, driver);
						// Navigate Back To Meter Group - Add to Navigate To Page2
						String strMeterGroup = objDictionary.get("strMeterGroup");
						clsCommonWeb.ClickLink(objDictionary, driver, "Rate Block Groups", "Settings", 1);
						strMeterGroup = objDictionary.get("strMeterGroup");
						clsCommonWeb.ClickLink(objDictionary, driver, "Meter Groups", strMeterGroup, 1);
						clsCommonWeb.ClickLink(objDictionary, driver, "Meter Group", "Meters", 1);
						clsCommonWeb.ClickLink(objDictionary, driver, "AutomationMeterGroup", strDeviceId, 1);
						clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Showing Meter","{TextExists} Showing Meter~Rate Block Group", 30);
					}
					// Click Edit This Meter
					clsCommonWeb.ClickButton(objDictionary, driver, "Showing Meter", "Edit This Meter", 1, "Local");
					clsCommonWeb.PopulateAction(objDictionary, driver, "Configure Meter", "Populate Rate Block Group","{L} Rate Block Group", strRateBlockGroup);
					try {Thread.sleep(1000);} catch (Exception e) {}
					clsCommonWeb.ClickButton(objDictionary, driver, "Configure Meter", "Update", 1, strHostType);
					System.out.println("Method (" + strMethodName + ") took: " + timer.stop());
				}
				String strVariableName = clsCommonWeb.StoreText(objDictionary, driver, "Meter", "UserName", 1,"strVarUserName");
				clsCommonWeb.ClickLink(objDictionary, driver, "Meter", strVariableName, 1);
				clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Log Out", 1);
				driver.quit();
			}
		}
	}
