	public String SENTRYLINK_CalculateCreditCardRemainingAmount(Double dblMaximumDuration, String strCreditCardIncrementTime, DecimalFormat dFormat)
  	{
		//M32_FTFP0_FTR_PS1_CP1_VMT_PRT_CCP1_VMT_ES1_VPSH_VICAE_VIAC
		double dblCreditCardPaymentAmount = Math.ceil(((dblMaximumDuration - Double.parseDouble(strCreditCardIncrementTime)) / Double.parseDouble(strCreditCardIncrementTime)) * .25 * 100.0)/100.0; 
		//M39A_FTFP10_FTR_PS1_CP1_VMT_PRT_CCP1_VMT_ES1_VPSH_VICAE_VIAC
		//double dblCreditCardPaymentAmount = Math.round(((dblMaximumDuration - Double.parseDouble(strCreditCardIncrementTime)) / Double.parseDouble(strCreditCardIncrementTime)) * .25 * 100.0)/100.0; 
		return dFormat.format(dblCreditCardPaymentAmount);
  	}
	public String SENTRYLINK_CalculateCreditCardAmount(Double dblDuration, String strCreditCardIncrementTime, DecimalFormat dFormat)
  	{
		//DecimalFormat dFormat = new DecimalFormat("$ 0.00");
		//double dblCreditCardPaymentAmount = Math.ceil(((dblMaximumDuration - Double.parseDouble(strCreditCardIncrementTime)) / Double.parseDouble(strCreditCardIncrementTime)) * .25 * 100.0)/100.0; 
		//M39A_FTFP10_FTR_PS1_CP1_VMT_PRT_CCP1_VMT_ES1_VPSH_VICAE_VIAC
		double dblDurationAmount = Math.round(((dblDuration) / Double.parseDouble(strCreditCardIncrementTime)) * .25 * 100.0)/100.0; 
		return dFormat.format(dblDurationAmount);
  	}
	public String SENTRYLINK_CalculateFirstPaymentFee(Map<String, String> objDictionary)
  	{
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		String strFirstPayment = objDictionary.get("strFirstPayment");
		if (strFirstPayment != null)
		{
			double dblFirstPayment = Integer.parseInt(strFirstPayment)*.01;
			return dFormat.format(dblFirstPayment);
		}
		return "$0.00";
  	}
	
	public String SENTRYLINK_CalculateSubsequentPaymentFee(Map<String, String> objDictionary)
  	{
		DecimalFormat dFormat = new DecimalFormat("$0.00");
		String strSubsequentPayment = objDictionary.get("strSubsequentPayment");
		if (strSubsequentPayment != null)
		{
			double dblSubsequentPayment = Integer.parseInt(strSubsequentPayment)*.01;
			return dFormat.format(dblSubsequentPayment);
		}
		return "$0.00";
  	}
	
