	public void SENTRYLINK_ValidateViolationStatus(Map<String, String> objDictionary, WebDriver driver, String strViolationReason, String strViolationStatus)
	{
  		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		CommonWeb clsCommonWeb = new CommonWeb();
		String strDeviceId = objDictionary.get("strDeviceId");
		String strMeterGroup = objDictionary.get("strMeterGroup");
		try {waitForPageLoaded(objDictionary,driver);}catch (Exception z) {} 
		//clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Parking Session", "{LinkExists} Violations", 25);
		try {Thread.sleep(5000);}catch (Exception z) {} 
		ClickLink(objDictionary, driver, "Violations", "Violations", 1);
		//Filter Violations By MeterGroup
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Violations", "{ListboxExists} Meter Groups", 15);
		clsCommonWeb.PopulateAction(objDictionary, driver, "Violations", "Populate Meter Groups", "{L} Meter Groups",strMeterGroup.toUpperCase());
		clsCommonWeb.ClickButton(objDictionary, driver, "Violations", "Find Violations", 1,"Local");
		try {Thread.sleep(2000);}catch (Exception z) {} 
		String strClaimRowNumber = StoreTableRowNumberBaseOnTwoColumnValue(objDictionary, driver, "Violations", "Violations", 1, 9, strDeviceId,10, strViolationReason, "strClaimRowNumber");
		VerificationPointTable(objDictionary, driver,"Violations", "Violations", 1, strClaimRowNumber, "12", "CellValue", strViolationStatus);
	}
