	public void SENTRYLINK_DeleteFreeAndNoParkingRateSetFromRateBlock(Map<String, String> objDictionary) {
	    String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
	    Reporter.log("<font color='orange'>     " + strMethodName + "</font>");
	    System.out.println("Start: " + strMethodName);
	    Stopwatch timer = Stopwatch.createStarted();

	    CommonWeb clsCommonWeb = new CommonWeb();
	
	    // === Existing setup (unchanged) ===
	    String strVirtualMeter = objDictionary.getOrDefault("strVirtualMeter", "False");
	    String strDeviceId = objDictionary.get("strDeviceId");

	    HttpConnections clsHttpConnections = new HttpConnections();
	    String strRateBlockId = strVirtualMeter.equals("True")
	        ? clsHttpConnections.GetVirtualMeterRateBlockId(objDictionary)
	        : clsHttpConnections.GetMeterRateBlockId(objDictionary, strDeviceId);
	    objDictionary.put("strRateBlockId", strRateBlockId);

	    String strMeterId = strVirtualMeter.equals("True")
	        ? clsHttpConnections.Json_VirtualMeterId(objDictionary)
	        : clsHttpConnections.Json_MeterId(objDictionary, "Local");
	    objDictionary.put("strMeterId", strMeterId);

	    // Open Browser & Login
	    threadDriver = clsCommonWeb.SetDriverBrowser(objDictionary.get("strBrowser"), objDictionary.get("strRemotePath"), objDictionary);
	    WebDriver driver = getDriver();
	    clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
	    clsCommonWeb.SENTRYLINK_LoginInOrCreate(objDictionary, driver, "admin");
	    clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, clsCommonWeb.GetCurrentPageName(objDictionary, driver), "Rate Block Group", "Local");
	    waitForPageLoaded(objDictionary, driver);
	    try { Thread.sleep(2000); } catch (Exception ignored) {}

	    // === NEW: Delete all overlapping rate blocks safely ===
	    deleteAllRateBlocksOfType(objDictionary, driver, "type-no-parking", "No Parking");
	    deleteAllRateBlocksOfType(objDictionary, driver, "type-fixed", "Fixed");
	    deleteAllRateBlocksOfType(objDictionary, driver, "type-free", "Free");           // Free Parking
	    deleteAllRateBlocksOfType(objDictionary, driver, "type-progressive", "Progressive");
	    SENTRYLINK_DeleteFreeHoliday(objDictionary, driver);
	    // Send rates to all meters
	    clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Group", "{ButtonExists} Send to all", 15);
	    clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Send to all", 1, "Local");

	    driver.quit();
	    System.out.println("Method (" + strMethodName + ") took: " + timer.stop());
	}
	private void deleteAllRateBlocksOfType(Map<String, String> objDictionary,WebDriver driver, String typeClass, String friendlyName)
	{
		CommonWeb clsCommonWeb = new CommonWeb();
	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
	    int deletedCount = 0;
	    while (true) {
	        List<WebElement> blocks = driver.findElements(By.xpath("//a[contains(@class, 'label " + typeClass + "')]"));
	         if (blocks.isEmpty()) {
	            if (deletedCount > 0) { System.out.println("Deleted " + deletedCount + " " + friendlyName + " rate block(s).");}
	            break;
	        }
	        WebElement block = blocks.get(0);  // Always take first one
	        try {
	            // Scroll into view
	            ((JavascriptExecutor) driver).executeScript("arguments[0].scrollIntoView({block: 'center'});", block);
	            // Wait until clickable
	            wait.until(ExpectedConditions.elementToBeClickable(block));
	            // JavaScript click - bypasses all overlapping/z-index problems
	            ((JavascriptExecutor) driver).executeScript("arguments[0].click();", block);
	            // Click Delete button
	            clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Delete Rate Block", 1,"Local");
	            deletedCount++;
	            Thread.sleep(1500); // Small delay for UI to update

	        } catch (Exception e) {
	            System.out.println("Warning: Could not delete " + friendlyName + " block: " + e.getMessage());
	            break; // Prevent infinite loop
	        }
	    }
	}
	public void SENTRYLINK_DeleteFreeHoliday(Map<String, String> objDictionary, WebDriver driver) {
	    CommonWeb clsCommonWeb = new CommonWeb();
	    WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(15));
	    int deletedCount = 0;
	    try {
	        System.out.println("🚀 Starting Free Holiday cleanup...");
	        while (true) {
	            // Check if at least one "Free Holiday" link exists
	            List<WebElement> freeHolidayLinks = driver.findElements(By.xpath("//a[contains(text(), 'Free Holiday')]"));
	            if (freeHolidayLinks.isEmpty()) {
	                System.out.println("✅ No more 'Free Holiday' links found.");
	                break;
	            }
	            // Click the first available "Free Holiday" link
	            WebElement link = freeHolidayLinks.get(0);
	            String linkText = link.getText().trim();
	            System.out.println("➡️ Found & clicking: " + linkText);
	            link.click();
	            // Wait for Rate Block detail page to load
	            wait.until(ExpectedConditions.presenceOfElementLocated(By.xpath("//a[contains(text(), 'Delete Rate Block')]")));
	            // Use your existing CommonWeb method to click Delete
	            clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Delete Rate Block", 1, "Local");
	            System.out.println("🗑️  Clicked 'Delete Rate Block'");
	            // Wait until we return to the Rate Block Group page
	            wait.until(ExpectedConditions.urlContains("/rate_block_groups/"));
	            deletedCount++;
	            System.out.println("✅ Successfully deleted one 'Free Holiday' rate block.\n");
	            Thread.sleep(2500); // Small delay to let UI stabilize
	        }
	        System.out.println("\n🎉 Process completed! Total 'Free Holiday' rate blocks deleted: " + deletedCount);
	    }
	    catch (Exception e) {clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary, driver,"❌ Error occurred: " + e.getMessage(), "Local");}
	}
