	    			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting","Save Rate Block", 1,"Local");
	    			try {Thread.sleep(1500);}catch (Exception f) {}
	    			if(strEnvironment.equals("PROD"))
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free Parking");}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
	    			date = addDay(date, 1); 
	    			String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
	    			clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary,driver,strDayOfWeekPlus1);
