	public void SENTRYLINK_SetRateBlocksFreeTodayAndEveryDayButPaidYesterday(Map<String, String> objDictionary)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
		objDictionary.put("strRateBlockType", "RateBlockFreeTodayAndEveryDayButPaidYesterday");
		System.out.println("Start: "+strMethodName);
		Stopwatch timer = Stopwatch.createStarted();
		String strDeviceId = objDictionary.get("strDeviceId");
		String strVirtualMeter = objDictionary.get("strVirtualMeter");
		if (strVirtualMeter == null) { strVirtualMeter = "False"; }
		String strMeterId;
		HttpConnections clsHttpConnections = new HttpConnections();
		if (strVirtualMeter.equals("True")) {
		    strMeterId = clsHttpConnections.Json_VirtualMeterId(objDictionary);
		} else {
		    strMeterId = clsHttpConnections.Json_MeterId(objDictionary, "Local");
		}
		objDictionary.put("strMeterId", strMeterId);
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		// Dictionary Variables
				String strEnvironment = objDictionary.get("strEnvironment");
				String strBrowser = objDictionary.get("strBrowser");
				String strRemotePath = objDictionary.get("strRemotePath");
			     strVirtualMeter = objDictionary.get("strVirtualMeter");
				if(strVirtualMeter == null){strVirtualMeter = "False";}
				if (strVirtualMeter.equals("True"))
				{
					String strUserExists = "";
					try {strUserExists = clsHttpConnections.JsonCheckIfUserExists(objDictionary);} catch (Exception e) {};
					if (strUserExists.contains("True"))// False
					{
						String LegacyStatus = clsHttpConnections.HTTPCONNECTIONS_FetchLegacyMeterStatus(objDictionary, "");
						if(!LegacyStatus.equals("Empty"))
						{
							try {clsHttpConnections.JsonEndParkingSession(objDictionary);} catch (Exception e) {}
							LegacyStatus = clsHttpConnections.HTTPCONNECTIONS_FetchLegacyMeterStatus(objDictionary, "");
							if (LegacyStatus.equals("Empty")) {Reporter.log("The Virtual meter spot changed to empty");}
							else {clsMeter.UpdateErrorMessageWithPivotalData(objDictionary, null,"The Virtual meter spot did not change to empty-" + strMethodName);}
						}
					}
				}
				else
				{
					clsMeter.METER_ExitBothSpots(objDictionary, null, "Local");
					String strExecuteFrom = objDictionary.get("ExecuteFrom");
					if (strExecuteFrom == null) {strExecuteFrom = "";}
					if (strExecuteFrom.equals("Development")) {clsCommonWeb.OpenMeterInBrowser(objDictionary);}
				}
		
		clsCommonWeb.SENTRYLINK_DeleteFreeAndNoParkingRateSetFromRateBlock(objDictionary);
		clsMeter.RemoveRateBlocksFromMeter(objDictionary, null, "Local");
	     strVirtualMeter = objDictionary.get("strVirtualMeter");
		if(strVirtualMeter == null){strVirtualMeter = "False";}
		
		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Rate Block Group","Local");
		
		
		try
		{
			// Get today's and yesterday's day-of-week abbreviations
			Calendar calendar = Calendar.getInstance();
			Date today = calendar.getTime();
			String todayAbbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(today.getTime());
			
			calendar.add(Calendar.DATE, -1);
			Date yesterday = calendar.getTime();
			String yesterdayAbbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(yesterday.getTime());
			
			// Define all days of the week
			String[] allDaysOfWeek = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"};
			
			// Step 1: Add Free Rate Block for all days EXCEPT yesterday
			if(strEnvironment.equals("PROD"))
			{
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free");
			}
			else
			{
				String strTestCaseName = objDictionary.get("strTestCaseName");
				String strFirstLetter = strTestCaseName.substring(0, 1);
				try {Thread.sleep(1500);}catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", strFirstLetter+" Free Parking");
				try {Thread.sleep(1500);}catch (Exception f) {}
			}
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
			try {Thread.sleep(1500);}catch (Exception f) {}
			
			// Uncheck ONLY yesterday for the free rate block
			clsCommonWeb.SENTRYLINK_UncheckOnlyThisDayOfWeek(objDictionary, driver, yesterdayAbbr);
			
			// Set Free Rate Block: 00:00 to 23:59
			String strStartDate = clsCommonWeb.AddDaysToCurrentDate("MM/dd/yyyy","-67");
			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time", "FreeRateBlock|"+strStartDate+"|00:00|23:59");
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting","Save Rate Block", 1,"Local");
			try {Thread.sleep(1500);}catch (Exception f) {}
			
			// Step 2: Add Paid Rate Block for yesterday ONLY
			if(strEnvironment.equals("PROD"))
			{
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Rate");
			}
			else
			{
				String strTestCaseName = objDictionary.get("strTestCaseName");
				String strFirstLetter = strTestCaseName.substring(0, 1);
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "25 buys 15 min fixed");
//				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", strFirstLetter+" Paid Parking");
			}
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
			try {Thread.sleep(1500);}catch (Exception f) {}
			clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, yesterdayAbbr);
			// Uncheck all days EXCEPT yesterday for the paid rate block
//			for (String day : allDaysOfWeek) {
//				if (!day.equals(yesterdayAbbr)) {
//					clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, day);
//				}
//			}
			
			// Set Fixed Rate Block: 00:00 to 23:59 (yesterday only) - This is the paid rate block
			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time", "FixedRateBlock|"+strStartDate+"|00:00|23:59");
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting","Save Rate Block", 1,"Local");
			try {Thread.sleep(1500);}catch (Exception f) {}
			
			System.out.println("Method ("+strMethodName+") took: " + timer.stop());
		}
		catch(Exception e)
		{
			clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary, driver, e+"-"+strMethodName,"Local");
		}
		
		// Send to all meters
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Group", "{ButtonExists} Send to all", 30);
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Send to all", 1,"Local");
		
		// Wait for meters to update
		if(strVirtualMeter.equals("False"))
		{
			System.out.println("Start: WaitUntilMeterFreeEqualsTrue");
			Stopwatch timer2 = Stopwatch.createStarted();
			clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterFreeEqualsTrue} NA", 180, "1","Local");
			System.out.println("Method (WaitUntilMeterFreeEqualsTrue) took: " + timer2.stop());
			String strRemoteDeviceId = objDictionary.get("strRemoteDeviceId");
			if(strRemoteDeviceId != null)
			{
				clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterFreeEqualsTrue} NA", 180, "1","Remote");
			}
		}
		
		// Store the configuration in dictionary
		objDictionary.remove("strFreeParkingStartTime");
		objDictionary.put("strFreeParkingStartTime", "00:00");
		objDictionary.remove("strFreeParkingEndTime");
		objDictionary.put("strFreeParkingEndTime", "23:59");
		objDictionary.remove("strRemainingFreeTimeStart");
		objDictionary.put("strRemainingFreeTimeStart", "00:00:00");
		
		waitForPageLoaded(objDictionary,driver);
		driver.quit();
		clsMeter.SENTRYMETER_AddRateBlocksToAutomationResults(objDictionary,"Local");
	}
	public void SENTRYLINK_UncheckOnlyThisDayOfWeek(Map<String, String> objDictionary, WebDriver driver, String strDayOfWeekAbr) {
	    String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
	    WebElement objCheckbox = null;
	    try {
	        switch (strDayOfWeekAbr) {
	            case "Mon":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.mon']"));
	                break;
	            case "Tue":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.tue']"));
	                break;
	            case "Wed":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.wed']"));
	                break;
	            case "Thu":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.thu']"));
	                break;
	            case "Fri":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.fri']"));
	                break;
	            case "Sat":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.sat']"));
	                break;
	            case "Sun":
	                objCheckbox = driver.findElement(By.xpath("//input[@ng-model='day_checkbox.sun']"));
	                break;
	        }
	        if (objCheckbox != null && objCheckbox.isSelected()) {
	            objCheckbox.click();
	        }
	    } catch (Exception a) {
	        CommonWeb clsCommonWeb = new CommonWeb();
	        clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary, driver, "The Checkbox ("+strDayOfWeekAbr+") did not exist-"+strMethodName, "Local");
	    }
	}
	
	public void SENTRYLINK_SetRateBlocksFreeToRate(Map<String, String> objDictionary, String strFreeTimeMinutes,String strMinutesOfFreeTimeBeforeCurrentTime, String strFreeTimeFirstPayment)
	{
		String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     " + strMethodName + "</font>");
		objDictionary.put("strRateBlockType", "RateBlockToFreeToRate");
		System.out.println("Start: " + strMethodName);
		Stopwatch timer = Stopwatch.createStarted();
		// May want to pass this variable into the function
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		// Dictionary Variables
		String strEnvironment = objDictionary.get("strEnvironment");
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		String strVirtualMeter = objDictionary.get("strVirtualMeter");
		if (strVirtualMeter == null) {strVirtualMeter = "False";}
		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Rate Block Group", "Local");
		// Calculate and Update Free Parking
		String strFreeParkingStartTime = clsCommonWeb.AddTimeToCurrentTime(strMinutesOfFreeTimeBeforeCurrentTime,"HH:mm");
		String strFreeParkingEndTime = clsCommonWeb.AddTimeToCurrentTime(strFreeTimeMinutes, "HH:mm");
		try 
		{
			Date dateObj = new SimpleDateFormat("HH:mm").parse(strFreeParkingStartTime);
			String strFreeParkingStartTime12 = new SimpleDateFormat("h:mm a").format(dateObj);
			objDictionary.remove("strFreeParkingStartTime12");
			objDictionary.put("strFreeParkingStartTime12", strFreeParkingStartTime12);
			dateObj = new SimpleDateFormat("HH:mm").parse(strFreeParkingEndTime);
			String strFreeParkingEndTime12 = new SimpleDateFormat("h:mm a").format(dateObj);
			objDictionary.remove("strFreeParkingEndTime12");
			objDictionary.put("strFreeParkingEndTime12", strFreeParkingEndTime12);
			SimpleDateFormat sdf = new SimpleDateFormat("HH:mm");
			Date dtFreeParkingStartTime = sdf.parse(strFreeParkingStartTime);
			Date dtFreeParkingEndTime = sdf.parse(strFreeParkingEndTime);
			if (dtFreeParkingEndTime.compareTo(dtFreeParkingStartTime) > 0)
			{
				// EndTime > StartTime
				try 
				{
					// Update FreeRateBlock
					driver.findElement(By.xpath("//strong[contains(text(),'FreeRateBlock')]")).click();
					try {Thread.sleep(1500);} catch (Exception f) {}
					clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","FreeRateBlock|" + strFreeParkingStartTime + "|" + strFreeParkingEndTime);
				} 
				catch (Exception e) 
				{
					// Wait is used to wait until listbox is loaded.
					try {Thread.sleep(2000);} catch (Exception f) {}
//					if (strEnvironment.equals("PROD")) 
//					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
//					else 
//					{
						String strTestCaseName = objDictionary.get("strTestCaseName");
						String strFirstLetter = strTestCaseName.substring(0, 1);
						try {Thread.sleep(1500);} catch (Exception f) {}
						clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group",strFirstLetter + " Free Parking");
//					}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
					try {Thread.sleep(1500);} catch (Exception f) {}
					clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Setting","{TextFieldExists} Rate Block Setting~Rate Block Name", 30);
					String strStartDate = clsCommonWeb.AddDaysToCurrentDate("MM/dd/yyyy", "-67");
					clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day","{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time", "FreeRateBlock|"+ strStartDate + "|" + strFreeParkingStartTime + "|" + strFreeParkingEndTime);
				}
			} 
			else if (dtFreeParkingEndTime.compareTo(dtFreeParkingStartTime) < 0) 
			{
				// EndTime < StartTime
				try 
				{
					// Update FreeRateBlock
					driver.findElement(By.xpath("//strong[contains(text(),'FreeRateBlock')]")).click();
					try {Thread.sleep(1500);	} catch (Exception f) {}
					// Current Day
					Calendar calendar = Calendar.getInstance();
					Date date = calendar.getTime();
					String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
					clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekAbr);
					String strStartDate = clsCommonWeb.AddDaysToCurrentDate("MM/dd/yyyy", "-67");
					clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day","{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time","FreeRateBlock|" + strStartDate + "|" + strFreeParkingStartTime + "|23:59");
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1,"Local");
					date = addDay(date, 1);
					String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
					clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver,strDayOfWeekPlus1);
					clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day","{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time","FreeRateBlock|" + strStartDate + "|00:00|" + strFreeParkingEndTime);
				}
				catch (Exception e) 
				{
					// Add FreeRateBlock Current Day
					if (strEnvironment.equals("PROD")) {clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else
					{
						String strTestCaseName = objDictionary.get("strTestCaseName");
						String strFirstLetter = strTestCaseName.substring(0, 1);
						clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group",strFirstLetter + " Free Parking");
					}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
					// Current Day
					Calendar calendar = Calendar.getInstance();
					Date date = calendar.getTime();
					String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
					clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekAbr);
					String strStartDate = clsCommonWeb.AddDaysToCurrentDate("MM/dd/yyyy", "-67");
					clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day","{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time","FreeRateBlock|" + strStartDate + "|" + strFreeParkingStartTime + "|23:59");
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1,"Local");
					try {Thread.sleep(1500);} catch (Exception f) {}
					if (strEnvironment.equals("PROD")) {clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else {
						String strTestCaseName = objDictionary.get("strTestCaseName");
						String strFirstLetter = strTestCaseName.substring(0, 1);
						clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group",strFirstLetter + " Free Parking");
					}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
					date = addDay(date, 1);
					String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
					clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver,strDayOfWeekPlus1);
					clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day","{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time","FreeRateBlock|" + strStartDate + "|00:00|" + strFreeParkingEndTime);
				}
			} 
			else if (dtFreeParkingEndTime.compareTo(dtFreeParkingStartTime) == 0) {System.out.println("The Start and End Date are the same");}
			System.out.println("Method (" + strMethodName + ") took: " + timer.stop());
		} 
		catch (Exception e) 
		{clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary, driver, e + "-" + strMethodName, "Local");}
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Setting", "{ButtonExists} Save Rate Block",30);
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1, "Local");
		if (strVirtualMeter.equals("False")) {clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterFreeEqualsFalse} NA", 35, "1", "Local");}
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Group", "{ButtonExists} Send to all", 30);
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Send to all", 1, "Local");
		if (strVirtualMeter.equals("False")) 
		{
			System.out.println("Start: WaitUntilMeterFreeEqualsTrue");
			Stopwatch timer2 = Stopwatch.createStarted();
			clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterFreeEqualsTrue} NA", 240, "1", "Local");
			System.out.println("Method (WaitUntilMeterFreeEqualsTrue) took: " + timer2.stop());
			String strRemoteDeviceId = objDictionary.get("strRemoteDeviceId");
			if (strRemoteDeviceId != null) {clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterFreeEqualsTrue} NA", 180, "1", "Remote");}
		}
		String strRemainingFreeTimeStart = strFreeParkingStartTime + ":00";
		objDictionary.remove("strFreeParkingEndTime");
		objDictionary.put("strFreeParkingEndTime", strFreeParkingEndTime);
		objDictionary.remove("strRemainingFreeTimeStart");
		objDictionary.put("strRemainingFreeTimeStart", strRemainingFreeTimeStart);
		waitForPageLoaded(objDictionary, driver);
		driver.quit();
		clsMeter.SENTRYMETER_AddRateBlocksToAutomationResults(objDictionary, "Local");
	}
	public void SENTRYLINK_SetRateBlocksHolidayFree(Map<String, String> objDictionary, String strFreeTimeMinutes,String strMinutesOfFreeTimeBeforeCurrentTime, String strFreeTimeFirstPayment)
	{
		String strMethodName = new Object() {}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     " + strMethodName + "</font>");
		objDictionary.put("strRateBlockType", "RateBlockToFreeToRate");
		System.out.println("Start: " + strMethodName);
		Stopwatch timer = Stopwatch.createStarted();
		// May want to pass this variable into the function
		CommonWeb clsCommonWeb = new CommonWeb();
		Meter clsMeter = new Meter();
		// Dictionary Variables
		String strEnvironment = objDictionary.get("strEnvironment");
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		String strVirtualMeter = objDictionary.get("strVirtualMeter");
		if (strVirtualMeter == null) {strVirtualMeter = "False";}
		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Rate Block Group", "Local");
		String strTestCaseName = objDictionary.get("strTestCaseName");
		String strFirstLetter = strTestCaseName.substring(0, 1);
		try {Thread.sleep(1500);} catch (Exception f) {}
		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group","Populate Add Set to This Group", "{L} Add Set to This Group",strFirstLetter + " Free Parking");
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
		try {Thread.sleep(1500);} catch (Exception f) {}
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Setting","{TextFieldExists} Rate Block Setting~Rate Block Name", 30);
		String strStartDate = clsCommonWeb.AddDaysToCurrentDate("MM/dd/yyyy", "0");
		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day","{T} Rate Block Name|{T} End Date|{T} End Time", "Free Holiday|"+strStartDate+"|23:59");
		//Uncheck Non Current Day of Week Values
		Calendar calendar = Calendar.getInstance();
		Date date = calendar.getTime();
		String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
		clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekAbr);
		//Check Previous Day Of Week Value
		Calendar cal = Calendar.getInstance();
		cal.add(Calendar.DATE, -1);
		String strPreviousDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(cal.getTime());
		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Previous Date Checkbox", "{CB} "+strPreviousDayOfWeekAbr,"Checked");
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1, "Local");
		try {Thread.sleep(1500);} catch (Exception f) {}
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Send to all", 1,"Local");
		objDictionary.put("strHolidayFree","True");
		driver.quit();
	}
	public void SENTRYLINK_SetRateBlocksRateToFree(Map<String, String> objDictionary,String strFreeParkingMinutesBeforeStarting, String strFreeTimeMinutes, String strFreeTimeFirstPayment)
	{
  		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
		Meter clsMeter = new Meter();
		CommonWeb clsCommonWeb = new CommonWeb();
		HttpConnections clsHttpConnections = new HttpConnections();
		String strBrowser = objDictionary.get("strBrowser");
  		String strRemotePath = objDictionary.get("strRemotePath");
  		String strVirtualMeter = objDictionary.get("strVirtualMeter");if(strVirtualMeter == null){strVirtualMeter = "False";}
  		String strEnvironment = objDictionary.get("strEnvironment");
  		//Get Meter Id
  		String strMeterId = "";
  		if(strVirtualMeter.equals("True")){strMeterId = clsHttpConnections.Json_VirtualMeterId(objDictionary);}
  		else{strMeterId = clsHttpConnections.Json_MeterId(objDictionary, "Local");}
  		objDictionary.put("strMeterId", strMeterId);
  		threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath,objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Rate Block Group","Local");
		//Calculate and Update Free Parking
		String strFreeParkingStartTime = clsCommonWeb.AddTimeToCurrentTime(strFreeParkingMinutesBeforeStarting,"HH:mm");
		int intEndTimeMinutes = Integer.parseInt(strFreeParkingMinutesBeforeStarting) +Integer.parseInt(strFreeTimeMinutes); 
		String strFreeParkingEndTime = clsCommonWeb.AddTimeToCurrentTime(Integer.toString(intEndTimeMinutes),"HH:mm");
		Date dtFreeParkingStartTime = null;
		Date dtFreeParkingEndTime = null;
		try
		{
			Date dateObj = new SimpleDateFormat("HH:mm").parse(strFreeParkingStartTime);
			String strFreeParkingStartTime12 = new SimpleDateFormat("h:mm a").format(dateObj);
			objDictionary.remove("strFreeParkingStartTime12");objDictionary.put("strFreeParkingStartTime12",strFreeParkingStartTime12);
			SimpleDateFormat sdf = new SimpleDateFormat("HH:mm");
			dtFreeParkingStartTime = sdf.parse(strFreeParkingStartTime);
			dtFreeParkingEndTime = sdf.parse(strFreeParkingEndTime);
		}catch(Exception e){}
		String strRateSet = "Free Parking";
		if(dtFreeParkingEndTime.compareTo(dtFreeParkingStartTime)>0)
		{
	    		//EndTime > StartTime
	    		try
	    		{
	    			//Update FreeRateBlock
	    			driver.findElement(By.xpath("//strong[contains(text(),'FreeRateBlock')]")).click();
	    			try {Thread.sleep(2500);}catch (Exception f) {}
	    			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time", "FreeRateBlock|"+strFreeParkingStartTime +"|"+strFreeParkingEndTime);
	    		}
	    		catch(Exception e)
	    		{
	    			//Add FreeRateBlock
	    			try {Thread.sleep(1500);}catch (Exception f) {}
	    			if(strEnvironment.equals("PROD"))
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else
					{
						String strTestCaseName = objDictionary.get("strTestCaseName");
						String strFirstLetter = strTestCaseName.substring(0, 1);
						try {Thread.sleep(1000);}catch (Exception f) {}
						clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", strFirstLetter+" "+strRateSet);
					}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
	    			clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Setting", "{TextFieldExists} Rate Block Setting~Rate Block Name", 30);
	    			try {Thread.sleep(1000);}catch (Exception f) {}
	    			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time", "FreeRateBlock|"+strFreeParkingStartTime +"|"+strFreeParkingEndTime);
	    		}
	    	}
			else if(dtFreeParkingEndTime.compareTo(dtFreeParkingStartTime)<0)
	    	{
	    		//EndTime < StartTime
	    		try
	    		{
	    			//Update FreeRateBlock
	    			driver.findElement(By.xpath("//strong[contains(text(),'FreeRateBlock')]")).click();
	    			try {Thread.sleep(1500);}catch (Exception f) {}
	    			//Current Day
	    			Calendar calendar = Calendar.getInstance();
	    			Date date = calendar.getTime();
	    			String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
	    			clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary,driver,strDayOfWeekAbr);
	    			try {Thread.sleep(2500);}catch (Exception f) {}
	    			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time", "FreeRateBlock|"+strFreeParkingStartTime +"|23:59");
	    			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting","Save Rate Block", 1,"Local");
	    			try {Thread.sleep(1500);}catch (Exception f) {}
	    			if(strEnvironment.equals("PROD"))
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", strRateSet);}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
	    			date = addDay(date, 1); 
	    			String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
	    			clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary,driver,strDayOfWeekPlus1);
	    			try {Thread.sleep(2500);}catch (Exception f) {}
	    			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time", "FreeRateBlock|00:00|"+strFreeParkingEndTime);
	    		}
	    		catch(Exception e)
	    		{
	    			//Add FreeRateBlock Current Day
	    			if(strEnvironment.equals("PROD"))
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else
					{
						String strTestCaseName = objDictionary.get("strTestCaseName");
						String strFirstLetter = strTestCaseName.substring(0, 1);
						clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", strFirstLetter+" Free Parking");
					}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
	    			//Current Day
	    			Calendar calendar = Calendar.getInstance();
	    			Date date = calendar.getTime();
	    			String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
	    			clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary,driver,strDayOfWeekAbr);
	    			String strStartDate =  clsCommonWeb.AddDaysToCurrentDate("MM/dd/yyyy","-7");
	    			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Date|{T} Start Time|{T} End Time", "FreeRateBlock|"+strStartDate +"|"+strFreeParkingStartTime+"|23:59");
	    			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting","Save Rate Block", 1,"Local");
	    			//Add FreeRateBlock Day + One
	    			date = addDay(date, 1); 
	    			String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
	    			try {Thread.sleep(1500);}catch (Exception f) {}
	    			if(strEnvironment.equals("PROD"))
					{clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", "Free");}
					else
					{
						String strTestCaseName = objDictionary.get("strTestCaseName");
						String strFirstLetter = strTestCaseName.substring(0, 1);
						clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group", "{L} Add Set to This Group", strFirstLetter+" Free Parking");
					}
					clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Add Set to This Group", 1,"Local");
	    			clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary,driver,strDayOfWeekPlus1);
	    			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time", "FreeRateBlock|00:00|"+strFreeParkingEndTime);
	     	}
    	}
    	else if(dtFreeParkingEndTime.compareTo(dtFreeParkingStartTime)==0)
    	{
    		System.out.println("The Start and End Date are the same");
	    }
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting","Save Rate Block", 1,"Local");
		clsCommonWeb.GlobalObjectWait(objDictionary, driver, "Rate Block Group", "{ButtonExists} Send to all", 30);
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group","Send to all", 1,"Local");
		if(strVirtualMeter.equals("False"))
		{clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilARateBlockIdIsNotNeg1} NA", 60, "1","Local");}
		if(strVirtualMeter.equals("False"))
		{clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilFreeParkingBlockExists} NA", 90, "1","Local");}
		else
		{clsMeter.METER_MeterWaitWithMessage(objDictionary,40, "Waiting for Meter Free To Equal False-Spot");}
		//RemainingFreeTimeStart
 		String strMinutesBeforeFreeStart = strFreeParkingStartTime+":00";
  		objDictionary.remove("strMinutesBeforeFreeStart");objDictionary.put("strMinutesBeforeFreeStart", strMinutesBeforeFreeStart);
 		Reporter.log("strMinutesBeforeFreeStart: "+strMinutesBeforeFreeStart);
  		driver.quit();
		clsMeter.SENTRYMETER_AddRateBlocksToAutomationResults(objDictionary,"Local");
	}
