	public void SENTRYLINK_SetRateBlocksRateToNoParking(Map<String, String> objDictionary,String strNoParkingMinutesBeforeStarting, String strNoParkingTimeMinutes) throws Exception
	{
		String strMethondName = new Object() {}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     " + strMethondName + "</font>");
		Meter clsMeter = new Meter();
		CommonWeb clsCommonWeb = new CommonWeb();
		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
		WebDriver driver = getDriver();
		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strCurrentPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Rate Block Group", "Local");
		
		String strNoParkingStartTime = clsCommonWeb.AddTimeToCurrentTime(strNoParkingMinutesBeforeStarting, "HH:mm");
		int intEndTimeMinutes = 0;
		if (strNoParkingMinutesBeforeStarting.contains("-")) {intEndTimeMinutes = Integer.parseInt(strNoParkingTimeMinutes);}
		else {intEndTimeMinutes = Integer.parseInt(strNoParkingMinutesBeforeStarting)+ Integer.parseInt(strNoParkingTimeMinutes);}
		String strNoParkingEndTime = clsCommonWeb.AddTimeToCurrentTime(Integer.toString(intEndTimeMinutes), "HH:mm");
		Date dateObj = new SimpleDateFormat("HH:mm").parse(strNoParkingStartTime);
		String strNoParkingStartTime12 = new SimpleDateFormat("h:mm a").format(dateObj);
		objDictionary.remove("strNoParkingStartTime12");
		objDictionary.put("strNoParkingStartTime12", strNoParkingStartTime12);
		SimpleDateFormat sdf = new SimpleDateFormat("HH:mm");
		Date dtNoParkingStartTime = sdf.parse(strNoParkingStartTime);
		Date dtNoParkingEndTime = sdf.parse(strNoParkingEndTime);
		if (dtNoParkingEndTime.compareTo(dtNoParkingStartTime) > 0) 
		{
			// EndTime > StartTime
			try 
			{
				// Update NoParkingRateBlock
				driver.findElement(By.xpath("//strong[contains(text(),'NoParkingRateBlock')]")).click();
				try {Thread.sleep(2500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","NoParkingRateBlock|" + strNoParkingStartTime + "|" + strNoParkingEndTime);
			} 
			catch (Exception e) 
			{
				// Add NoParkingRateBlock
				String strTestCaseName = objDictionary.get("strTestCaseName");
				String strFirstLetter = strTestCaseName.substring(0, 1);
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group","{L} Add Set to This Group", strFirstLetter+" No Parking");
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
				try {Thread.sleep(2500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","NoParkingRateBlock|" + strNoParkingStartTime + "|" + strNoParkingEndTime);
			}
		} 
		else if (dtNoParkingEndTime.compareTo(dtNoParkingStartTime) < 0) 
		{
			// EndTime < StartTime
			try
			{
				// Update FreeRateBlock
				driver.findElement(By.xpath("//strong[contains(text(),'NoParkingRateBlock')]")).click();
				try {Thread.sleep(1500);} catch (Exception f) {}
				// Current Day
				Calendar calendar = Calendar.getInstance();
				Date date = calendar.getTime();
				String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
				clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekAbr);
				try {Thread.sleep(2500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","NoParkingRateBlock|" + strNoParkingStartTime + "|23:59");
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1, "Local");
				try {Thread.sleep(1500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group","{L} Add Set to This Group", "No Parking");
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
				date = addDay(date, 1);
				String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
				clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekPlus1);
				try {Thread.sleep(2500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","NoParkingRateBlock|00:00|" + strNoParkingEndTime);
			} 
			catch (Exception e)
			{
				// Add FreeRateBlock Current Day
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group","{L} Add Set to This Group", "No Parking");
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
				// Current Day
				Calendar calendar = Calendar.getInstance();
				Date date = calendar.getTime();
				String strDayOfWeekAbr = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
				clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekAbr);
				try {Thread.sleep(2500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","NoParkingRateBlock|" + strNoParkingStartTime + "|23:59");
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1, "Local");
				// Add FreeRateBlock Day + One
				date = addDay(date, 1);
				String strDayOfWeekPlus1 = new SimpleDateFormat("EE", Locale.ENGLISH).format(date.getTime());
				try {Thread.sleep(1500);} catch (Exception f) {}
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Add Set to This Group","{L} Add Set to This Group", "No Parking");
				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
				clsCommonWeb.SENTRYLINK_UncheckRateBlockNonCurrentDayOfWeek(objDictionary, driver, strDayOfWeekPlus1);
				clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting","Populate Specific Times of Day", "{T} Rate Block Name|{T} Start Time|{T} End Time","NoParkingRateBlock|00:00|" + strNoParkingEndTime);
			}
		} 
		else if (dtNoParkingEndTime.compareTo(dtNoParkingStartTime) == 0) {System.out.println("The Start and End Date are the same");}
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Rate Block", 1, "Local");
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Send to all", 1, "Local");
		clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilARateBlockIdIsNotNeg1} NA", 60, "1", "Local");
		if (strNoParkingMinutesBeforeStarting.contains("-")) {clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterNoParkingEqualsTrue} NA", 60, "1", "Local");}
		driver.quit();
		strNoParkingStartTime = strNoParkingStartTime + ":00";
		Reporter.log("strNoParkingStartTime: " + strNoParkingStartTime);objDictionary.put("strNoParkingStartTime", strNoParkingStartTime);
		clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilNoParkingBlockExists} NA", 90, "1", "Local");
		clsMeter.SENTRYMETER_AddRateBlocksToAutomationResults(objDictionary, "Local");
	}
