	public void SENTRYLINK_UnlockAccount(Map<String, String> objDictionary,WebDriver driver, String strUserName)
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		SENTRYLINK_UserLoginIn(objDictionary, driver,"Admin");
		String strEnvironment = objDictionary.get("strEnvironment");
		if(strEnvironment.equals("QA"))
		{
			driver.navigate().to("https://sentrylink.quality.sentry-link.com/admin/users");
		}
		else if(strEnvironment.equals("SG"))
		{
			driver.navigate().to("https://sentrylink.staging.sentry-link.com/admin/users");
		}
		clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email", strUserName);
	 	clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1,"Local");
	 	try {Thread.sleep(2500);} catch (Exception f) {}
	 	String strCondition = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Approved Users", "Unlock", 1, "Exists", "strCondition");
  		if(strCondition.equals("True"))
  		{
  			clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Unlock", 1);
  			try {Thread.sleep(1500);} catch (Exception f) {}
  		}
	 	driver.quit();
	}
