	// *******************************************************************************************************************************
	// Ticket Service 
	// *******************************************************************************************************************************
	public void SENTRYLINK_EnableAndDisableTicketServices(Map<String, String> objDictionary, String strTicketServiceName) {
  		CommonWeb clsCommonWeb = new CommonWeb();
  		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
		threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath,objDictionary);
		WebDriver driver = getDriver();
  		//Store Grace Period Violation Number
  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
  		String strPageName1 = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName1, "Editing Municipality","Local");
  		clsCommonWeb.ClickLink(objDictionary, driver, "Editing Municipality", "Ticket Services", 1);
  		WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10)); // Adjust timeout as necessary
        int maxRetries = 3; // Maximum number of retries to avoid endless loops
        int retryCount = 0;
        while (retryCount < maxRetries) { // Loop to handle potential stale element issues
            try {
                WebElement objTable = clsCommonWeb.GetTableObj(objDictionary, driver, "Ticket Services", "Ticket Services", 1);
                List<WebElement> rows = objTable.findElements(By.tagName("tr"));
                int rowCount = rows.size();
                if (rowCount == 0) {
                    System.out.println("No rows found in the table.");
                    break; // Exit the loop if no rows are found
                }
                boolean rowProcessed = false; // Flag to check if we processed a row
                for (int i = 0; i < rowCount; i++) {
                    WebElement row = rows.get(i);
                    List<WebElement> cells = row.findElements(By.tagName("td"));
                    if (cells.size() > 5) { // Ensure there are enough cells in the row
                        String cellText = cells.get(0).getText(); // Assuming the cell to match is in the first position
                        String strPrimary = cells.get(1).getText();
                        String strEnabled = cells.get(2).getText();
                        if (cellText.equals(strTicketServiceName)) {
                            // Enable Ticket Service
                            if (strEnabled.equals("false") || strPrimary.equals("false")) {
                                WebElement editButton = cells.get(5);
                                wait.until(ExpectedConditions.elementToBeClickable(editButton)).click();
                                clsCommonWeb.PopulateAction(objDictionary, driver, "Ticket Service Settings", "Populate Ticket Service", "{CB} Enabled|{CB} Primary service", "Checked|Checked");
                                clsCommonWeb.ClickButton(objDictionary, driver, "Ticket Service", "Submit", 1, "Local");
                                clsCommonWeb.ClickLink(objDictionary, driver, "Editing Municipality", "Ticket Services", 1);
                                rowProcessed = true;
                            }
                        } else {
                            // Disable Ticket Service
                            if (strEnabled.equals("true") || strPrimary.equals("true")) {
                                WebElement editButton = cells.get(5);
                                wait.until(ExpectedConditions.elementToBeClickable(editButton)).click();
                                clsCommonWeb.PopulateAction(objDictionary, driver, "Ticket Service Settings", "Populate Ticket Service", "{CB} Enabled|{CB} Primary service", "UnChecked|UnChecked");
                                clsCommonWeb.ClickButton(objDictionary, driver, "Ticket Service", "Submit", 1, "Local");
                                clsCommonWeb.ClickLink(objDictionary, driver, "Editing Municipality", "Ticket Services", 1);
                                rowProcessed = true;
                            }
                        }
                    }
                }
                if (!rowProcessed) {
                    System.out.println("No matching rows found or processed.");
                    break; // Exit the while loop if no rows were processed
                }
                // If rows were processed, re-fetch the table and rows
                retryCount++;
                System.out.println("Retrying... Attempt " + retryCount);
                try {Thread.sleep(2000);} catch (InterruptedException e) {e.printStackTrace();}
            } catch (org.openqa.selenium.StaleElementReferenceException e) {
                System.out.println("Caught StaleElementReferenceException. Re-fetching elements...");
                // Optionally add a delay before retrying to account for transient issues
                try {Thread.sleep(2000);} catch (InterruptedException ie) {ie.printStackTrace();}
            }
        }
        if (retryCount >= maxRetries) {
            System.out.println("Exceeded maximum number of retries. Exiting...");
        }
        driver.quit();
    }
