	public void SENTRYLINK_AddRateSet(Map<String, String> objDictionary, WebDriver driver, String strMaximumDuration,String strCreditCardIncrementTime, String strObjLabels, String strObjValues) 
	{
		String strMethodName = new Object() {
		}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     " + strMethodName + "</font>");
		System.out.println("Start: " + strMethodName);
		Stopwatch timer = Stopwatch.createStarted();
		CommonWeb clsCommonWeb = new CommonWeb();
		// Dictionary Variables
		String strRateBlockGroup = objDictionary.get("strRateBlockGroup");
		String strRateType = objDictionary.get("strRateType");
		if (strRateType == null) {strRateType = "Fixed";}
		String strRateSetName = strRateBlockGroup.replace("AutomationRateBlockGroup", "AutomationRateSet")+ strRateType;
		try {Thread.sleep(6000);} catch (Exception e) {}
		String strCondition = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Rate Sets", strRateSetName, 1,"Exists", "");
		if (strCondition.equals("False")) 
		{
			// Check if Create Link Exists
			String strConditional = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Rate Sets","Rate Set Created", 1, "Exists", "strConditional");
			if (strConditional.equals("True")){clsCommonWeb.ClickLink(objDictionary, driver, "Rate Sets", "Rate Set Created", 1);}
			else {clsCommonWeb.ClickButton(objDictionary, driver, "Rate Sets", "Add New Rate Set", 1, "Local");}
			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Rate Set","{T} Rate Set Name|{L} Rate Type", strRateSetName + "|" + strRateType);
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Edit", 1, "Local");
			if (strRateType.equals("Fixed")) {SENTRYLINK_PopulateFixedRateBlock(objDictionary, driver, strMaximumDuration, strCreditCardIncrementTime,strObjLabels, strObjValues);}
			else if (strRateType.equals("Progressive")) {SENTRYLINK_PopulateProgressiveRateBlock(objDictionary, driver, strCreditCardIncrementTime, strObjLabels,strObjValues);}
			try {Thread.sleep(2500);} catch (Exception e) {}
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save", 1, "Local");
			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save Rate Set", 1, "Local");
		}
		System.out.println("Method (" + strMethodName + ") took: " + timer.stop());
	}
	public void SENTRYLINK_AddReservationRateBlockGroup(Map<String, String> objDictionary, WebDriver driver, String strReservationRateType)
  	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		String strReservationBlockGroup = objDictionary.get("strReservationBlockGroup");
  		String strInitialGracePeriod = objDictionary.get("strInitialGracePeriod");
  		String strMaximumDuration = objDictionary.get("strMaximumDuration");
  		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
  		String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
  		int intDefaultMinimumTime = Integer.parseInt(strMeterIncrementTime) * 4;
	  	String strViolationGracePeriod = objDictionary.get("strViolationGracePeriod");
  		String strHandicapInitialGracePeriod = objDictionary.get("strViolationGracePeriod");
  		String strHandicapViolationGrace = objDictionary.get("strHandicapViolationGrace");if(strHandicapViolationGrace == null) {strHandicapViolationGrace = "1";}
  		String strNoParkingGrace = objDictionary.get("strNoParkingGrace");
	  	//Add Rate Block Group
		clsCommonWeb.ClickLink(objDictionary, driver, "Meter Groups", "Rate Block Groups", 1);
		//Start Function
		String strRateSetName = strReservationBlockGroup.replace("ReservationRateBlockGroup", "ReservationRateSet");
		//Check If Rate Set Exists - Functions
		String strRateSetExists = objDictionary.get("strRateSetExists");
		String strObjLabels = "{T} Maximum Duration|{T} Coin Time Puchase Limit|{T} Free Time with First Payment|{T} Credit Card Increment Time|{T} Initial Grace|{T} Violation Grace|{T} Handicap Initial Grace|{T} Handicap Violation Grace|{T} No Parking Grace|{T} Default Minimum Cost|{T} Default Minimum Time";
		clsCommonWeb.ClickLink(objDictionary, driver,"Rate Block Groups", "Rate Sets", 1);
	  	if(strRateSetExists.equals("False"))
		{
	  		//************************
			//ADD RESERVATION RATE SET
	  		//************************
  			//Check if Create Link Exists
  			String strConditional = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Rate Sets", "Rate Set Created", 1, "Exists", "strConditional");
  			if(strConditional.equals("True")){clsCommonWeb.ClickLink(objDictionary, driver, "Rate Sets", "Rate Set Created", 1);}
  			else{clsCommonWeb.ClickButton(objDictionary, driver, "Rate Sets", "Add New Rate Set", 1,"Local");}
  			try {Thread.sleep(1000);}catch (Exception e) {}
  			clsCommonWeb.SENTRYLINK_PopulateRateSet(objDictionary, driver, strReservationRateType);
  			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save Rate Set", 1,"Local");
  		}
	  	else
	  	{
	  		//************************
			//UPDATE RESERVATION RATE SET
	  		//************************
	  		clsCommonWeb.ClickLink(objDictionary, driver,"Rate Sets", strRateSetName+strReservationRateType, 1);
	  		clsCommonWeb.SENTRYLINK_PopulateRateSet(objDictionary, driver, strReservationRateType);
  			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save Rate Set", 1,"Local");
	  	}
	  	clsCommonWeb.ClickLink(objDictionary, driver, "Rate Set", "Rate Block Groups", 1);
	  	//Add Rate Block
  		String strConditional = clsCommonWeb.ConditionalStepLink(objDictionary, driver, "Rate Block Groups", "Rate Block Group Created", 1, "Exists", "");
		if(strConditional.equals("False"))
		{clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Groups", "Add New", 1,"Local");}
		clsCommonWeb.ClickLink(objDictionary, driver, "Rate Block Groups", "Rate Block Group Created", 1);
		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Group", "Populate Rate Block Group Name", "{T} Rate Block Group Name|{L} Add Set to This Group", strReservationBlockGroup+"|"+strRateSetName+strReservationRateType);
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Setting", "Save Name", 1,"Local");
		clsCommonWeb.SENTRYLINK_ClearRateFromRateBlockTable(objDictionary,driver);
		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Block Group", "Add Set to This Group", 1,"Local");
		try {Thread.sleep(1000);}catch (Exception e) {}
		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Block Setting", "Populate Rate Block Name", "{T} Rate Block Name", strReservationBlockGroup);
		String strMinutesBeforeReservation = objDictionary.get("strMinutesBeforeReservation");
		String strReservationTimeMinutes = objDictionary.get("strReservationTimeMinutes");
		clsCommonWeb.SENTRYLINK_PopulateReservationStartAndEndTime(objDictionary,driver,strMinutesBeforeReservation, strReservationTimeMinutes,strReservationRateType);
	}
	public void SENTRYLINK_PopulateRateSet(Map<String, String> objDictionary, WebDriver driver, String strReservationRateType)
  	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		String strReservationBlockGroup = objDictionary.get("strReservationBlockGroup");
  		String strInitialGracePeriod = objDictionary.get("strInitialGracePeriod");
  		String strMaximumDuration = objDictionary.get("strMaximumDuration");
  		String strFreeTimeFirstPayment = objDictionary.get("strFreeTimeFirstPayment");
  		String strMeterIncrementTime = objDictionary.get("strMeterIncrementTime");
  		int intDefaultMinimumTime = Integer.parseInt(strMeterIncrementTime) * 4;
	  	String strViolationGracePeriod = objDictionary.get("strViolationGracePeriod");
  		String strHandicapInitialGracePeriod = objDictionary.get("strViolationGracePeriod");
  		String strHandicapViolationGrace = objDictionary.get("strHandicapViolationGrace");if(strHandicapViolationGrace == null) {strHandicapViolationGrace = "1";}
  		String strNoParkingGrace = objDictionary.get("strNoParkingGrace");
  		String strObjLabels = "{T} Maximum Duration|{T} Coin Time Puchase Limit|{T} Free Time with First Payment|{T} Credit Card Increment Time|{T} Initial Grace|{T} Violation Grace|{T} Handicap Initial Grace|{T} Handicap Violation Grace|{T} No Parking Grace|{T} Default Minimum Cost|{T} Default Minimum Time";
  		//Start Function
  		String strRateSetName = strReservationBlockGroup.replace("ReservationRateBlockGroup", "ReservationRateSet");
  		//Function
		if(strReservationRateType.equals("Fixed"))
		{
			//FIXED Rate Set
			try {Thread.sleep(1000);}catch (Exception e) {}
			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Rate Set", "{T} Rate Set Name|{L} Rate Type", strRateSetName+strReservationRateType+"|"+strReservationRateType);
			String strObjValues = strMaximumDuration+"|"+strMaximumDuration+"|"+strFreeTimeFirstPayment+"|"+strMeterIncrementTime+"|"+strInitialGracePeriod+"|"+strViolationGracePeriod+"|"+strHandicapInitialGracePeriod+"|"+strHandicapViolationGrace+"|"+strNoParkingGrace+"|100|"+intDefaultMinimumTime;
	  		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Free Time with Free Payment", strObjLabels, strObjValues);
			String strFamily = objDictionary.get("strFamily");if(strFamily == null) {strFamily = "Normal";}
  	  		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Rate Set", "{L} Family",strFamily);
  	  	  	String strCondition = clsCommonWeb.ConditionalStepTextField(objDictionary, driver, "Rate Set", "Buys Minutes", 1, "Exists", "");
	  		if(strCondition.equals("False"))
	  		{
	  			try {Thread.sleep(4000);}catch (Exception e) {}
	  			clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Edit", 1,"Local");
	  			strCondition = clsCommonWeb.ConditionalStepTextField(objDictionary, driver, "Rate Set", "Buys Minutes", 1, "Exists", "");
	  			if(strCondition.equals("False"))
		  		{
	  				clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Add Row", 1,"Local");
		  		}
	  		}
  			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Buys Minutes", "{T} Price|{T} Buys Minutes|{T} Max Time", "25|"+strMeterIncrementTime+"|"+strMaximumDuration);
  	  		clsCommonWeb.ClickButton(objDictionary, driver, "Rate Set", "Save", 1,"Local");
		}
		else
		{
			//FREE PARKIN Rate Set
			clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Rate Set", "{T} Rate Set Name|{L} Rate Type", strRateSetName+strReservationRateType+"|Free Parking");
			String strObjValues = strMaximumDuration+"|"+strMaximumDuration+"|"+strFreeTimeFirstPayment+"|"+strMeterIncrementTime+"|"+strInitialGracePeriod+"|"+strViolationGracePeriod+"|"+strHandicapInitialGracePeriod+"|"+strHandicapViolationGrace+"|"+strNoParkingGrace+"|100|"+intDefaultMinimumTime;
	  		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Free Time with Free Payment", strObjLabels, strObjValues);
			String strFamily = objDictionary.get("strFamily");
  	  		clsCommonWeb.PopulateAction(objDictionary, driver, "Rate Set", "Populate Rate Set", "{L} Family",strFamily);
  	  	}
  	}
