	public void SENTRYLINK_UpdateMaintenanceMode(Map<String, String> objDictionary,Session sessionMeter,String strMaintenanceStatus,String strSpotNumber,String strMaintenanceReason,String strHostType)
  	{
  		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
  		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
  		System.out.println("Start: "+strMethodName);
  		Stopwatch timer = Stopwatch.createStarted();
  		CommonWeb clsCommonWeb = new CommonWeb();
  		Meter clsMeter = new Meter();
  		String strTestCaseName = objDictionary.get("strTestCaseName");
  		String strBrowser = objDictionary.get("strBrowser");
  		String strRemotePath = objDictionary.get("strRemotePath");
  		String strMeterGroup = objDictionary.get("strMeterGroup");
  		//Get Device Id
  		String strDeviceId = "";
  		if(strHostType.equals("Local")){strDeviceId = objDictionary.get("strDeviceId");}
  		else if(strHostType.contains("Remote")){strDeviceId = objDictionary.get("strRemoteDeviceId"+strHostType.substring(strHostType.length() - 1));}
  		clsMeter.StoreDumpStackValuesInDictionary(objDictionary,null,sessionMeter,"1",strHostType,"UpdateMaintenanceMode");
  		String strMaintenanceModeEnabled = objDictionary.get("strMaintenanceModeEnabled");
  		String strNumberOfSpots = clsMeter.METER_GetSYS_NUMBER_OF_SPOTS(objDictionary,sessionMeter);
  		String strCurrentMaintenanceMode2 = "False";
  		if(strMaintenanceStatus.equals("Disable"))
  		{
  			//DISABLE
  			if(strSpotNumber.equals(""))
  			{
  				//Disable all spots
  				HttpConnections clsHttpConnections = new HttpConnections();
  				String strSentryLinkMaintenanceMode = clsHttpConnections.HTTPCONNECTIONS_AnyMeterSpotMainteanceMode(objDictionary, strHostType);
  				if(strSentryLinkMaintenanceMode.equals("true"))
  				{
  					threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser,strRemotePath,objDictionary);
  	  		  		WebDriver driver = getDriver();
  	  		  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
  	  		  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
  	  		  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
  	  		  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName, "AutomationMeterGroup",strHostType);
  	  		  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
  	  		  		String strMaintenanceIncludesUnknown = CheckMaintenanceModeTableIncludesUnknown(objDictionary, driver, "Meter", "Meter Spots", 1);
  	  		  		if(strMaintenanceIncludesUnknown.equals("True"))
  	  		  		{
  			  			//Clear Mainenance Mode from all spots
  				  		clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{CB} Maintenance All", "Checked");
  				  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Clear All", 1, strHostType);
  				  	}
  	  		  		clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{CB} Maintenance All", "Checked");
	  		  		//Check If Sentry Link shows Meter in Maintenance Mode if Not put meter in maintenance mode and remove it. (BUG)
	  		  		String strConditional = clsCommonWeb.ConditionalStepButton(objDictionary, driver, "Meter", "Clear All", 1, "Visible-Class", "");
	  		  		if(strConditional.equals("False"))
	  		  		{
	  		  			//Find all spot that are still in maintenance mode,
	  		  			if(strCurrentMaintenanceMode2.equals("True"))
			  			{
			  				clsMeter.StoreDumpStackValuesInDictionary(objDictionary,null,sessionMeter,"2",strHostType,"UpdateMaintenanceMode");
			  			}
			  			//Get Current Maintenance Mode
			  	    	String strMaintenanceMode = objDictionary.get("strMaintenanceMode");
			  	    	switch (strMaintenanceMode)
			  	    	{
				  	    	case "FreeParking":strMaintenanceReason = "Free Parking";break;
			  	    		case "Parking":strMaintenanceReason = "Maint. Parking";break;
			  	    		case "UnenforcedParking":strMaintenanceReason = "Maint. Unenforced";break;
			  	    		case "NoParking":strMaintenanceReason = "No Parking";break;
			  	    	}
			  	    	clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{L} Maintenance Reason|{CB} Maintenance All", strMaintenanceReason+"|Checked");
			  	    	clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Apply", 1,"Local");
			  	    	try {Thread.sleep(5000);}catch (Exception e) {} 
			  	    	clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{CB} Maintenance All", "Checked");
			  		}
	  		  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Clear All", 1, strHostType);
	  		  		//WaitUntilMaintenanceMode False for All Spaces
	  		  		for (int i = 0; i < Integer.parseInt(strNumberOfSpots); i++) 
	  		  		{
	  		  			int intSpotNumber = i + 1;
	  		  			clsMeter.GlobalWait(objDictionary,driver,sessionMeter,"{WaitUntilMeterInMaintEqualsFalse} NA",25,Integer.toString(intSpotNumber),strHostType);
	  		  		}
	  		  		driver.quit();
  				}
  				else
  				{
  					//Check Meter Side Maintaince Mode (Bug 161327749)
  					String strCurrentMaintenanceMode = clsMeter.METER_GetCurrentMaintenanceMode(objDictionary, null,sessionMeter, "1",strHostType);
  			  		if(strCurrentMaintenanceMode.equals("True"))
  			  		{
	  			  		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser,strRemotePath,objDictionary);
	  	  		  		WebDriver driver = getDriver();
	  	  		  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
	  	  		  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
	  	  		  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
	  	  		  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName, "AutomationMeterGroup",strHostType);
	  	  		  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
	  	  		  		//Check If Sentry Link shows Meter in Maintenance Mode if Not put meter in maintenance mode and remove it. (BUG)
		  		  		String strConditional = clsCommonWeb.ConditionalStepButton(objDictionary, driver, "Meter", "Clear All", 1, "Visible-Class", "");
		  		  		if(strConditional.equals("False"))
		  		  		{
		  		  			clsMeter.StoreDumpStackValuesInDictionary(objDictionary,null,sessionMeter,"2",strHostType,"UpdateMaintenanceMode");
				  			//Get Current Maintenance Mode
				  	    	String strMaintenanceMode = objDictionary.get("strMaintenanceMode");
				  	    	switch (strMaintenanceMode)
				  	    	{
					  	    	case "FreeParking":strMaintenanceReason = "Free Parking";break;
				  	    		case "Parking":strMaintenanceReason = "Maint. Parking";break;
				  	    		case "UnenforcedParking":strMaintenanceReason = "Maint. Unenforced";break;
				  	    		case "NoParking":strMaintenanceReason = "No Parking";break;
				  	    	}
				  	    	clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{L} Maintenance Reason|{CB} Maintenance All", strMaintenanceReason+"|Checked");
				  	    	clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Apply", 1,"Local");
				  	    	try {Thread.sleep(5000);}catch (Exception e) {} 
				  	    	clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{CB} Maintenance All", "Checked");
				  		}
		  		  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Clear All", 1, strHostType);
		  		  		//WaitUntilMaintenanceMode False for All Spaces
		  		  		for (int i = 0; i < Integer.parseInt(strNumberOfSpots); i++) 
		  		  		{
		  		  			int intSpotNumber = i + 1;
		  		  			clsMeter.GlobalWait(objDictionary,driver,sessionMeter,"{WaitUntilMeterInMaintEqualsFalse} NA",25,Integer.toString(intSpotNumber),strHostType);
		  		  		}
		  		  		driver.quit();
  			  		}
  				}
  			}
  			else
  			{
  				HttpConnections clsHttpConnections = new HttpConnections();
  				String strSentryLinkMaintenanceMode = clsHttpConnections.HTTPCONNECTIONS_IsMeterSpotMainteanceMode(objDictionary, strHostType, strSpotNumber);
  				if(strSentryLinkMaintenanceMode.equals("true"))
  				{
	  				//Disable Specific Spot
	  				threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser,strRemotePath,objDictionary);
	  		  		WebDriver driver = getDriver();
	  		  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
	  		  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
	  		  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
	  		  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName, "AutomationMeterGroup",strHostType);
	  		  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
	  		  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "ClearSpot", Integer.parseInt(strSpotNumber), strHostType);
			  		//Vechile has to Exit Before Maintenance Mode changes on Meter
	  		  		String strBegunVariable = objDictionary.get("strBegunVariable");
	  		  		String strValidTimePurchased = objDictionary.get("strValidTimePurchased");
	  		  		if(strBegunVariable.equals("True") && strValidTimePurchased.equals("0"))
	  		  		{driver.quit();}
	  		  		else
	  		  		{
	  		  			clsMeter.GlobalWait(objDictionary,null,sessionMeter,"{WaitUntilMeterInMaintEqualsFalse} 1",15,strSpotNumber,strHostType);
	  		  			driver.quit();
	  		  		}
  				}
  			}
  		}
  		else
  		{
  			//ENABLE
  			if(strSpotNumber.equals(""))
  			{
  				System.out.println("MIH");
  			}
  			else
  			{
  				HttpConnections clsHttpConnections = new HttpConnections();
  				String strSentryLinkMaintenanceMode = clsHttpConnections.HTTPCONNECTIONS_IsMeterSpotMainteanceMode(objDictionary, strHostType, strSpotNumber);
  				if(strSentryLinkMaintenanceMode.equals("false"))
  				{
	  				//ENABLE A Specific Spot
	  				threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser,strRemotePath,objDictionary);
	  		  		WebDriver driver = getDriver();
	  		  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
	  		  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
	  		  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
	  		  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName, "AutomationMeterGroup",strHostType);
	  				clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
	  				clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{L} Maintenance Reason|{CB} Maintenance Spot "+strSpotNumber, strMaintenanceReason+"|Checked");
		  			//Click Set to maintenance mode
			  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Apply", 1,"Local");
			  		//Check If Spot is Occupied
			  		String strBegunVariable = clsMeter.GetMeterBegunValue(objDictionary,sessionMeter,strSpotNumber,strHostType);
			  		if(strBegunVariable.equals("False"))
			  		{
				  		//Wait Until Meter Spot In Maintenance Mode
				  		clsMeter.GlobalWait(objDictionary, driver,sessionMeter,"{WaitUntilMeterInMaintEqualsTrue} NA", 30,strSpotNumber,strHostType);
					}
			  		//START InsertCoinApplyPayment Log Trace
		  	  		//Validate Meter Color changes
		  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Edit Spot", "Settings", 1);
		  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", strMeterGroup, 1);
		  	  		try {Thread.sleep(1000);}catch (Exception e) {} 
		  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter Group", "Meters", 1);
		  	  		WebElement objLink  = clsCommonWeb.GetLinkObj(objDictionary, driver, "Meter Group", strDeviceId,1);
		  	  		if (objLink == null){clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Meter (" + strDeviceId + ") at index (1) did not exist","Local");}
		  	  		String strParentClass = objLink.findElement(By.xpath("..")).getAttribute("class");
			  	  	if(strParentClass.contains("maintenance_mode")){Reporter.log("The meter in Sentry Link changed to Maintenance Mode");}
			  		else{clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The meter in Sentry Link did not change to Maintenance Mode");}
			  	  	driver.quit();
  				}
  			}
  		}
  		System.out.println("Method ("+strMethodName+") took: " + timer.stop());
  	}
	public void SENTRYLINK_UpdateMaintenanceMode(Map<String, String> objDictionary, String strMaintenanceStatus, String strSpotNumber, String strMaintenanceReason, String strHostType)
  	{
  		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
  		Reporter.log("<font color='orange'>     "+strMethodName+"</font>");
  		System.out.println("Start: "+strMethodName);
  		Stopwatch timer = Stopwatch.createStarted();
  		CommonWeb clsCommonWeb = new CommonWeb();
  		Meter clsMeter = new Meter();
  		String strTestCaseName = objDictionary.get("strTestCaseName");
  		String strBrowser = objDictionary.get("strBrowser");
  		String strRemotePath = objDictionary.get("strRemotePath");
  		String strMeterGroup = objDictionary.get("strMeterGroup");
  		String strDeviceId = "";
  		if(strHostType.equals("Local")){strDeviceId = objDictionary.get("strDeviceId");}
		else{strDeviceId = objDictionary.get("strRemoteDeviceId");}
  		threadDriver = clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath, objDictionary);
  		WebDriver driver = getDriver();
  		String strCurrentMaintenanceMode = clsMeter.METER_GetCurrentMaintenanceMode(objDictionary, driver, "1",strHostType);
  		String strNumberOfSpots = clsMeter.METER_GetSYS_NUMBER_OF_SPOTS(objDictionary, null,strHostType);
  		String strCurrentMaintenanceMode2 = "False";
  		if(!strNumberOfSpots.equals("1")){strCurrentMaintenanceMode2 = clsMeter.METER_GetCurrentMaintenanceMode(objDictionary, driver, "2",strHostType);}
  		if(strMaintenanceStatus.equals("Disable"))
  		{
  			if(strCurrentMaintenanceMode.equals("True")||strCurrentMaintenanceMode2.equals("True"))
  			{
  		  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
  		  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
  		  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
  		  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName, "AutomationMeterGroup",strHostType);
  		  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
  				//Populate Maintenance Mode
		  		clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{CB} Maintenance All", "Checked");
		  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Clear All", 1, strHostType);
		  		//WaitUntilMaintenanceMode = False
		  		clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterInMaintEqualsFalse} 1", 60,"1",strHostType);
		  		clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterInMaintEqualsFalse} 1", 60,"2",strHostType);
		  		try {Thread.sleep(3000);}catch (Exception e) {} 
  			}
  		}
  		else
  		{
	  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver); 
	  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver); 
	  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
	  		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary,driver, strPageName, "AutomationMeterGroup",strHostType);
	  		if(strSpotNumber.equals(""))
	  		{
	  			//START MaintenanceMode Log Trace
		  		clsMeter.METER_StartLogTrace2(objDictionary,driver,"MaintenanceMode"); 
		  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
	  			//Populate Maintenance Mode
		  		clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{L} Maintenance Reason|{CB} Maintenance All", strMaintenanceReason+"|Checked");
				//Click Set to maintenance mode
		  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Apply", 1,"Local");
		  		String strBegunVariable = clsMeter.GetMeterBegunValue(objDictionary,"1",strHostType);
		  		if(strBegunVariable.equals("False")){clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterInMaintEqualsTrue} 1", 45,"1",strHostType);}
		  		strBegunVariable = clsMeter.GetMeterBegunValue(objDictionary,"2",strHostType);
		  		if(strBegunVariable.equals("False")){clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterInMaintEqualsTrue} 2", 45,"1",strHostType);}
		  		//Validate Meter Color changes
		  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Details", 1);
	  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", strMeterGroup, 1);
	  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Meters", 1);
	  	  		WebElement objLink  = clsCommonWeb.GetLinkObj(objDictionary, driver, "Meter Group", strDeviceId,1);
		  		if (objLink == null){clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Meter (" + strDeviceId + ") at index (1) did not exist","Local");}
		  		String strParentClass = objLink.findElement(By.xpath("..")).getAttribute("class");
		  		//Validate Meter in Sentry Link changes to Maintenance Mode
		  		if(strParentClass.contains("maintenance_mode")){Reporter.log("The meter in Sentry Link changed to Maintenance Mode");}
		  		else{clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The meter in Sentry Link did not change to Maintenance Mode");}
		  		//Validate Meter Logs
		  		//try {clsMeter.METER_CopyLogTraceLocally2(objDictionary, driver, strTestCaseName+"_MaintenanceMode","MaintenanceMode");}catch (Exception e) {}
		  	}
	  		else
	  		{
	  			clsCommonWeb.ClickLink(objDictionary, driver, "Meter", "Spots", 1);
	  			clsCommonWeb.PopulateAction(objDictionary, driver, "Meter", "Populate Maintenance Values", "{L} Maintenance Reason|{CB} Maintenance Spot "+strSpotNumber, strMaintenanceReason+"|Checked");
	  			//Click Set to maintenance mode
		  		clsCommonWeb.ClickButton(objDictionary, driver, "Meter", "Apply", 1,"Local");
		  		//Check If Spot is Occupied
		  		String strBegunVariable = clsMeter.GetMeterBegunValue(objDictionary,strSpotNumber,strHostType);
		  		if(strBegunVariable.equals("False"))
		  		{
			  		//Wait Until Meter Spot In Maintenance Mode
			  		clsMeter.GlobalWait(objDictionary, driver, "{WaitUntilMeterInMaintEqualsTrue} "+strSpotNumber, 30,"1",strHostType);
		  		}
		  		//START InsertCoinApplyPayment Log Trace
	  	  		clsMeter.METER_StartLogTrace2(objDictionary,driver, "MaintenanceMode"); 
	  	  		//Validate Meter Color changes
	  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Edit Spot", "Settings", 1);
	  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter", strMeterGroup, 1);
	  	  		try {Thread.sleep(1000);}catch (Exception e) {} 
	  	  		clsCommonWeb.ClickLink(objDictionary, driver, "Meter Group", "Meters", 1);
	  	  		WebElement objLink  = clsCommonWeb.GetLinkObj(objDictionary, driver, "Meter Group", strDeviceId,1);
	  	  		if (objLink == null){clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Meter (" + strDeviceId + ") at index (1) did not exist","Local");}
	  	  		String strParentClass = objLink.findElement(By.xpath("..")).getAttribute("class");
		  	  	if(strParentClass.contains("maintenance_mode")){Reporter.log("The meter in Sentry Link changed to Maintenance Mode");}
		  		else{clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The meter in Sentry Link did not change to Maintenance Mode");}
	  			//VALIDATE METER LOGS - Screen Change
		  	  	//try {clsMeter.METER_CopyLogTraceLocally2(objDictionary, driver, strTestCaseName+"_MaintenanceMode","MaintenanceMode");}catch (Exception e) {}
	  		}
  		}
  		waitForPageLoaded(objDictionary,driver);
  		driver.quit();
  		System.out.println("Method ("+strMethodName+") took: " + timer.stop());
  	}

