	public String CheckMaintenanceModeTableIncludesUnknown(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strTableName, int intTableIndex)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objTable = GetTableObj(objDictionary, driver, strPageName, strTableName, intTableIndex);
		if (objTable == null){UpdateErrorMessageWithPivotalData(objDictionary,driver,"The table (" + strTableName + ") with index (" + intTableIndex + ") did not exist)-"+strMethondName,"Local");}
		if(objTable.findElements(By.xpath("./tbody/tr")).size() > 0)
		{
			List<WebElement> allRows = objTable.findElements(By.xpath("./tbody/tr")); 
			for (WebElement objRow : allRows) 
			{ 
				WebElement objCell = objRow.findElement(By.xpath("./td[4]"));
				System.out.println(objCell.getText());
				if(objCell.getText().equals("Unknown (Temporary) Clear"))
				{
					return "True";
				}
			}
		}
		return "False";
	}
	public void SENTRYLINK_PopulateOtherSubscriptions(Map<String, String> objDictionary, String strReason, String strCheckboxValue, String strAlertType)
  	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		String strTableName = "Other Subscriptions";
  		int intTableIndex = 1;
  		int intColumnNumber = 1;
  		int intRowNumber = 1;
  		String strBrowser = objDictionary.get("strBrowser");
		String strRemotePath = objDictionary.get("strRemotePath");
  		String strUniqueId = objDictionary.get("strUniqueId");
  		String strMunicipality = objDictionary.get("strMunicipality");
  		threadDriver =clsCommonWeb.SetDriverBrowser(strBrowser, strRemotePath,objDictionary);
  		WebDriver driver = getDriver();
  		clsCommonWeb.SENTRYLINK_OpenLoginPage(objDictionary, driver);
  		clsCommonWeb.SENTRYLINK_AdminLoginIn(objDictionary, driver);
		String strUserName = strUniqueId+strMunicipality.replace(" ","").replace(",", "")+"peo"+"@gmail.com";
  		String strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strPageName, "Approved Users","Local");
		clsCommonWeb.PopulateAction(objDictionary, driver, "Approved Users", "Populate User Search", "{T} Email", strUserName.toLowerCase());
 		clsCommonWeb.ClickButton(objDictionary, driver, "Approved Users", "Search", 1,"Local");
 		try {Thread.sleep(4000);}catch (Exception f) {}
 		clsCommonWeb.ClickLink(objDictionary, driver, "Approved Users", "Edit", 1);
 		try {Thread.sleep(1500);}catch (Exception f) {}
 		WebElement objTable = clsCommonWeb.GetTableObj(objDictionary,driver, "Edit User", strTableName,intTableIndex);
		if (objTable == null){clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The table (" + strTableName + ") with index (" + intTableIndex + ") did not exist)-StoreTableValue","Local");}
		String strCheckBoxColumn = "1";
		switch (strAlertType)
		{
			case "text":
				strCheckBoxColumn = "2";break;
			case "email":
				strCheckBoxColumn = "3";break;
			case "app":
				strCheckBoxColumn = "4";break;
		}
		System.out.println("NumberOfRows: "+objTable.findElements(By.xpath("./tbody/tr")).size());
		if(objTable.findElements(By.xpath("./tbody/tr")).size() > 0)
		{
			List<WebElement> allRows = driver.findElements(By.xpath("//div[@id='other-subscriptions']/table[contains(@class,'table table-sm')]/tbody/tr")); 
			System.out.println("NumberOfColums:"+allRows.size());
			for (WebElement objRow : allRows) 
			{ 
				System.out.println("NumberOfColums: "+objRow.findElements(By.xpath("./td")).size());
				if(objRow.findElements(By.xpath("./td")).size() > intColumnNumber)
				{
					WebElement objCell = objRow.findElement(By.xpath("./td["+intColumnNumber+"]"));
					System.out.println(objCell.getText());
					if(objCell.getText().equalsIgnoreCase(strReason))
					{
						try
						{
							WebElement objCheckbox = objRow.findElement(By.xpath("./td["+strCheckBoxColumn+"]//input[@type='checkbox']"));
							if (strCheckboxValue == "Checked"){if (!objCheckbox.isSelected()){objCheckbox.click();}}
			                else{if (objCheckbox.isSelected()){objCheckbox.click();}}
							Reporter.log("The Checkbox in Table ("+strTableName+") that contained ("+strReason+") was set to ("+strCheckboxValue+")");
							clsCommonWeb.ClickButton(objDictionary, driver, "Edit User", "Save Other Subscriptions", 1,"Local");
							try {Thread.sleep(1500);}catch (Exception f) {}
							driver.quit();
							return;
						}
						catch(Exception e)
						{clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Checkbox in row ("+intRowNumber+") of the ("+strTableName+") table did not exist","Local");}
				    }
				}
			    intRowNumber++;
			}
			clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Value ("+strReason+") did not exist in the ("+strTableName+") Table","Local");
	    }
		else
		{clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"There was no rows in the ("+strTableName+") table","Local");}
  	}
