	public void SENTRYLINK_ValidateImageCountEqualExpected(Map<String, String> objDictionary,WebDriver driver,int intTotalImageSeconds, int intTotalNumberOfViolations, String strShortExitSession)
  	{
  		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		Reporter.log("<font color='orange'>     "+strMethondName+"</font>");
  		CommonWeb clsCommonWeb = new CommonWeb();
  		Meter clsMeter = new Meter();
  		String strParkingImageDurationExit  = clsMeter.METER_GetPARKING_IMAGE_DURATION_EXIT(objDictionary,driver);
      	if(intTotalImageSeconds == 0)
  		{
  			//Only Exit Message Expected
  			List<WebElement> uls = driver.findElements(By.xpath("//div[contains(@class,'jcarousel jcarousel-navigation')]//ul//li"));
		    	int intActualNumberOfImages = uls.size();
		    	if (intActualNumberOfImages == 1)
		    	{
		    		Reporter.log("The actual number of images ("+intActualNumberOfImages+") was correct");
		    	}
		    	else
		    	{
		    		clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Actual Number Of Images ("+intActualNumberOfImages+") was greater than Expected Number Of Images (1)","Local");
	        	}
  		}
      	else if (!strParkingImageDurationExit.equals("1"))
      	{
      		List<WebElement> uls = driver.findElements(By.xpath("//div[contains(@class,'jcarousel jcarousel-navigation')]//ul//li"));
		    	int intActualNumberOfImages = uls.size();
		    	Reporter.log("Actual Total Images: "+intActualNumberOfImages);
		    	String strParkingImageCountViolation = clsMeter.METER_GetPARKING_IMAGE_COUNT_VIOLATION(objDictionary, driver);
		    	int intExpectedNumberOfViolationImages = (Integer.parseInt(strParkingImageCountViolation) + 1) * intTotalNumberOfViolations;
		    	Reporter.log("Expected Number Of Violation Images: "+intExpectedNumberOfViolationImages);
		    	int intExpectedNumberOfImages = 0;
	  		if(strShortExitSession.equals("True"))
	  		{
	  			//ShortExitSession will only be 1 second worth of exit pictures
	  			intExpectedNumberOfImages = (intTotalImageSeconds - Integer.parseInt(strParkingImageDurationExit) + 1) * 5 + intExpectedNumberOfViolationImages;
	  		}
		    	else
		    	{
		    		intExpectedNumberOfImages = intTotalImageSeconds * 5 + intExpectedNumberOfViolationImages;
		    	}
	  		Reporter.log("Expected Number Images ("+intTotalImageSeconds+" * 5) With Violation Images: "+intExpectedNumberOfImages);
		    	int intDifferenceBetweenExpectedAndActual = intExpectedNumberOfImages - intActualNumberOfImages;
		    	Reporter.log("Difference Between Expected and Actual Images: "+intDifferenceBetweenExpectedAndActual);
		    	int intExpectedExitImages = 0;
		    	intExpectedExitImages = Integer.parseInt(strParkingImageDurationExit) * 5/2;
		    Reporter.log("Expected Exit Images: "+intDifferenceBetweenExpectedAndActual);
		    	if (intDifferenceBetweenExpectedAndActual - 2 <= intExpectedExitImages && intDifferenceBetweenExpectedAndActual <= intExpectedExitImages+2)
		    	{
		    		Reporter.log("The actual number of images ("+intActualNumberOfImages+") was within the correct range");
		    	}
	  		else
	  		{
	  			if(intDifferenceBetweenExpectedAndActual - 1 > intExpectedExitImages)
	  			{
		  			int intExpectedNumberOfImagesMinusExpectedExitImages = intExpectedNumberOfImages - intExpectedExitImages;
		  			clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Actual Number Of Images ("+intActualNumberOfImages+") was less than Expected Number Of Images("+intExpectedNumberOfImagesMinusExpectedExitImages+")","Local");
	        	}
	  			else
	  			{
	  				int intExpectedNumberOfImagesMinusExpectedExitImages = intExpectedNumberOfImages - intExpectedExitImages;
		  			clsMeter.UpdateErrorMessageWithPivotalData(objDictionary, driver, "The Actual Number Of Images ("+intActualNumberOfImages+") was greater than Expected Number Of Images("+intExpectedNumberOfImagesMinusExpectedExitImages+")");
	        	}
	  		}
	    }
  		else
  		{
	  		String strParkingImageCountViolation = clsMeter.METER_GetPARKING_IMAGE_COUNT_VIOLATION(objDictionary,driver);
	  		//The +1 is a extra picture with different contrast
	  		int intExpectedNumberOfViolationImages = (Integer.parseInt(strParkingImageCountViolation) + 1) * intTotalNumberOfViolations;
	  		int intExpectedNumberOfImages = intTotalImageSeconds * 5 + intExpectedNumberOfViolationImages;
	      	List<WebElement> uls = driver.findElements(By.xpath("//div[contains(@class,'jcarousel jcarousel-navigation')]//ul//li"));
	    	int intActualNumberOfImages = uls.size();
	    	if (intExpectedNumberOfImages - 5 <= intActualNumberOfImages && intActualNumberOfImages <= intExpectedNumberOfImages+5)
	    	{
	    		Reporter.log("The actual number of images ("+intActualNumberOfImages+") was within the correct range");
	    	}
	    	else
	    	{
	    		int intExpectedNumberOfImagesMinus5 = intExpectedNumberOfImages - 5;
	    		int intExpectedNumberOfImagesPlus5 = intExpectedNumberOfImages + 5;
	    		if(intExpectedNumberOfImagesMinus5 > intActualNumberOfImages)
	    		{clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Expected Number Of Images ("+intExpectedNumberOfImagesMinus5+") was greater than Actual Number Of Images("+intActualNumberOfImages+")");}
	        	else if (intActualNumberOfImages > intExpectedNumberOfImagesPlus5)
	    		{clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Actual Number Of Images ("+intActualNumberOfImages+") was greater than Expected Number Of Images("+intExpectedNumberOfImagesPlus5+")");}
	    	}
  		}
  	}
	public void SENTRYLINK_ValidateImageCountLessThanExpected(Map<String, String> objDictionary,WebDriver driver,int intTotalImageSeconds)
  	{
  		Meter clsMeter = new Meter();
  		String strParkingImageCountViolation = clsMeter.METER_GetPARKING_IMAGE_COUNT_VIOLATION(objDictionary, driver);
  		int intExpectedNumberOfImages = intTotalImageSeconds * 5 + Integer.parseInt(strParkingImageCountViolation)+1;//Violations now get extra (contrast image)
      	List<WebElement> uls = driver.findElements(By.xpath("//div[contains(@class,'jcarousel jcarousel-navigation')]//ul//li"));
	    	int intActualNumberOfImages = uls.size();
	    	int intExpectedNumberOfImagesMinus4 = intExpectedNumberOfImages - 4;
		if (intActualNumberOfImages < intExpectedNumberOfImagesMinus4)
		{Reporter.log("The actual number of images ("+intActualNumberOfImages+") was less then expected ("+intExpectedNumberOfImagesMinus4+")");}
		else
		{clsMeter.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The actual number of images ("+intActualNumberOfImages+") was greater then expected ("+intExpectedNumberOfImagesMinus4+")");}
	}
	public int SENTRYLINK_ReturnAwaitingPhotoCount(WebDriver driver,String strReturnType)
  	{
  	 	int intFailCounter = 0;
  		int intPassCounter = 0;
  		List<WebElement> li = driver.findElements(By.xpath("//div[contains(@class,'jcarousel jcarousel-navigation')]//ul//li"));
      	for (int i = 1; i<=li.size(); i=i+1)
 		{	
    		String strImageAlt = driver.findElement(By.xpath("//div[contains(@class,'jcarousel jcarousel-navigation')]//ul//li[" + i+ "]//img")).getAttribute("alt");
    		if (strImageAlt.equals("Vehicle photo default"))
  		{intFailCounter++;}
  		else
  		{intPassCounter++;}
 		}
      	if(strReturnType.equals("Pass"))
      	{return intPassCounter;}
      	else 
      	{return intFailCounter;}
  	}
