		clsCommonWeb.SENTRYLINK_NavigateToPage2(objDictionary, driver, strCurrentPageName, "Rate Block Group","Local");
		//Calculate and Update Free Parking
		//clsCommonWeb.SENTRYLINK_SetRateBlocksFree(objDictionary,driver,strFreeTimeMinutes, strMinutesOfFreeTimeBeforeCurrentTime); 
		clsCommonWeb.SENTRYLINK_SetRateBlocksNoParking(objDictionary,driver,strMinutesBeforeNoParking, strNoParkingTimeMinutes,"0");
