		String strReservationBlockGroupNbr = objDictionary.get("strReservationBlockGroup").replace("ReservationRateBlockGroup", "");
		String strMeterGroup = objDictionary.get("strMeterGroup");
		String strMeterName = objDictionary.get("strMeterName");
		String strPermitStartTimePlusMinusMinutes = objDictionary.get("strPermitStartTimePlusMinusMinutes");if(strPermitStartTimePlusMinusMinutes == null) {strPermitStartTimePlusMinusMinutes = "";}
		String strPermitEndTimePlusMinusMinutes = objDictionary.get("strPermitEndTimePlusMinusMinutes");if(strPermitEndTimePlusMinusMinutes == null) {strPermitEndTimePlusMinusMinutes = "";}
		// String strReservationBlockGroup =
		// objDictionary.get("strReservationBlockGroup");
		String strReservationParkingPermitRateBlock = "";
		if(!strReservationBlockGroupNbr.equals(""))
		{
			 strReservationParkingPermitRateBlock = "ReservationParkingRateBlock" + strReservationBlockGroupNbr;
		}
		String strEmail = strUniqueId + strMunicipality.replace(" ", "").replace(",", "") + "parker" + "@gmail.com";
		// Calculate Valid From Date
		String strNbrOfValidFromsDaysFromCurrentDay = objDictionary.get("strNbrOfValidFromsDaysFromCurrentDay");
		if (strNbrOfValidFromsDaysFromCurrentDay == null) {strNbrOfValidFromsDaysFromCurrentDay = "0";}
		String strValidFromDate = AddDaysToCurrentDate("MM/dd/yyyy", strNbrOfValidFromsDaysFromCurrentDay);
		String strValidToDate = AddDaysToCurrentDate("MM/dd/yyyy", "365");
