        String strPermitCost =  objDictionary.get("strPermitCost");if(strPermitCost == null) {strPermitCost = "";}
        Date currentTime = new Date();
        SimpleDateFormat formatter = new SimpleDateFormat("hh:mma");
        String strPermitStartTime = formatter.format(currentTime);
        objDictionary.put("strPermitStartTime", strPermitStartTime);     
        String strPermitEndTime = AddTimeToExistingTime(strPermitStartTime, "0","hh:mma");
