	public String AddTimeToCurrentTime(String strPlusMinutes,String strDateFormat)
	{
		String newTime = "";
		Calendar calendar = Calendar.getInstance();
		SimpleDateFormat sdf = new SimpleDateFormat(strDateFormat);
		try
		{
			Date d = sdf.parse(sdf.format(calendar.getTime())); 
			Calendar cal = Calendar.getInstance();
			cal.setTime(d);
			cal.add(Calendar.MINUTE, Integer.parseInt(strPlusMinutes));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e) {}
		return newTime;
	}
	public String AddTimeToExistingTime(String strTime, String strPlusMinutes,String strDateFormat)
	{
		String newTime = "";
		try
		{
			DateFormat sdf = new SimpleDateFormat(strDateFormat);
			Date startDate = sdf.parse(strTime);
			Calendar cal = Calendar.getInstance();
			cal.setTime(startDate);
			cal.add(Calendar.MINUTE, Integer.parseInt(strPlusMinutes));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e) 
		{
			System.out.println("MIH");
		}
		return newTime;
	}
	public String AddHoursToExistingTime(String strTime, String strPlusHours,String strDateFormat)
	{
		String newTime = "";
		try
		{
			DateFormat sdf = new SimpleDateFormat(strDateFormat);
			Date startDate = sdf.parse(strTime);
			Calendar cal = Calendar.getInstance();
			cal.setTime(startDate);
			cal.add(Calendar.HOUR, Integer.parseInt(strPlusHours));
			newTime = sdf.format(cal.getTime());
		}
		catch(Exception e) 
		{
			System.out.println("MIH");
		}
		return newTime;
	}
	public String ConvertUTCTimeToLocalTime(String strTimeToConvert,String strUTCFormat,String strLocalFormat)
	{
		try 
		{
	 		DateFormat utcFormat = new SimpleDateFormat(strUTCFormat);
	 		utcFormat.setTimeZone(TimeZone.getTimeZone("UTC"));
	 		Date date = utcFormat.parse(strTimeToConvert);
	 		DateFormat pstFormat = new SimpleDateFormat(strLocalFormat);
	 		pstFormat.setTimeZone(TimeZone.getTimeZone("CST"));
	 		return pstFormat.format(date);
		}
		catch (Exception e) 
		{
			System.out.println(e);
		} 
 		return null;
	}
	
	public String ConvertUTCTimeToLocalTimeWithTimeZoneAbbr(String strTimeToConvert, String strUTCFormat, String strLocalFormat, String timeZoneId) 
	{
        try {
            DateFormat utcFormat = new SimpleDateFormat(strUTCFormat);
            utcFormat.setTimeZone(TimeZone.getTimeZone("UTC"));
            Date date = utcFormat.parse(strTimeToConvert);

            DateFormat localFormat = new SimpleDateFormat(strLocalFormat);
            localFormat.setTimeZone(TimeZone.getTimeZone(timeZoneId));

            // Get time zone abbreviation
            TimeZone timeZone = TimeZone.getTimeZone(timeZoneId);
            boolean isDaylightSavingTime = timeZone.inDaylightTime(date);
            String timeZoneAbbreviation = isDaylightSavingTime ? "CDT" : "CST";
            return localFormat.format(date).toLowerCase() + " " + timeZoneAbbreviation;
        } catch (Exception e) {
            System.out.println(e);
        }
        return null;
    }
	
	public String ConvertUTCtoCST_UTC(String strTimeToConvert,String strUTCFormat,String strLocalFormat)throws Exception
	{
 		try
 		{
			DateFormat utcFormat = new SimpleDateFormat(strUTCFormat);
	 		utcFormat.setTimeZone(TimeZone.getTimeZone("UTC"));
	 		Date date = utcFormat.parse(strTimeToConvert);
	 		DateFormat pstFormat = new SimpleDateFormat(strLocalFormat);
	 		pstFormat.setTimeZone(TimeZone.getTimeZone("UTC"));
	 		return pstFormat.format(date);
 		}
 		catch(Exception e)
 		{
 			System.out.println(e);
 		}
 		return "";
	}
	public void ClickAllLinksOn(Map<String, String> objDictionary,WebDriver driver)
	{
		CommonWeb clsCommonWeb = new CommonWeb();
		String strPageName = "";String strLinkText = "";String strHref = "";String strArrayOfLinks = "";String strErrorMessage = "";
		strPageName = clsCommonWeb.GetCurrentPageName(objDictionary, driver);
		List<WebElement> links = driver.findElements(By.tagName("a"));
		//System.out.println(links.size());
		String strCurrentURL = driver.getCurrentUrl();
 		for (int i = 0; i<=links.size(); i=i+1)
 		{
 			try{strLinkText = links.get(i).getText();}catch(Exception e){strLinkText = "";}
 			if(!strLinkText.equals(""))
 			{
 				//Add Link Text to remove from array
 				if(!strLinkText.equals("Purge Decommissioned Meters")){strArrayOfLinks = strArrayOfLinks+"ByText~"+strLinkText+"•";}
 			}
 			else
 			{
 				try{strHref = links.get(i).getAttribute("href");}catch(Exception e){strHref = "";}
 				//Add URL contents to remove from array
 				if(strHref != null && !strHref.equals(strCurrentURL)  && !strHref.contains("logout") && !strHref.contains("activity_feed_items"))
 				{
	 				if(!strHref.equals("")){strArrayOfLinks = strArrayOfLinks+"ByUrl~"+strHref+"•";}
 				}
 			}
 		}
 		strArrayOfLinks = strArrayOfLinks.substring(0, strArrayOfLinks.length()-1);
 		System.out.println(strArrayOfLinks);
 		String[] StrArrayOfLinks = strArrayOfLinks.split("\\•", -1);
 		for (String strLinkValues : StrArrayOfLinks)
        {
			 String[] arrObjectName = strLinkValues.split("~");
			 String strByType = arrObjectName[0];
			 String strLinkValue = arrObjectName[1];
			 if(!strLinkValue.equals("Log Out"))
			 {		
				 switch (strByType)
				 {
				 	case "ByUrl":
				 		driver.navigate().to(strLinkValue);
				 		break;
				 	case "ByText":
				 		driver.findElement(By.linkText(strLinkValue)).click();break;
				 }
				 String strCurrentPageTitle = driver.getTitle();
				 switch (strCurrentPageTitle)
				 {
				 	case "404 Not Found":
				 		switch (strByType)
						{
							case "ByUrl":
								UpdateErrorMessageWithPivotalData(objDictionary,driver,"404 Not Found Page appeared when Navigating to the url ("+strLinkValue+") from the page ("+strPageName+")","Local");
							case "ByText":
								UpdateErrorMessageWithPivotalData(objDictionary,driver,"404 Not Found Page appeared when Clicking the link ("+strLinkValue+") from the page ("+strPageName+")","Local");
						}
				 		break;
				 	case "The page you were looking for doesn't exist (404)":
				 		switch (strByType)
						{
							case "ByUrl":
								UpdateErrorMessageWithPivotalData(objDictionary,driver,"The page you were looking for doesn't exist (404) appeared when navigating to the url ("+strLinkValue+") from the page ("+strPageName+")","Local");
							case "ByText":
								UpdateErrorMessageWithPivotalData(objDictionary,driver,"The page you were looking for doesn't exist (404) appeared when clicking the link ("+strLinkValue+") from the page ("+strPageName+")","Local");
						}
				 		break;
					default:
						try
						{
							driver.findElement(By.xpath("//*[contains(text(), 'Something went wrong.')]"));
							switch (strByType)
							{
								case "ByUrl":
									UpdateErrorMessageWithPivotalData(objDictionary,driver,"Something went wrong appeared when Navigating to the url ("+strLinkValue+") from the page ("+strPageName+")","Local");
								case "ByText":
									UpdateErrorMessageWithPivotalData(objDictionary,driver,"Something went wrong appeared when Clicking the link ("+strLinkValue+") from the page ("+strPageName+")","Local");
							}
					 		break;
						}catch(Exception e){}
						try
						{
							driver.findElement(By.xpath("//*[contains(text(), 'Errors:')]"));
							try {Thread.sleep(2000);}catch (Exception e) {}//Wait for Message to Load
							strErrorMessage = driver.findElement(By.xpath("//div[contains(@class,'alert alert-success')]")).getText().replace("\n", " ");
							if(!strErrorMessage.equals(""))
							{
								switch (strByType)
								{
									case "ByUrl":
										UpdateErrorMessageWithPivotalData(objDictionary,driver,strErrorMessage+" appeared when Navigating to the url ("+strLinkValue+") from the page ("+strPageName+")","Local");
									case "ByText":
										UpdateErrorMessageWithPivotalData(objDictionary,driver,strErrorMessage+" appeared when Clicking the link ("+strLinkValue+") from the page ("+strPageName+")","Local");
								}
						 		break;
							}
						}catch(Exception e){}
						switch (strByType)
						{
							case "ByUrl":
								Reporter.log("Navigating to the url ("+strLinkValue+") from the page ("+strPageName+") was successful"+"");break;
						 	case "ByText":
						 		Reporter.log("Clicking the link ("+strLinkValue+") from the page ("+strPageName+") was successful"+"");break;
						}
				 }
				 String strAfterClickURL = driver.getCurrentUrl();
				 if(!strCurrentURL.equals(strAfterClickURL))
				 {driver.navigate().back();}
				 else
				 {try{driver.findElement(By.linkText(strLinkValue)).click();}catch (Exception e) {}}
			 }
        }
	}
