	public void ClickLink(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strLinkName, int intLinkIndex) {
	    WebElement objLink = GetLinkObj(objDictionary, driver, strPageName, strLinkName, intLinkIndex);

	    if (objLink != null) {
	        String strHref = objLink.getAttribute("href");
	        objDictionary.remove("strHref");
	        objDictionary.put("strHref", strHref);

	        // Wait for the link to be visible
	        WebDriverWait wait = new WebDriverWait(driver, Duration.ofSeconds(10));
	        wait.until(ExpectedConditions.visibilityOf(objLink)); // Ensure the link is visible

	        // Scroll to the link
	        try {
	            if (objLink.isDisplayed()) {
	                ((JavascriptExecutor) driver).executeScript("arguments[0].scrollIntoView({block: 'center', inline: 'nearest'});", objLink);
	                Thread.sleep(500); // Brief wait after scrolling
	            } else {
	                UpdateErrorMessageWithPivotalData(objDictionary, driver, "Link is not displayed - cannot scroll", "Local");
	            }
	        } catch (Exception e) {
	            UpdateErrorMessageWithPivotalData(objDictionary, driver, "Error while trying to scroll - " + e, "Local");
	        }

	        // Attempt to click the link
	        try {
	            wait.until(ExpectedConditions.elementToBeClickable(objLink));
	            try {Thread.sleep(1000);} catch (Exception e) {}
	            objLink.click(); // Attempt to click the link
	            Reporter.log("The Link (" + strLinkName + ") with index (" + intLinkIndex + ") was clicked successfully.");
	        } catch (Exception e) {
	            handleLinkClickException(objDictionary, driver, strLinkName, strHref, e);
	        }
	        strLinkName = ConvertValues(objDictionary, driver, strLinkName);
	        Reporter.log("The Link (" + strLinkName + ") with index (" + intLinkIndex + ") was clicked successfully.");
	    } else {
	        handleLinkNotFound(objDictionary, driver, strLinkName);
	    }

	    // Wait for the page to load if specified
	    String strWaitForPageLoad = objDictionary.get("strWaitForPageLoad");
	    if (strWaitForPageLoad == null) {
	        strWaitForPageLoad = "True";
	    }
	    if (strWaitForPageLoad.equals("True")) {
	        waitForPageLoaded(objDictionary, driver);
	    }
	}

	// Helper method to handle exceptions during link click
	private void handleLinkClickException(Map<String, String> objDictionary, WebDriver driver, String strLinkName, String strHref, Exception e) {
	    if (!e.toString().contains("Element is not clickable at point")) {
	        if (strLinkName.equals("FixedRateBlock")) {
	            // Handles Overlapping RateBlocks
	            String strRateBlockId = objDictionary.get("strRateBlockId"); // Set Before Browser Is Opened
	            String strURL = "/rating/rate_block_groups/" + strRateBlockId;
	            List<WebElement> RateBlocks = driver.findElements(By.xpath("//a[contains(@href,'" + strURL + "')]"));
	            for (WebElement RateBlock : RateBlocks) {
	                if (!strHref.equals(RateBlock.getAttribute("href"))) {
	                    objDictionary.remove("strHref");
	                    objDictionary.put("strHref", RateBlock.getAttribute("href"));
	                    try {
	                        RateBlock.click();
	                        break;
	                    } catch (Exception f) {
	                        // Handle the exception if necessary
	                    }
	                }
	            }
	        } else {
	            UpdateErrorMessageWithPivotalData(objDictionary, driver, "Error Clicking Link - " + e, "Local");
	        }
	    } else {
	        driver.navigate().to(strHref);
	        Reporter.log("The Link (" + strLinkName + ") was redirected to its href.");
	    }
	}
	// Helper method to handle link not found scenarios
	private void handleLinkNotFound(Map<String, String> objDictionary, WebDriver driver, String strLinkName) {
	    if (strLinkName.equals("Next ›")) {
	        UpdateErrorMessageWithPivotalData(objDictionary, driver, "The Link (" + strLinkName + ") did not exist - No more results exist", "Local");
	    } else {
	        UpdateErrorMessageWithPivotalData(objDictionary, driver, "The Link (" + strLinkName + ") did not exist", "Local");
	    }
	}
	public void ClickTableLinkByColumnValue(Map<String, String> objDictionary,WebDriver driver, String strPageName, String strTableName, int intTableIndex, int intColumnNumber, String strTableValue, String strLinkName)
	{
		WebElement objTable = GetTableObj(objDictionary,driver, strPageName, strTableName, intTableIndex);
		if (objTable == null)
		{UpdateErrorMessageWithPivotalData(objDictionary,driver,"The table (" + strTableName + ") with index (" + intTableIndex + ") did not exist)-StoreTableValue","Local");}
		int intRowNumber = 1;
		//System.out.println(objTable.findElements(By.xpath("//tbody/tr")).size());
		if(objTable.findElements(By.xpath("//tbody/tr")).size() > 0)
		{
			List<WebElement> allRows = objTable.findElements(By.xpath("//tbody/tr")); 
			for (WebElement objRow : allRows) 
			{ 
				//System.out.println(objRow.findElements(By.xpath("//tr["+intRowNumber+"]//td")).size());
				if(objRow.findElements(By.xpath("//tr["+intRowNumber+"]//td")).size() > intColumnNumber)
				{
					WebElement objCell = objRow.findElement(By.xpath("./td["+intColumnNumber+"]"));
					//System.out.println(objCell.getText());
					if(objCell.getText().equalsIgnoreCase(strTableValue))
					{
						try
						{
							String strHref = objTable.findElement(By.xpath("//tr["+intRowNumber+"]//a[contains(text(),'"+strLinkName+"')]")).getAttribute("href");
							WebElement element = objTable.findElement(By.xpath("//tr["+intRowNumber+"]//a[contains(text(),'"+strLinkName+"')]"));
							
							
							 // Instantiate the Actions class
				        	Actions actions = new Actions(driver);
				        	// Move to the element
				        	actions.moveToElement(element).perform();
				        	Thread.sleep(500);
							element.click();
							Reporter.log("The link ("+strLinkName+") in row ("+intRowNumber+") of the ("+strTableName+") table was clicked successfully"+"");
							objDictionary.remove("strHref");objDictionary.put("strHref", strHref);
							if(strTableName.equals("Users") && strLinkName.equals("Edit"))
							{	
								String strRole = objDictionary.get("strRole");
								strWaitObjects = "{ListboxContains} User Roles~"+strRole;intWaitTime = 15;
								DynamicObjectWait(objDictionary, driver, "EditUser");
							}
							else if(strTableName.equals("Users") && strLinkName.equals("Destroy"))
							{Thread.sleep(2000);driver.switchTo().alert().accept();}
							return;
						}
						catch(Exception e)
						{UpdateErrorMessageWithPivotalData(objDictionary,driver,"The link ("+strLinkName+") in row ("+intRowNumber+") of the ("+strTableName+") table did not exist","Local");}
				    }
				}
			    intRowNumber++;
			}
			UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Value ("+strTableValue+") did not exist in the ("+strTableName+") Table","Local");
        }
		else
		{UpdateErrorMessageWithPivotalData(objDictionary,driver,"There was no rows in the ("+strTableName+") table","Local");}
	}
	public void DeletePreviousScreenShot(ITestResult testResult) throws Exception 
	{
		String strScreenShotName = "";
		String strPackageWithTestCaseName = "";
		try 
		{
			strPackageWithTestCaseName = testResult.getTestClass().getName();
			String strMethodName = testResult.getName();
			String strXmlBrowserName = testResult.getTestClass().getXmlTest().getParameter("strBrowser");
			String strXmlTestName = testResult.getTestClass().getXmlTest().getName();
			if(strXmlBrowserName == null){strScreenShotName = strPackageWithTestCaseName+"."+strMethodName;}
			else 
			{
				if(strXmlTestName != null){strScreenShotName = strPackageWithTestCaseName+"."+strMethodName+"."+strXmlTestName+"."+strXmlBrowserName;}
				else{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName+"."+strXmlBrowserName;}
			}
			File directory = new File(".");
			String strPath = directory.getCanonicalPath() +"/ScreenShots/"+ strScreenShotName+".png";
			try
	    		{
		    		File file = new File(strPath);
		    		if(file.delete()){System.out.println(file.getName() + " is deleted!");}
		    		else{System.out.println("Delete operation is failed.");}
		    	}catch(Exception e)
	    		{e.printStackTrace();}
		} catch(Exception e) {}
    }
	public void PopulateAction(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strAction, String strObjectNames, String strObjectValues) 
	{	
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strPageURL = GetPageURL(objDictionary, driver, strPageName);
		String strMobileChrome = objDictionary.get("strMobileChrome");if(strMobileChrome == null) {strMobileChrome = "False";}
		if(strMobileChrome == "False"){driver = SeleniumSwitchBrowser(objDictionary,driver,strPageName, strPageURL);}
		String[] arrObjectNames = strObjectNames.split("\\|", -1);
		String[] arrObjectValues = strObjectValues.split("\\|", -1);
		int intCounter = 0;		
		String strObjectnameWithValues = "";
		for (String strObjectName : arrObjectNames)
        {
			String[] arrObjectName = strObjectName.split("}");
			String strObjectType = arrObjectName[0].substring(1);
			strObjectName = arrObjectName[1].substring(1);
	        if(!arrObjectValues[intCounter].equals(""))
	        {
	        	switch (strObjectType)
	             {
	             	case "CB":
	             		PopulateCheckbox(objDictionary, driver, strPageName, strObjectName, arrObjectValues[intCounter]);
	             		break;
	             	case "L":
	             	case "UDL":
	             		PopulateListbox(objDictionary, driver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	case "T":
	             		PopulateTextfield(objDictionary, driver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	case "RB":
	             		PopulateRadioButton(objDictionary, driver, strPageName, strObjectName, arrObjectValues[intCounter]);
	                    break;
	             	default:
	             		UpdateErrorMessageWithPivotalData(objDictionary,null,"The Object Type(" + strObjectType + ") does not exist or has not been coded-"+strMethondName,"Local");
	             		break;
	             }
             }
             strObjectnameWithValues = strObjectnameWithValues+"|"+strObjectName+","+arrObjectValues[intCounter];
             intCounter++;
        }
		strObjectnameWithValues = strObjectnameWithValues.substring(1);
		String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
		if (strStoredPopulateVariable != null)                        
        {
			Reporter.log("The (" + strAction.replaceAll("Populate ", "") + ") field(s) were populated correctly (" + strStoredPopulateVariable + ") - Values("+strObjectnameWithValues+")"+"");
		 	objDictionary.remove("strStoredPopulateVariable");
        }
        else
        { Reporter.log("The (" + strAction.replaceAll("Populate ", "") + ") field(s) were populated correctly - Values("+strObjectnameWithValues+")"+"");}
 	}
