	public void PopulateTextfield(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strObjectName, String strObjectValue)
	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
		WebElement objTextField = GetTextFieldObj(objDictionary,driver,strPageName,strObjectName);
		strObjectValue = ConvertValues(objDictionary, driver, strObjectValue);
		if (strTextfieldPopulateType == "JQueryTextField")
		{
			strTextfieldPopulateType = "";
			if (driver instanceof JavascriptExecutor)
			{try{((JavascriptExecutor)driver).executeScript("window.document.getElementById('"+strJQueryFilter+"').value = \""+strObjectValue+"\";");}catch(Exception e){}}
			else
			{UpdateErrorMessageWithPivotalData(objDictionary,null,"This driver does not support JavaScript!-"+strMethodName,"Local");}
			strTextfieldPopulateType = "";strJQueryFilter = "";
		}
		else
		{
		    if (objTextField != null)
		    {
	    		try{objTextField.clear();}
		    	catch(Exception e){Reporter.log("Unable to Clear the Textfield ("+strObjectName+") on Page ("+strPageName+")");}
	    		try{
	    			Actions actions = new Actions(driver);
		        	// Move to the element
		        	actions.moveToElement(objTextField).perform();
		        	objTextField.sendKeys(strObjectValue);
		        	if(strObjectName.equals("Province/State")||strObjectName.equals("End Date")||strObjectName.equals("Start Date"))
		        	{
		        		try {Thread.sleep(500);}catch (Exception e) {}
		        		actions.sendKeys(Keys.TAB).perform();
		        	}
		        }
        		catch(Exception e){UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Textfield (" + strObjectName + ")  did not exist-"+strMethodName,"Local");}
		    	if (strTextfieldPopulateType == "TextFieldWithAutoSuggest")
		    	{
		    		//Scroll To Textfield
		    		WebElement element = objTextField;
		    		((JavascriptExecutor) driver).executeScript("arguments[0].scrollIntoView(true);", element);
		    		try {Thread.sleep(1000);}catch (Exception e) {}
		    		//Click Link
		    		try{driver.findElement(By.linkText(strObjectValue)).click();}catch(Exception e)
		    		{UpdateErrorMessageWithPivotalData(objDictionary,null,"Unable To Click Textfield (" + strObjectName + ") -"+strMethodName,"Local");}
		    		strTextfieldPopulateType = "";
		    	}
		    }
		    else
		    {UpdateErrorMessageWithPivotalData(objDictionary,null,"The Textfield (" + strObjectName + ")  did not exist-"+strMethodName,"Local");}
		    driver.switchTo().defaultContent();
		}
		if (strStoreValueAsVariableName != "")
        {
            objDictionary.remove(strStoreValueAsVariableName); objDictionary.put(strStoreValueAsVariableName, strObjectValue);
            String strStoredPopulateVariable = objDictionary.get("strStoredPopulateVariable");
            if (strStoredPopulateVariable != null)
            {objDictionary.remove("strStoredPopulateVariable");objDictionary.put("strStoredPopulateVariable", strStoredPopulateVariable + strStoreValueAsVariableName + ": " + strObjectValue + "|");}
            else
            { objDictionary.put("strStoredPopulateVariable", strStoreValueAsVariableName + ": " + strObjectValue + "|"); }
            strStoreValueAsVariableName = "";
        }
	}
