	public String GetCurrentPageName(Map<String, String> objDictionary, WebDriver driver)
 	{
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
  		waitForPageLoaded(objDictionary,driver);
  		try {Thread.sleep(500);}catch (Exception e) {} 
  		System.out.println(driver.getCurrentUrl());
		String strPageName = objDictionary.get(driver.getCurrentUrl());
		if(strPageName == null)
		{UpdateErrorMessageWithPivotalData(objDictionary,null,"The Url ("+driver.getCurrentUrl()+") has not been added to the objDictionary-"+strMethodName,"Local");}
		return strPageName;
 	}

