	public WebDriver SeleniumSwitchBrowser(Map<String, String> objDictionary, WebDriver driver,String strPageName, String strPageURL)
    {
		String strHandleTitle = "";
		String strHandleUrl= "";
		try
		{
			Set<String>  handles = driver.getWindowHandles();
	        String strPageExistFlag = "False";
	        for(String handle:handles)
	        {
	        	try
	        	{
	        		strHandleTitle= driver.switchTo().window(handle).getTitle();
	    			strHandleUrl= driver.switchTo().window(handle).getCurrentUrl();
	    			System.out.println(strHandleTitle);
	    			System.out.println(strHandleUrl);
	    			System.out.println(strPageURL);
	        		if(strHandleUrl.contains(strPageURL))
		    		{
		    			strPageExistFlag = "True";
		    			driver.switchTo().window(handle).getTitle().equals(strHandleUrl);
		    			//Attempt to wait for page load complete
		    			long timeOut = 5000;
		    		    long end = System.currentTimeMillis() + timeOut;
				        while (System.currentTimeMillis() < end) 
				        {
				            if (String.valueOf(((JavascriptExecutor) driver).executeScript("return document.readyState")).equals("complete")) { break;}
				        }
		    		}
	        		else if(strHandleUrl.contains("rate_block_groups")||strHandleUrl.contains("open_parking_lots")||strHandleUrl.contains("kiosks")||strHandleUrl.contains("rate_sets")||strHandleUrl.contains("meter_groups")||strHandleUrl.contains("ticket_services")||strHandleUrl.contains("devices/meters")||strHandleUrl.contains("csv_reports"))
	        		{
	        			if(strPageURL.contains(strHandleUrl))
			    		{
			    			strPageExistFlag = "True";
			    			driver.switchTo().window(handle).getTitle().equals(strPageURL);
			    			//Attempt to wait for page load complete
			    			long timeOut = 5000;
			    		    long end = System.currentTimeMillis() + timeOut;
					        while (System.currentTimeMillis() < end) 
					        {
					            if (String.valueOf(((JavascriptExecutor) driver).executeScript("return document.readyState")).equals("complete")) { break;}
					        }
			    		}
			    	}
	    		}
	    		catch (Exception e)
	    		{	
	    			System.out.println(e);
	    			System.out.println("MIH");
	    		}
	        }
	        if(strPageExistFlag.equals("False"))
	        {
	        	System.out.println(strHandleTitle);
    			System.out.println(strHandleUrl);
    			System.out.println(strPageURL);
    			UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Page (" + strPageName + ") did not exist-SeleniumSwitchBrowser","Local");
	        }
	        LookForMessageForWarningTheWorkerSubSystemIsReportingSeriousProblems(driver);
		}
		catch (Exception e)
		{
        	UpdateErrorMessageWithPivotalData(objDictionary,driver,"Unable to attach to window handle-SeleniumSwitchBrowser","Local");
        }
        return driver;
    }
	public void LookForMessageForWarningTheWorkerSubSystemIsReportingSeriousProblems(WebDriver driver)
	{
		try 
		{
			driver.findElement(By.xpath("//*[contains(text(),'WARNING! The Worker subsystem is reporting serious problems.  Contact Engineering.')]"));
			String strWarningMessage = "The message: WARNING! The Worker subsystem is reporting serious problems. Contact Engineering.";
			Reporter.log("<font color='yellow'>"+strWarningMessage+"</font>");
		}	
		catch(Exception e) {};
	}

	// Dynamic Waits
	public WebDriver DynamicObjectWait(Map<String, String> objDictionary,WebDriver driver, String strPageName)
    {
		CommonWeb clsCommonWeb = new CommonWeb();
		String strEnvironment = objDictionary.get("strEnvironment");
		String strObjectValue2 = "";String strTimeoutFlag = "False";
		String strMethodName = new Object(){}.getClass().getEnclosingMethod().getName();
        Timestamp currentTime = new Timestamp(System.currentTimeMillis());
        Calendar cal = Calendar.getInstance();
        cal.setTimeInMillis(currentTime.getTime());
        cal.add(Calendar.SECOND, intWaitTime);
        Timestamp endTime = new Timestamp(cal.getTime().getTime());
        if(driver != null) {waitForPageLoaded(objDictionary,driver);}
        do
        {                
            String[] arrWaitObjects = strWaitObjects.split("\\|");
            for (String WaitObject : arrWaitObjects)
            {
                String[] arrWaitObject = WaitObject.split("}");
                String strWaitType = arrWaitObject[0].substring(1);
                String[] arrWaitValue = arrWaitObject[1].trim().split("~");
                int intWaitValueLenght = arrWaitValue.length;
                String strWaitValue = arrWaitValue[0];
                if (intWaitValueLenght == 2) {strObjectValue2 = arrWaitValue[1];}
                strActualWaitType = strWaitType;
                strActualWaitValue = strWaitValue;
                WebElement objName = null;
                switch (strWaitType)
                {
                	case "AccessDenied":
	                	strActualWaitValue = strObjectValue2;
	            		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
	            		if(objName != null)
	            		{
	                		if(objName.getText().contains("Access Denied"))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
	            		}
	                	break;
                	case "ListboxExists":
                		objName = GetListboxObj(objDictionary, driver,strPageName,strWaitValue);
                		if(objName != null){strWaitObjects = "";intWaitTime = 30;return driver;}
                		break;
                	case "ListboxContains":
                		objName = GetListboxObj(objDictionary, driver,strPageName,strWaitValue);
                		if(objName != null)
                		{
                			List<WebElement> options = objName.findElements(By.tagName("option"));
                			for (WebElement option : options)
                			{
                				if(strObjectValue2.equals(option.getText()))
                				{strWaitObjects = "";intWaitTime = 30;return driver;}
                			}
                		}
                		break;
                	case "PageExists":
                		String strUrl = clsCommonWeb.GetPageURL(objDictionary,driver, strWaitValue);
                		try
                		{
                			String strCurrentURL = driver.getCurrentUrl();
                			if(strUrl.equals(strCurrentURL)){strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}catch (Exception e){System.out.println(e+"-"+strMethodName);}
                		break;
                	case "TextExists":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		break;
                	case "YourAccountIsLocked":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("Your account is locked."))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	case "YourAccountHasExpiredDueToInactivity":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("Your account has expired due to inactivity. Please contact the site administrator."))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	case "WARNING! The Worker subsystem is reporting serious problems. Contact Engineering.":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("WARNING! The Worker subsystem is reporting serious problems. Contact Engineering."))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	case "InvalidEmailOrPassword":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("Invalid email, phone number, or password."))//Invalid email, phone number, or password.
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	case "SignInSuccessfully":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("Signed in successfully."))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
	                		else if(objName.getText().contains("Access Denied") && strEnvironment.equals("PROD"))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	case "YouHaveOneMoreAttemptBeforeYourAccountIsLocked":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("You have one more attempt before your account is locked."))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	case "UserIsDeleted":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("User is deleted"))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
//                	case "WaitUntilARateBlockIdIsNotNeg1":
//                		String strRateBlockExistFlag = DynamicObjectWait_WaitUntilARateBlockIdIsNotNeg1(objDictionary);
//                		if(strRateBlockExistFlag.equals("True"))
//                		{return driver;}
//                		break;
//                	case "WaitUntilMeterDisplaysFreeParking":
//                		String strFreeParkingFlag = DynamicObjectWait_WaitUntilMeterDisplaysFreeParking(objDictionary);
//                		if(strFreeParkingFlag.equals("True"))
//                		{return driver;}
//                		break;
                	case "YouNeedToSignInOrSignUpBeforeContinuing":
                		strActualWaitValue = strObjectValue2;
                		objName = GetTextObj(objDictionary, driver, strWaitValue, strObjectValue2);
                		if(objName != null)
                		{
	                		if(objName.getText().contains("You need to sign in or sign up before continuing."))
	                		{strWaitObjects = "";strObjectValue2 = ""; intWaitTime = 30;return driver;}
                		}
	                	break;
                	default:
                		UpdateErrorMessageWithPivotalData(objDictionary,driver,"The strWaitType has not been added-"+strMethodName,"Local");
                }
                currentTime = new Timestamp(System.currentTimeMillis());
                if (currentTime.getTime() > endTime.getTime())
                {UpdateErrorMessageWithPivotalData(objDictionary,driver,"None of the expected objects (" + strWaitObjects + ") existed after (" + intWaitTime + ") seconds","Local");}
            }
        }while (strTimeoutFlag == "False");
		return driver;
    }

	// ************************************************************************************************************************************************************************
	// Global Pay Session sessionLocalMeter, Session sessionRemoteMeter
	// ************************************************************************************************************************************************************************
	public void SENTRYMOBILE_GlobalPay(Map<String, String> objDictionary,String[] arrGlobalPayActions1, String[] arrGlobalPayActions2,Session sessionLocalMeter,Session sessionRemoteMeter,String strRemoteDeviceId)
	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		int intPayAction1Counter = 0;
		int intPayAction2Counter = 0;
		String strActions1Complete = "False";
		String strActions2Complete = "False";
		int intNbrActions1 = arrGlobalPayActions1.length;
		int intNbrActions2 = arrGlobalPayActions2.length;
		String strEndTest = "False";
  		do
		{
			if(intPayAction1Counter <  intNbrActions1)
			{
				//LOCAL SPOTS 1
				String strStartArray = Arrays.toString(arrGlobalPayActions1);
				if(arrGlobalPayActions1[intPayAction1Counter].contains("LS"))
				{
					arrGlobalPayActions1 = clsCommonWeb.SENTRYMOBILE_ProcessGlobalPayAction(objDictionary,sessionLocalMeter,sessionRemoteMeter,strRemoteDeviceId,arrGlobalPayActions1,intPayAction1Counter,"Local","1");
				}
				//REMOTE SPOT 2
				else if(arrGlobalPayActions1[intPayAction1Counter].contains("RS"))
				{
					arrGlobalPayActions1 = clsCommonWeb.SENTRYMOBILE_ProcessGlobalPayAction(objDictionary,sessionLocalMeter,sessionRemoteMeter,strRemoteDeviceId,arrGlobalPayActions1,intPayAction1Counter,"Remote","2");
				}
				String strEndArray = Arrays.toString(arrGlobalPayActions1);
				if(strStartArray.equals(strEndArray)){intPayAction1Counter++;}
			}else {strActions1Complete = "True";}
			
			if(intPayAction2Counter <  intNbrActions2)
			{
				String strStartArray = Arrays.toString(arrGlobalPayActions2);
				//LOCAL SPOTS 1
				if(arrGlobalPayActions2[intPayAction2Counter].contains("LS"))
				{
					arrGlobalPayActions2 = clsCommonWeb.SENTRYMOBILE_ProcessGlobalPayAction( objDictionary,sessionLocalMeter,sessionRemoteMeter,strRemoteDeviceId,arrGlobalPayActions2,intPayAction2Counter,"Local","1");
				}
				//REMOTE SPOT 2
				else if(arrGlobalPayActions2[intPayAction2Counter].contains("RS"))
				{
					arrGlobalPayActions2 = clsCommonWeb.SENTRYMOBILE_ProcessGlobalPayAction(objDictionary,sessionLocalMeter,sessionRemoteMeter,strRemoteDeviceId,arrGlobalPayActions2,intPayAction2Counter,"Remote","2");
				}
				String strEndArray = Arrays.toString(arrGlobalPayActions2);
				if(strStartArray.equals(strEndArray)){intPayAction2Counter++;}
			}else {strActions2Complete = "True";}
			if(strActions1Complete.equals("True") && strActions2Complete.equals("True")){strEndTest = "True";}
		}while (strEndTest.equals("False"));
	}
