	// ************************************************************************************************************************************************************************
	// Global Pay - Process Global Pay Actions
	// ************************************************************************************************************************************************************************
	public String[] SENTRYMOBILE_ProcessGlobalPayAction(Map<String, String> objDictionary,Session sessionLocalMeter, Session sessionRemoteMeter,String strRemoteDeviceId,String[] arrGlobalPayActions, int intPayActionCounter, String strHostType, String strSpotNumber)
	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		Meter clsMeter = new Meter();
  		String strGracePeriodWait = "";
  		strGracePeriodWait = objDictionary.get("strGracePeriodWait"+strHostType+strSpotNumber);if(strGracePeriodWait == null) {strGracePeriodWait = "False";}
		if(strGracePeriodWait.equals("True"))
		{
			Session sessionMeter = null;
			if(strHostType.equals("Local")) {sessionMeter = sessionLocalMeter;}else{sessionMeter = sessionRemoteMeter;}
			//Get Violation Status
			String strViolationValue = clsMeter.METER_GetMeterViolationValue(objDictionary,sessionMeter,strHostType,strSpotNumber);
			if(strViolationValue.equals("True"))
			{
				Reporter.log("<font color='DEEPPINK'>Grace Period Violation Occured on Local Space:"+strHostType+"-Spot: "+strSpotNumber+"</font>");
		  		System.out.println("Spot "+strSpotNumber+" Action: "+arrGlobalPayActions[intPayActionCounter]);
				objDictionary.remove("strGracePeriodWaitLocal1");
				clsCommonWeb.SENTRYLINK_ExecuteGlobalPayAction(objDictionary,sessionLocalMeter, sessionRemoteMeter,strRemoteDeviceId,arrGlobalPayActions[intPayActionCounter],"1",strSpotNumber);
			}
			else
			{
				System.out.println(Arrays.toString(arrGlobalPayActions));
				arrGlobalPayActions = ShiftArrayElementsToTheLeftAndReplaceLastElementWithOriginalElement(arrGlobalPayActions, intPayActionCounter);
				System.out.println(Arrays.toString(arrGlobalPayActions));
			}
		}
		else
		{
			System.out.println("Spot "+strSpotNumber+" Action: "+arrGlobalPayActions[intPayActionCounter]);
			clsCommonWeb.SENTRYLINK_ExecuteGlobalPayAction(objDictionary,sessionLocalMeter, sessionRemoteMeter,strRemoteDeviceId,arrGlobalPayActions[intPayActionCounter],"1",strSpotNumber);
		}
		return arrGlobalPayActions;
	}
