			clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary,null,sessionMeter,strSpotNumber,strHostType);
			strBegunVariable = "False";
			strCurrentMaxRemaining = clsMeter.METER_GetMeterMaxRemaining(objDictionary,sessionMeter,strSpotNumber, strHostType);
