	public void SENTRYMOBILE_GlobalPayCoinPayment(Map<String, String> objDictionary,String strAction, String strSpotNumber, String strHostType, String strLocalMeterSpotName, String strRemoteMeterSpotName)
	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		Meter clsMeter = new Meter();
  		//Translates Action and Add to Dictionary
  		String strExecutedGlobalPayActions = objDictionary.get("strExecutedGlobalPayActions");if(strExecutedGlobalPayActions == null) {strExecutedGlobalPayActions = "";}
  		String strActionDescription = "";
  		Session sessionMeter = null;
  		if(strHostType.equals("Local"))
  		{strActionDescription = "Coin Payment Local Space:"+strLocalMeterSpotName+"-Spot: "+strSpotNumber;}
  		else 
  		{strActionDescription = "Coin Payment Remote Space:"+strRemoteMeterSpotName+"-Spot: "+strSpotNumber;}
  		Reporter.log("<font color='DEEPPINK'>"+strActionDescription+"</font>");
  		objDictionary.put("strExecutedGlobalPayActions", strExecutedGlobalPayActions+"<br>"+strActionDescription);
  		clsMeter.METER_GetMemory(objDictionary, strHostType);
  		clsMeter.METER_GetUptime(objDictionary,strHostType,"BeforeCoinPayment");
  		clsMeter.StoreDumpStackValuesInDictionary(objDictionary, null, strSpotNumber, strHostType, "Before");
  		//Get Current Parked Status
		String strBegunVariable = objDictionary.get("strBegunVariable");
		String strMaintenanceModeEnabled = objDictionary.get("strMaintenanceModeEnabled");
		String strMaxRemaining = objDictionary.get("strMaxRemaining");
		//Add Rate Blocks To Automation Results
		clsMeter.SENTRYMETER_AddRateBlocksToAutomationResults(objDictionary,strHostType);
		if(strMaintenanceModeEnabled.equals("False") && strBegunVariable.equals("False"))
		{
			Reporter.log("Coin Payment 1A");
			//Park Spot
			clsMeter.METER_ParkSpot(objDictionary,sessionMeter,strSpotNumber,strHostType);
			
			
			
			clsMeter.METER_ParkSpot(objDictionary,strSpotNumber,strHostType);
			
			
			//Enter Space Number
			SENTRYMOBILE_GlobalPay_EnterSpaceNumber(objDictionary,strHostType, strLocalMeterSpotName, strRemoteMeterSpotName);
			//Coin Payment
			clsMeter.METER_InsertCoin(objDictionary, null,strSpotNumber,strHostType);
			//Store Parking Id
			HttpConnections clsHttpConnections = new HttpConnections();
			clsHttpConnections.HTTPCONNECTIONS_StoreParkingSessionId(objDictionary, strHostType, strSpotNumber);
	  	}	
		else if(strMaintenanceModeEnabled.equals("True") && strBegunVariable.equals("True") || strMaintenanceModeEnabled.equals("False") && strBegunVariable.equals("True"))
		{
			Reporter.log("Coin Payment 2A");
			//Disable Maintenance Mode Before Inserting Payment
			if(strMaintenanceModeEnabled.equals("True"))
			{
				String strMaintenanceMode = objDictionary.get("strMaintenanceMode");
				if(!strMaintenanceMode.equals("UnenforcedParking"))//User can add payment when maintenance mode Unenforced is enabled
				{
					//Remove Maintenance Mode
					clsCommonWeb.SENTRYLINK_UpdateMaintenanceMode(objDictionary,"Disable",strSpotNumber,"",strHostType);
				}
			}
			//Get Current Max Remaining
			if(strMaxRemaining.equals("0"))
			{
				//Exit Spot
				clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary, null, strSpotNumber,strHostType);
				//Park Spot
				clsMeter.METER_ParkSpot(objDictionary, null,strSpotNumber,strHostType);
				//Store Parking Session Id
				HttpConnections clsHttpConnections = new HttpConnections();
				clsHttpConnections.HTTPCONNECTIONS_StoreParkingSessionId(objDictionary, strHostType, strSpotNumber);
			}
			//Enter Space Number
			SENTRYMOBILE_GlobalPay_EnterSpaceNumber(objDictionary,strHostType, strLocalMeterSpotName, strRemoteMeterSpotName);
			//Coin Payment
			clsMeter.METER_InsertCoin(objDictionary, null,strSpotNumber,strHostType);
		}
		else if(strMaintenanceModeEnabled.equals("True") && strBegunVariable.equals("False"))
		{
			Reporter.log("Coin Payment 3A");
			//Meter Should Only Allow Payment for Maint. Unenforced
			clsCommonWeb.SENTRYLINK_UpdateMaintenanceMode(objDictionary,"Disable",strSpotNumber,"",strHostType);
			//Enter Space Number
			SENTRYMOBILE_GlobalPay_EnterSpaceNumber(objDictionary,strHostType, strLocalMeterSpotName, strRemoteMeterSpotName);
			//Coin Payment
			clsMeter.METER_InsertCoin(objDictionary, null,strSpotNumber,strHostType);
		}
	}

