	public void SENTRYMOBILE_GlobalPayCoinPaymentPresumedOccupied(Map<String, String> objDictionary,Session sessionLocalMeter,Session sessionRemoteMeter,String strAction,String strSpotNumber,String strHostType)
	{
  		CommonWeb clsCommonWeb = new CommonWeb();
  		Meter clsMeter = new Meter();
  		HttpConnections clsHttpConnections = new HttpConnections();
		//Translates Action and Add to Dictionary
  		String strLogMessageSyncDisabled = objDictionary.get("strLogMessageSyncDisabled");if(strLogMessageSyncDisabled == null) {strLogMessageSyncDisabled = "False";}
  		String strUISyncDisabled = objDictionary.get("strUISyncDisabled");if(strUISyncDisabled == null) {strUISyncDisabled = "False";}
  		String strPaymentSyncDisabled = objDictionary.get("strPaymentSyncDisabled");if(strPaymentSyncDisabled == null) {strPaymentSyncDisabled = "False";}
  		String strExecutedGlobalPayActions = objDictionary.get("strExecutedGlobalPayActions");if(strExecutedGlobalPayActions == null) {strExecutedGlobalPayActions = "";}
  		//Get Device Id
  		String strDeviceId = "";String strHost = "";
  		if(strHostType.equals("Local")){strDeviceId = objDictionary.get("strDeviceId");strHost = objDictionary.get("strHost");}
  		else if(strHostType.contains("Remote")){strDeviceId = objDictionary.get("strRemoteDeviceId"+strHostType.substring(strHostType.length() - 1));strHost = objDictionary.get("strRemoteHost"+strHostType.substring(strHostType.length() - 1));}
  		String[] arrLocalMeterSpots = strDeviceId.split("-");
		//Get Spot Name
  		String strSpotName = "";if(strSpotNumber.equals("1")){strSpotName = arrLocalMeterSpots[0];}else{int intSpotName = Integer.parseInt(arrLocalMeterSpots[0]) + Integer.parseInt(strSpotNumber) - 1;strSpotName = Integer.toString(intSpotName);}
		Session sessionMeter = null;String strActionDescription = "";
  		if(strHostType.equals("Local")){strActionDescription = "Coin Payment Local Space Presumed Occupied:"+strSpotName+",LogMessageSyncDisabled: "+strLogMessageSyncDisabled+",strUISyncDisabled: "+strUISyncDisabled+",strPaymentSyncDisabled: "+strPaymentSyncDisabled+"-Spot: "+strSpotNumber+" Host: "+strHost;sessionMeter = sessionLocalMeter;}
  		else {strActionDescription = "Coin Payment Remote Space Presumed Occupied:"+strSpotName+",LogMessageSyncDisabled: "+strLogMessageSyncDisabled+",strUISyncDisabled: "+strUISyncDisabled+",strPaymentSyncDisabled: "+strPaymentSyncDisabled+"-Spot: "+strSpotNumber+" Host: "+strHost;sessionMeter = sessionRemoteMeter;}
  		Reporter.log("<font color='DEEPPINK'>"+strActionDescription+"</font>");
  		objDictionary.put("strExecutedGlobalPayActions", strExecutedGlobalPayActions+"<br>"+strActionDescription);
  		clsMeter.METER_GetMemory(objDictionary,sessionLocalMeter,strHostType);
  		clsMeter.METER_GetUptime(objDictionary,sessionLocalMeter,sessionRemoteMeter,strHostType,"BeforeCoinPayment");
  		clsMeter.StoreDumpStackValuesInDictionary(objDictionary, null,sessionMeter,strSpotNumber, strHostType, "Before");
  		//Get Current Parked Status
		String strBegunVariable = objDictionary.get("strBegunVariable");
		String strMaintenanceModeEnabled = objDictionary.get("strMaintenanceModeEnabled");
		String strCurrentMaxRemaining = objDictionary.get("strMaxRemaining");
		String strViolation = objDictionary.get("strViolation");
		if(strViolation.equals("True"))
		{
			//Remove Violation
			Reporter.log("Space ("+strDeviceId+") was in Violation");
			clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary,null,sessionMeter,strSpotNumber,strHostType);
			strBegunVariable = "False";
			strCurrentMaxRemaining = clsMeter.METER_GetMeterMaxRemaining(objDictionary,sessionMeter,strSpotNumber, strHostType);
		}
		String strParkingSpotState1 = clsHttpConnections.HTTPCONNECTIONS_StoreParkingSpotState(objDictionary,strHostType,strSpotNumber);
  		if(strBegunVariable.equals("True")  && !strParkingSpotState1.equals("PARKING_STATE_VALID_PRESUMED_OCCUPIED"))//Expected PARKING_STATE_INIT_GRACE_PERIOD,PARKING_STATE_MAINT_FREE_OCCUPIED
		{
			Reporter.log("Parking was not in Presumbed Occupied-Clear Space");
			clsMeter.SENTRYMETER_ShortSessionWaitExitSpot(objDictionary,null,sessionMeter,strSpotNumber,strHostType);
			clsMeter.StoreDumpStackValuesInDictionary(objDictionary, null,sessionMeter,strSpotNumber, strHostType, "Before");
	  		//Get Current Parked Status
			strBegunVariable = objDictionary.get("strBegunVariable");
			strMaintenanceModeEnabled = objDictionary.get("strMaintenanceModeEnabled");
			strCurrentMaxRemaining = objDictionary.get("strMaxRemaining");
			strViolation = objDictionary.get("strViolation");
		}
		//Add Rate Blocks To Automation Results
		clsMeter.SENTRYMETER_AddRateBlocksToAutomationResults(objDictionary,sessionLocalMeter,strHostType);
		//Add Coin Payment - Presumed Occuppied
		if(strMaintenanceModeEnabled.equals("False"))
		{
			Reporter.log("Presumed Occupied-Coin Payment");
			//Enter Space Number
			SENTRYMOBILE_GlobalPay_EnterSpaceNumber(objDictionary,sessionLocalMeter,strHostType,strSpotName);
			//Coin Payment
			clsMeter.METER_InsertCoin(objDictionary,null,sessionLocalMeter,sessionRemoteMeter,strSpotNumber,strHostType);
			//Validate Presumed Occupied
			String strParkingSpotState2 = clsHttpConnections.HTTPCONNECTIONS_StoreParkingSpotState(objDictionary,strHostType,strSpotNumber);
      		if(strParkingSpotState2.contains("PARKING_STATE_VALID_PRESUMED_OCCUPIED"))
      		{Reporter.log("The parking spot state equalled ("+strParkingSpotState2+")");}
      		else
      		{
      			//The below step "park" is used to clear the spot so subsequent tests don't fail
      			clsMeter.METER_ExecutePythonScriptAgainstMeter(objDictionary,sessionMeter,strHostType,"testauto_vehicle_detection_control.py -o SPOT_"+strSpotNumber);	
    			UpdateErrorMessageWithPivotalData(objDictionary,null,"The parking spot state did not equal (PARKING_STATE_VALID) -actual value ("+strParkingSpotState2+")",strHostType);
      		}
      	}	
		else if(strMaintenanceModeEnabled.equals("True"))
		{
			//Reporter.log("Coin Payment 2");
			if(strMaintenanceModeEnabled.equals("True")||strCurrentMaxRemaining.equals("0"))
			{
				//Disable Maintenance Mode Before Inserting Payment
				if(strMaintenanceModeEnabled.equals("True"))
				{
					String strMaintenanceMode = objDictionary.get("strMaintenanceMode");
					if(!strMaintenanceMode.equals("UnenforcedParking"))//User can add payment when maintenance mode Unenforced is enabled
					{
						//Remove Maintenance Mode
						clsCommonWeb.SENTRYLINK_UpdateMaintenanceMode(objDictionary,sessionMeter,"Disable",strSpotNumber,"",strHostType);
						try {Thread.sleep(3000);}catch (Exception e) {} 
					}
				}
			}
			String strParkingSpotState3 = clsHttpConnections.HTTPCONNECTIONS_StoreParkingSpotState(objDictionary,strHostType,strSpotNumber);
	  		
			if(strParkingSpotState1.equals("PARKING_STATE_MAINT_FREE_OCCUPIED"))
			{
				//strParkingSpotState3
				System.out.println("Valid strParkingSpotState3 equals PARKING_STATE_EMPTY");
			}
			else
			{
				System.out.println("What is the current Status");
			}
			
			//PARKING_STATE_EMPTY
			
			//Enter Space Number
			SENTRYMOBILE_GlobalPay_EnterSpaceNumber(objDictionary,sessionLocalMeter,strHostType,strSpotName);
			//Coin Payment
			clsMeter.METER_InsertCoin(objDictionary, null,sessionLocalMeter,sessionRemoteMeter,strSpotNumber,strHostType);
			//Validate Presumed Occupied
			String strParkingSpotState4 = clsHttpConnections.HTTPCONNECTIONS_StoreParkingSpotState(objDictionary,strHostType,strSpotNumber);
      		if(strParkingSpotState4.contains("PRESUMED_OCCUPIED"))
      		{Reporter.log("The parking spot state equalled ("+strParkingSpotState4+")");}
      		else
      		{UpdateErrorMessageWithPivotalData(objDictionary,null,"The parking spot state did not equal (PARKING_STATE_VALID) -actual value ("+strParkingSpotState4+")",strHostType);}
		}
	}
