	public String StoreTableValueHREF(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strTableName, int intTableIndex, String strVariableName, String strRowNumber, String strColumnNumber) {
	    String strMethondName = new Object() {}.getClass().getEnclosingMethod().getName();
	    WebElement objTable = GetTableObj(objDictionary, driver, strPageName, strTableName, intTableIndex);
	    strRowNumber = ConvertValues(objDictionary, driver, strRowNumber);
	    strColumnNumber = ConvertValues(objDictionary, driver, strColumnNumber);
	    int intRowNumber = Integer.parseInt(strRowNumber);
	    int intColumnNumber = Integer.parseInt(strColumnNumber);
	    String strCellHREF = "";

	    if (objTable == null) {
	        UpdateErrorMessageWithPivotalData(objDictionary, driver, "The table (" + strTableName + ") with index (" + intTableIndex + ") did not exist)-" + strMethondName, "Local");
	        return strCellHREF;
	    }
	    try {
	        int intRowCount = 1;
	        if (objTable.findElements(By.xpath("./tbody/tr")).size() > 0) {
	            List<WebElement> allRows = objTable.findElements(By.xpath("./tbody/tr"));
	            for (WebElement objRow : allRows) {
	                if (intRowNumber == intRowCount) {
	                    if (objRow.findElements(By.xpath(".//td")).size() > intColumnNumber) {
	                        WebElement objCell = objRow.findElement(By.xpath("./td[" + intColumnNumber + "]"));
	                        
	                        // Check if the cell contains a link
	                        List<WebElement> links = objCell.findElements(By.tagName("a"));
	                        if (!links.isEmpty()) {
	                            strCellHREF = links.get(0).getAttribute("href"); // Get the href of the first link
	                        } else {
	                            strCellHREF = objCell.getText(); // Fallback if there's no link
	                        }

	                        objDictionary.remove(strVariableName);
	                        objDictionary.put(strVariableName, strCellHREF);
	                        Reporter.log("The table href (" + strCellHREF + ") from row (" + intRowNumber + ") column (" + intColumnNumber + ") in the table (" + strTableName + ") was stored as variable name (" + strVariableName + ")");
	                        return strCellHREF;
	                    }
	                }
	                intRowCount++;
	            }
	            UpdateErrorMessageWithPivotalData(objDictionary, driver, "There was no row (" + intRowNumber + ") with column (" + strColumnNumber + ") in the (" + strTableName + ") table-" + strMethondName, "Local");
	        }
	    } catch (Exception e) {
	        UpdateErrorMessageWithPivotalData(objDictionary, driver, "There was an error retrieving href from row (" + intRowNumber + ") with column (" + strColumnNumber + ") in the (" + strTableName + ") table-" + strMethondName, "Local");
	    }
	    return strCellHREF;
	}
