	public String StoreText(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strTextName, int intTextIndex, String strVariableName)
	{
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		String strPageURL = GetPageURL(objDictionary, driver, strPageName);
		driver = SeleniumSwitchBrowser(objDictionary,driver,strPageName, strPageURL);
		String strTextValue = "";
		WebElement objText = GetTextObj(objDictionary, driver, strPageName, strTextName);
		if (objText == null){UpdateErrorMessageWithPivotalData(objDictionary,driver,"The stored page text (" + strTextName + ") with index (" + intTextIndex + ") did not exist-"+strMethondName,"Local");}
		switch (strTextName)
	    {
			case "Canvas Picture-Entrance Picture":
				switch (strSpecialInstruction)
                {
					case "alt":
						strTextValue = objText.getAttribute("alt");
                        break;
                    default:
                        strTextValue = objText.getText().replace("\n", "").replace("\r", "").trim();
                        break;
                 }
				break;
			case "Violation Id":
				strTextValue = objText.getText().replace("Violation ", "").trim();
				break;
			default:
				if (!objText.getText().equals(""))
                {
					switch (strSpecialInstruction)
                    {
						case "alt":
							strTextValue = objText.getAttribute("alt");
                            break;
                    	case "outerText":
                    		strTextValue = objText.getAttribute("outerText");
                            break;
                        default:
                            strTextValue = objText.getText().replace("\n", "").replace("\r", "").trim();
                            break;
                     }
                 }
	    }
		objDictionary.remove(strVariableName);objDictionary.put(strVariableName, strTextValue);
		Reporter.log("The text name (" + strTextName + ") value (" + strTextValue + ") was stored as variable name (" + strVariableName + ")");
		return strTextValue;
	}
