	public void VerificationPointLinkDropdown(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strLinkName, int intLinkIndex, String strLinkItems)
    {  
		CommonWeb clsCommonWeb = new CommonWeb();
		try 
		{
			//Validate Users Link and dropdown items.
			WebElement  objLink = GetLinkObj(objDictionary, driver, strPageName, strLinkName,intLinkIndex);
			objLink.click();
			WebElement dropdownMenu = driver.findElement(By.xpath("//ul[@class='dropdown-menu show']"));
		    // Retrieve all the items within the dropdown menu and store them in a list
	        List<WebElement> items = dropdownMenu.findElements(By.tagName("a")); // Assuming the items are represented by <a> tags, modify the tag name if necessary
	        String strDropDownItems = "";
	        for (WebElement item : items)
	        {
	        	strDropDownItems = strDropDownItems + "|" + item.getText();
	        }
	        strDropDownItems = strDropDownItems.substring(1);
	        //Validate the Expected Items in the expected order exist
	        if(strDropDownItems.equals(strLinkItems))
	        {Reporter.log("The Link ("+strLinkName+") Dropdown correctly contained the links ("+strDropDownItems+")");}
	        else
	        {clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Link ("+strLinkName+") Dropdown  did not contain (" + strLinkItems + ") - actual value (" + strDropDownItems + ")","Local");}
	        objLink.click();
	  	}
		catch(Exception e)
		{
			clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Link ("+strLinkName+") didn't contain dropdown links","Local");
		}
    }
