	public String ConditionalStepButton(Map<String, String> objDictionary, WebDriver driver, String strPageName, String strButtonName, int intButtonIndex, String strValidationType, String strTextVaue)
    {
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		CommonWeb clsCommonWeb = new CommonWeb();
		WebElement objButton = GetButtonObj(objDictionary, driver, strPageName, strButtonName,intButtonIndex);
		if (objButton != null)
        {   
            switch (strValidationType)
            {
                case "Disabled":
                    if (!objButton.isEnabled()) { return "True"; } else { return "False"; }
                case "Does Not Exist":
                    return "False";
                case "Enabled":
                    if (objButton.isEnabled()) { return "True"; } else { return "False"; } 
                case "Exists":
                    return "True";
                case "Visible":
                    if (objButton.isDisplayed()) { return "True"; } else { return "False"; } 
                case "Visible-Class":
                	System.out.println(objButton.getAttribute("class").toString());
                	if(objButton.getAttribute("class").toString().contains("ng-hide"))
                	{ return "False"; } 
                	else 
                	{ return "True"; } 
                case "Invisible":
                    if (objButton.isDisplayed()) 
                    { return "True"; } 
                    else 
                    { return "False"; }
                default:
                	clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The validation type (" + strValidationType + ") hasn't been coded yet-"+strMethondName,"Local");
            }
        }
        else
        {
            switch (strValidationType)
            {
                case "Does Not Exist":
                    return "True";
                case "Exists":
                    return "False";
                default:
                	clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The button (" + strButtonName + ") at index (" + intButtonIndex + ") did not exist, so it could not perform the (" + strValidationType + ") validation-"+strMethondName,"Local");
            }
        }
        return "";
    }
