	public String ConditionalStepTable(Map<String, String> objDictionary,WebDriver driver, String strPageName, String strTableName, int intTableIndex, String strValidationType, String strTableVaue, int intRowNumber, int intColumnNumber)
    {
		String strMethondName = new Object(){}.getClass().getEnclosingMethod().getName();
		CommonWeb clsCommonWeb = new CommonWeb();
		WebElement objTable = GetTableObj(objDictionary,driver, strPageName, strTableName, intTableIndex);
		if (objTable == null){clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The table (" + strTableName + ") with index (" + intTableIndex + ") did not exist-"+strMethondName,"Local");}
		switch (strValidationType)
        {
			case "ColumnValueExists":
				intRowNumber = 1;
				if(objTable.findElements(By.xpath("//tbody/tr")).size() > 0)
				{
					WebElement objTableRow = objTable.findElement(By.xpath("//tr["+intRowNumber+"]")); 
					if(objTableRow.findElements(By.xpath("//tr["+intRowNumber+"]//td")).size() >= intColumnNumber)
					{
						List<WebElement> allRows = objTable.findElements(By.xpath("//tr["+intRowNumber+"]")); 
						for (WebElement row : allRows) 
						{ 
						 	List<WebElement> cells = row.findElements(By.xpath("//td["+intColumnNumber+"]"));
						    for (WebElement cell : cells)
						    {
						    	System.out.print(cell.getText());
						    	if(cell.getText().equalsIgnoreCase(strTableVaue))	
						    	{return "True";}
						    }
						}
					}
				}
//				else
//				{clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"There was no rows in the ("+strTableName+") table-"+strMethondName);}
				return "False";
			case "ColumnValueContains":
				intRowNumber = 1;
				if(objTable.findElements(By.xpath("//tbody/tr")).size() > 0)
				{
					WebElement objTableRow = objTable.findElement(By.xpath("//tr["+intRowNumber+"]")); 
					if(objTableRow.findElements(By.xpath("//tr["+intRowNumber+"]//td")).size() >= intColumnNumber)
					{
						List<WebElement> allRows = objTable.findElements(By.xpath("//tr["+intRowNumber+"]")); 
						for (WebElement row : allRows) 
						{ 
						 	List<WebElement> cells = row.findElements(By.xpath("//td["+intColumnNumber+"]"));
						    for (WebElement cell : cells){if(cell.getText().contains(strTableVaue)){return "True";}}
						}
					}
				}
				else
				{clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"There was no rows in the ("+strTableName+") table-"+strMethondName,"Local");}
				return "False";
			default:
				clsCommonWeb.UpdateErrorMessageWithPivotalData(objDictionary,driver,"The Table validation type (" + strValidationType + ") hasn't been coded yet-"+strMethondName,"Local");
		}
		return "";
    }
