	public void ClearBrowserCache(WebDriver driver)
    {
	    driver.manage().deleteAllCookies();;
	    try {Thread.sleep(5000);}catch (Exception e) {} 
	}
	public void TakeWebScreenShot(Map<String, String> objDictionary, WebDriver driver) 
	{
	    Meter clsMeter = new Meter();
	    clsMeter.METER_SetMeterEndTime(objDictionary);
	    if (driver != null) {
	        try {
	            // Augment the WebDriver for screenshot capabilities
	            WebDriver augmentedDriver = new Augmenter().augment(driver);

	            // Capture screenshot
	            File screenshot = ((TakesScreenshot) augmentedDriver).getScreenshotAs(OutputType.FILE);

	            // Define the file path for saving the screenshot
	            String strPath = Paths.get("").toAbsolutePath().toString() + "/ScreenShots/Error.png";
	            File file = new File(strPath);

	            // Copy the screenshot to the defined file path
	            FileUtils.copyFile(screenshot, file);

	            // Upload the screenshot to Imgur and get the URL
	            String strImageURL = ImgurClient.getInstance().UploadImage(file, "WebScreenshot " + Instant.now());

	            // Check if the image URL is valid and log it
	            if (ImgurClient.getLastUrl() != null) {
	                strPath = ImgurClient.getLastUrl();
	                Reporter.log("<a href=\"" + strPath + "\">Web Screen Shot</a>");
	                Reporter.log("<img src=\"" + strPath + "\" alt=\"\"/><br />");
	            }
	        } catch (IOException e) {
	            Reporter.log("Error taking web screenshot: " + e.getMessage());
	        } catch (Exception e) {
	            Reporter.log("Unexpected error: " + e.getMessage());
	        }
	    } else {
	        Reporter.log("Unable to take screenshot: driver is null.");
	    }
	}
	
	
	public static void setWarningMsg(String text)
  	{
  	    Toolkit.getDefaultToolkit().beep();
  	    JOptionPane optionPane = new JOptionPane(text,JOptionPane.WARNING_MESSAGE);
  	    JDialog dialog = optionPane.createDialog("Warning!");
  	    dialog.setAlwaysOnTop(true);
  	    dialog.setVisible(true);
  	}
	public void TakeScreenShoot(WebDriver driver, ITestResult testResult, ITestNGMethod testMethod, ITestContext context) throws Exception 
	{
    	WebDriver augmentedDriver = new Augmenter().augment(driver);
		File screenshot = ((TakesScreenshot) augmentedDriver).getScreenshotAs(OutputType.FILE);
		String strPackageWithTestCaseName = testResult.getTestClass().getName();
		String strMethodName = testResult.getName();
		String strXmlBrowserName = testResult.getTestClass().getXmlTest().getParameter("strBrowser");
		String strXmlTestName = testResult.getTestClass().getXmlTest().getName();
		String strScreenShotName = "";
		if(strXmlBrowserName == null)
		{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName;}
		else
		{
			if(strXmlTestName != null)
			{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName+"."+strXmlTestName+"."+strXmlBrowserName;}
			else
			{strScreenShotName = strPackageWithTestCaseName+"."+strMethodName+"."+strXmlBrowserName;}
		}
		File directory = new File(".");
		String strPath = directory.getCanonicalPath() +"/ScreenShots/"+ strScreenShotName+".png";
		//Delete Existing Screenshot
		File file = new File(strPath);
		if(file.delete()){System.out.println(file.getName() + " is deleted!");}
		else{System.out.println("Delete operation is failed.");}
		FileUtils.copyFile(screenshot, new File(strPath));
		Reporter.log("<a href=" + strPath + " target='_blank' >" + strScreenShotName + "</a>");
	}

